RG.DESCS = {"ひばりヶ丘":{"x":"ひばりヶ丘駅は、東京都西東京市住吉町三丁目にある、西武鉄道池袋線の駅である。駅番号はSI13。","d":"東京都西東京市にある西武鉄道の駅","t":"ひばりヶ丘駅"},"お台場海浜公園":{"x":"お台場海浜公園駅は、東京都港区台場二丁目にある、ゆりかもめ東京臨海新交通臨海線の駅である。駅番号はU 06。港区内の駅では最も東にある。","d":"東京都港区台場にあるゆりかもめの駅","t":"お台場海浜公園駅"},"あざみ野":{"x":"あざみ野駅は、神奈川県横浜市青葉区あざみ野二丁目にある、東急電鉄と横浜市営地下鉄の駅である。","d":"神奈川県横浜市青葉区にある東急電鉄・横浜市交通局の駅","t":"あざみ野駅"},"たまプラーザ":{"x":"たまプラーザ駅は、神奈川県横浜市青葉区美しが丘一丁目にある、東急電鉄田園都市線の駅。横浜市で最北端に位置する駅である。愛称はたまプラ。","d":"神奈川県横浜市青葉区美しが丘にある東急電鉄の駅","t":"たまプラーザ駅"},"とうきょうスカイツリー":{"x":"とうきょうスカイツリー駅は、東京都墨田区押上一丁目にある、東武鉄道伊勢崎線の駅である。「東武スカイツリーライン」の愛称区間に含まれている。駅番号はTS 02。","d":"東京都墨田区押上一丁目にある東武鉄道の駅","t":"とうきょうスカイツリー駅"},"センター北":{"x":"センター北駅は、神奈川県横浜市都筑区中川中央一丁目にある、横浜市交通局の駅。ブルーラインとグリーンラインの2路線が乗り入れる。駅番号はブルーラインがB30、グリーンラインがG05。","d":"神奈川県横浜市都筑区中川中央にある横浜市交通局の駅","t":"センター北駅"},"センター南":{"x":"センター南駅は、神奈川県横浜市都筑区茅ケ崎中央にある、横浜市交通局の駅である。ブルーラインとグリーンラインの2路線が乗り入れる。駅番号はブルーラインがB29、グリーンラインがG04。","d":"神奈川県横浜市都筑区茅ケ崎中央にある横浜市交通局の駅","t":"センター南駅"},"つつじヶ丘":{"x":"つつじヶ丘駅は、東京都調布市西つつじケ丘三丁目にある、京王電鉄京王線の駅。京王中央管区所属。駅番号はKO14。","d":"東京都調布市西つつじヶ丘にある京王電鉄の駅","t":"つつじヶ丘駅"},"みのり台":{"x":"みのり台駅は、千葉県松戸市松戸新田にある、京成電鉄松戸線の駅である。駅番号はKS85。","d":"千葉県松戸市松戸新田にある京成電鉄の駅","t":"みのり台駅"},"お花茶屋":{"x":"お花茶屋駅は、東京都葛飾区宝町二丁目にある、京成電鉄本線の駅である。駅番号はKS08。","d":"東京都葛飾区宝町二丁目にある京成電鉄の駅","t":"お花茶屋駅"},"テレコムセンター":{"x":"テレコムセンター駅は、東京都江東区青海二丁目にある、ゆりかもめ東京臨海新交通臨海線の駅である。駅番号はU 09。江東区最南端の駅である。","d":"東京都江東区青海にあるゆりかもめの駅","t":"テレコムセンター駅"},"アーティゾン美術館":{"x":"アーティゾン美術館は、東京都中央区京橋にある私立美術館。公益財団法人石橋財団が運営している。 2019年7月1日にブリヂストン美術館 (ブリヂストンびじゅつかん、英: Bridgestone Museum of Art）から改称し、2020年1月18日にミュージアムタワー京橋内で新たにオープンした。","d":"東京都中央区にある私立美術館","t":"アーティゾン美術館"},"サントリー美術館":{"x":"サントリー美術館 は、東京都港区赤坂九丁目東京ミッドタウンにある、日本の古美術が中心の私立美術館。運営は公益財団法人サントリー芸術財団。","d":"東京都港区の東京ミッドタウンにある美術館","t":"サントリー美術館"},"みずほ台":{"x":"みずほ台駅は、埼玉県富士見市東みずほ台二丁目にある、東武鉄道東上本線の駅である。駅番号はTJ 16。","d":"埼玉県富士見市東みずほ台にある東武鉄道の駅","t":"みずほ台駅"},"サントリーホール":{"x":"サントリーホールは、東京都港区赤坂一丁目にあるコンサートホール。アークヒルズの一画に1986年10月12日に開館した。敷地は森ビルが、建物は森ビルとサントリーホールディングスが所有し、公益財団法人サントリー芸術財団が運営する。","d":"東京・赤坂にあるコンサートホール","t":"サントリーホール"},"インブリー館":{"x":"インブリー館は、宣教師で明治学院神学部教授のウィリアム・インブリーが長年住んでいたことで知られる日本の東京都内に現存する最古の宣教師館であり、明治学院大学白金キャンパス構内に位置する。1964年に「ひきや」された後はおもに学院の同窓会事務所や教員用の会議室として利用されている。 1998年に国の重要文化財に指定された。","d":"東京都の明治学院大学白金キャンパスにある宣教師館","t":"インブリー館"},"デジタル庁":{"x":"デジタル庁は、日本の行政機関のひとつ。デジタル社会の形成に関する内閣の事務を内閣官房と共に助け、その行政事務の迅速かつ重点的な遂行を図ることを目的として内閣に置かれる。2021年9月1日に発足した。","d":"日本の行政機関","t":"デジタル庁"},"モノレール浜松町":{"x":"浜松町駅は、東京都港区にある、東日本旅客鉄道の駅である。 本項では、ほぼ同位置に所在する東京モノレール羽田空港線のモノレール浜松町駅についても扱う。 所在地は、JR東日本が海岸一丁目、東京モノレールが浜松町二丁目となっている。","d":"東京都港区にある東日本旅客鉄道・東京モノレールの駅","t":"浜松町駅"},"三ノ輪橋":{"x":"三ノ輪橋停留場は、東京都荒川区南千住一丁目にある東京都交通局都電荒川線の停留場。駅番号はSA 01。 都電荒川線の始発停留場であり、停留場位置は日光街道の西側やや奥にある。","d":"東京都荒川区南千住にある都電荒川線の停留場","t":"三ノ輪橋停留場"},"三ノ輪":{"x":"三ノ輪駅は、東京都台東区三ノ輪二丁目にある、東京地下鉄日比谷線の駅である。駅番号はH 20。台東区最北端の駅である。","d":"東京都台東区にある東京地下鉄の駅","t":"三ノ輪駅"},"三河島":{"x":"三河島駅は、東京都荒川区西日暮里一丁目にある、東日本旅客鉄道常磐線の駅である。駅番号はJJ 03。","d":"東京都荒川区西日暮里にある東日本旅客鉄道の駅","t":"三河島駅"},"万世橋":{"x":"万世橋駅は、かつて東京府に存在した、国鉄中央本線と東京地下鉄道の駅である。 駅名は神田川に架かる万世橋に由来する。 本項は双方の駅について扱う。","d":"かつて東京都に存在した駅","t":"万世橋駅"},"三越前":{"x":"三越前駅は、東京都中央区日本橋室町にある、東京地下鉄の駅。","d":"東京都中央区にある東京地下鉄の駅","t":"三越前駅"},"三軒茶屋":{"x":"三軒茶屋駅は、東京都世田谷区太子堂に所在する、東急電鉄の駅・停留場である。親会社の東急が管理する複合ビルであるキャロットタワーに直結している。 駅名の「三軒茶屋」は行政地名としては当駅南側一帯の範囲となっており、当駅の正式な所在地は太子堂となっている。","d":"日本の鉄道駅","t":"三軒茶屋駅"},"ニコライ堂":{"x":"ニコライ堂は東京都千代田区神田駿河台にある正教会の大聖堂。「ニコライ堂」は通称であり、日本に正教会の教えをもたらしたロシア人修道司祭聖ニコライに由来する。 正式名称は「東京復活大聖堂」であり、イイスス・ハリストスの復活を記憶する大聖堂である。","d":"東京都千代田区にある大聖堂","t":"ニコライ堂"},"一之江":{"x":"一之江駅は、東京都江戸川区一之江八丁目にある、東京都交通局新宿線の駅である。駅番号はS 18。","d":"東京都江戸川区一之江にある東京都交通局の駅","t":"一之江駅"},"三郷中央":{"x":"三郷中央駅は、埼玉県三郷市中央一丁目にある、首都圏新都市鉄道つくばエクスプレスの駅。駅番号はTX09。","d":"埼玉県三郷市中央にある首都圏新都市鉄道の駅","t":"三郷中央駅"},"三井記念美術館":{"x":"三井記念美術館は、東京都中央区日本橋室町にある、旧財閥三井家の伝来品を収蔵展示するために設立された、公益財団法人三井文庫が運営する私立美術館である。","d":"東京都中央区日本橋にある美術館","t":"三井記念美術館"},"三井本館":{"x":"三井本館は東京都中央区日本橋室町に所在する三井不動産の本社ビルであり、同社が保有するオフィスビルである。三井越後屋の跡地に旧三井財閥の本拠として建てられた。また、團琢磨暗殺事件の現場でもある。","d":"東京都中央区日本橋にあるビル","t":"三井本館"},"リゾートゲートウェイ・ステーション":{"x":"リゾートゲートウェイ・ステーション駅は、千葉県浦安市舞浜にある、ディズニーリゾートラインの駅である。東日本旅客鉄道の舞浜駅と近接しており、乗換駅となっている。旅客案内上は、リゾートゲートウェイ・ステーションと呼称される。","d":"千葉県浦安市にある舞浜リゾートラインの駅","t":"リゾートゲートウェイ・ステーション駅"},"ベイサイド・ステーション":{"x":"ベイサイド・ステーション駅は、千葉県浦安市舞浜にある、ディズニーリゾートラインの駅である。東京ディズニーリゾート・オフィシャルホテル群の最寄り駅。旅客案内上は、ベイサイド・ステーションと呼称される。","d":"千葉県浦安市にある舞浜リゾートラインの駅","t":"ベイサイド・ステーション駅"},"三田演説館":{"x":"三田演説館は、東京都港区三田の慶應義塾大学三田キャンパスに所在する演説講堂で、今日の慶應義塾において福澤諭吉の存命中から存在する唯一の建造物である。日本の重要文化財指定建造物。","d":"慶應義塾大学内にある演説講堂","t":"三田演説館"},"三河島水再生センター":{"x":"三河島水再生センターは、東京都荒川区荒川にある東京都下水道局の下水処理施設。1922年に稼動を開始した日本で最初の近代的な下水処理場である。旧喞筒場施設が国の重要文化財に指定されている。","d":"東京都荒川区にある下水処理場","t":"三河島水再生センター"},"三越日本橋本店":{"x":"日本橋三越本店は、東京都中央区日本橋室町に所在する、三越伊勢丹が運営する百貨店。三越ブランドの本店である。","d":"東京・日本橋の百貨店","t":"三越日本橋本店"},"上野":{"x":"上野駅は、東京都台東区にある、東日本旅客鉄道・東京地下鉄の駅。 1883年に日本鉄道の駅として開業。山手線北東部のターミナル駅であり、北関東や東北地方・北陸地方へ至る列車が数多く集結することから、古くから東京の北の玄関口として機能してきた。","d":"東京の鉄道駅","t":"上野駅"},"三鷹":{"x":"三鷹駅は、東京都三鷹市下連雀三丁目にある、東日本旅客鉄道中央本線の駅である。八王子支社管轄の駅。","d":"東京都三鷹市下連雀にある東日本旅客鉄道の駅","t":"三鷹駅"},"三鷹の森ジブリ美術館":{"x":"三鷹の森ジブリ美術館は、東京都三鷹市の井の頭恩賜公園西園内にある、三鷹市立のアニメーション美術館。正式名称は三鷹市立アニメーション美術館。指定管理者は公益財団法人徳間記念アニメーション文化財団。","d":"日本のアニメーション美術館","t":"三鷹の森ジブリ美術館"},"上板橋":{"x":"上板橋駅は、東京都板橋区上板橋二丁目にある、東武鉄道東上本線の駅である。駅番号はTJ 07である。","d":"東京都板橋区上板橋にある東武鉄道の駅","t":"上板橋駅"},"上石神井":{"x":"上石神井駅は、東京都練馬区上石神井一丁目にある、西武鉄道新宿線の駅。駅番号はSS13。練馬区最南端の駅である。","d":"東京都練馬区にある西武鉄道の駅","t":"上石神井駅"},"上野恩賜公園":{"x":"上野恩賜公園は、東京都台東区にある公園。通称上野公園。上野駅西口に位置している。","d":"東京都の公園","t":"上野恩賜公園"},"上北沢":{"x":"上北沢駅は、東京都世田谷区上北沢四丁目にある、京王電鉄京王線の駅である。京王東管区所属。駅番号はKO09。","d":"東京都世田谷区上北沢にある京王電鉄の駅","t":"上北沢駅"},"下井草":{"x":"下井草駅は、東京都杉並区下井草二丁目にある西武鉄道新宿線の駅。駅番号はSS10。","d":"東京都杉並区にある西武鉄道の駅","t":"下井草駅"},"三鷹台":{"x":"三鷹台駅は、東京都三鷹市井の頭一丁目にある、京王電鉄井の頭線の駅である。井の頭北管区所属。駅番号はIN15。","d":"東京都三鷹市井の頭にある京王電鉄の駅","t":"三鷹台駅"},"上野動物園東園":{"x":"上野懸垂線は、東京都台東区上野にある恩賜上野動物園内において東京都交通局が運行していたモノレール路線である。上野動物園東園駅と上野動物園西園駅を結んでいた。上野動物園モノレールや上野モノレールと通称されていた。","d":"上野動物園内を走っていたモノレール","t":"東京都交通局上野懸垂線"},"上本郷":{"x":"上本郷駅は、千葉県松戸市上本郷にある、京成電鉄松戸線の駅である。駅番号はKS87。","d":"千葉県松戸市上本郷にある京成電鉄の駅","t":"上本郷駅"},"上野広小路":{"x":"上野広小路駅は、東京都台東区上野三丁目にある、東京地下鉄銀座線の駅。駅番号はG 15。台東区最西端の駅。","d":"東京都台東区にある東京地下鉄の駅","t":"上野広小路駅"},"上野御徒町":{"x":"上野御徒町駅は、東京都台東区上野五丁目にある、東京都交通局大江戸線の駅である。駅番号はE 09。","d":"東京都台東区にある東京都交通局の駅","t":"上野御徒町駅"},"下丸子":{"x":"下丸子駅は、東京都大田区下丸子三丁目にある、東急電鉄東急多摩川線の駅である。駅番号はTM04。","d":"東京都大田区下丸子にある東急電鉄の駅","t":"下丸子駅"},"上野毛":{"x":"上野毛駅は、東京都世田谷区上野毛一丁目にある、東急電鉄大井町線の駅である。駅番号はOM14。","d":"東京都世田谷区上野毛にある東急電鉄の駅","t":"上野毛駅"},"上町":{"x":"上町駅は、東京都世田谷区世田谷3丁目にある、東急電鉄世田谷線の停留場である。駅番号はSG06。","d":"東京都世田谷区世田谷にある東急電鉄の駅","t":"上町駅"},"上野東照宮":{"x":"上野東照宮は、東京都台東区上野恩賜公園内にある神社。旧社格は府社。その豪華さや由来から三大東照宮の一つに数えられることが多い。","d":"東京都台東区の神社","t":"上野東照宮"},"上井草":{"x":"上井草駅は、東京都杉並区上井草三丁目にある西武鉄道新宿線の駅である。駅番号はSS12。杉並区の駅では最も北にある。","d":"東京都杉並区にある西武鉄道の駅","t":"上井草駅"},"上中里":{"x":"上中里駅は、東京都北区上中里一丁目にある、東日本旅客鉄道の駅である。駅番号はJK 35。 乗り入れている路線は、線路名称上は東北本線であるが、当駅には電車線を走る京浜東北線電車のみが停車し、旅客案内では「東北線」とは案内されていない。","d":"東京都北区上中里にある東日本旅客鉄道の駅","t":"上中里駅"},"両国":{"x":"両国駅は、東京都墨田区横網一丁目にある、東日本旅客鉄道・東京都交通局の駅である。","d":"東京都墨田区にある東日本旅客鉄道・東京都交通局の駅","t":"両国駅"},"下板橋":{"x":"下板橋駅は、東京都豊島区池袋本町四丁目にある東武鉄道東上本線の駅である。駅番号はTJ 03。","d":"東京都豊島区池袋本町にある東武鉄道の駅","t":"下板橋駅"},"下高井戸":{"x":"下高井戸駅は、東京都世田谷区松原三丁目にある、京王電鉄の駅および東急電鉄の停留場である。","d":"東京都世田谷区松原にある京王電鉄・東急電鉄の駅","t":"下高井戸駅"},"中延":{"x":"中延駅は、東京都品川区にある、東急電鉄・東京都交通局の駅。 駅所在地は東急が中延四丁目、都営地下鉄が東中延二丁目となっている。","d":"東京都品川区にある東急電鉄・東京都交通局の駅","t":"中延駅"},"世田谷代田":{"x":"世田谷代田駅は、東京都世田谷区代田二丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 08。","d":"東京都世田谷区代田にある小田急電鉄の駅","t":"世田谷代田駅"},"下赤塚":{"x":"下赤塚駅は、東京都板橋区赤塚新町一丁目にある東武鉄道東上本線の駅である。駅番号はTJ 09。 東京地下鉄有楽町線・副都心線の地下鉄赤塚駅が近接しているが、乗り換えの案内は行われていない。","d":"東京都板橋区赤塚新町にある東武鉄道の駅","t":"下赤塚駅"},"中井":{"x":"中井駅は、東京都新宿区にある、西武鉄道・東京都交通局の駅である。 所在地は西武鉄道が中落合一丁目、東京都交通局が上落合二丁目である。","d":"東京都新宿区にある西武鉄道・東京都交通局の駅","t":"中井駅"},"不動前":{"x":"不動前駅は、東京都品川区西五反田五丁目にある、東急電鉄目黒線の駅である。駅番号はMG02。","d":"東京都品川区西五反田にある東急電鉄の駅","t":"不動前駅"},"下落合":{"x":"下落合駅は、東京都新宿区下落合一丁目にある、西武鉄道新宿線の駅。駅番号はSS03。 駅名にある「落合」は、神田川と妙正寺川の合流点から生じた地名。","d":"東京都新宿区にある西武鉄道の駅","t":"下落合駅"},"下神明":{"x":"下神明駅は、東京都品川区西品川一丁目にある、東急電鉄大井町線の駅である。駅番号はOM02。","d":"東京都品川区西品川にある東急電鉄の駅","t":"下神明駅"},"中村橋":{"x":"中村橋駅は、東京都練馬区中村北四丁目にある、西武鉄道池袋線の駅である。駅番号はSI07。","d":"東京都練馬区にある西武鉄道の駅","t":"中村橋駅"},"世田谷":{"x":"世田谷駅は、東京都世田谷区世田谷四丁目にある、東急電鉄世田谷線の停留場である。駅番号はSG05。","d":"東京都世田谷区世田谷にある東急電鉄の駅","t":"世田谷駅"},"下北沢":{"x":"下北沢駅は、東京都世田谷区北沢二丁目にある、小田急電鉄・京王電鉄の駅である。 新宿と渋谷の二大繁華街に鉄道で直結していることから、当駅周辺の下北沢も「シモキタ」と通称されるにぎやかな商業地となっている。","d":"東京都世田谷区北沢にある小田急電鉄・京王電鉄の駅","t":"下北沢駅"},"下総国分寺":{"x":"下総国分寺は、千葉県市川市にある真言宗豊山派の寺院。山号は国分山。本尊は薬師如来。","d":"千葉県市川市にある寺院","t":"下総国分寺"},"世田谷代官屋敷":{"x":"世田谷代官屋敷は、彦根藩世田谷領の代官を世襲した大場家の私邸かつ役宅で、大場代官屋敷とも呼ばれる。現在の東京都世田谷区世田谷1丁目に置かれた。1952年に東京都指定史跡に、1978年に大場家住宅主屋及び表門の二棟が重要文化財に指定された。","d":"東京都世田谷区にある、彦根藩の代官大場家の役宅","t":"世田谷代官屋敷"},"下布田遺跡":{"x":"下布田遺跡は、東京都調布市布田にある縄文時代晩期の集落遺跡。国の史跡に指定され、土製耳飾が国の重要文化財に指定されている。調布市内にある縄文時代の遺跡としては特に著名であり、なおかつ東京都を代表する縄文時代の遺跡といえる。","d":"東京都調布市にある縄文時代の集落遺跡","t":"下布田遺跡"},"中目黒":{"x":"中目黒駅は、東京都目黒区上目黒三丁目にある、東急電鉄・東京地下鉄の駅である。 目黒区の駅では最も東に位置し、同区の行政・商業・交通の中心的な駅として機能している。東京メトロの駅としては唯一目黒区に所在する。","d":"東京都目黒区にある東急電鉄・東京地下鉄の駅","t":"中目黒駅"},"亀有":{"x":"亀有駅は、東京都葛飾区亀有三丁目にある東日本旅客鉄道常磐線の駅である。駅番号はJL 20。緩行線のみホームがあり、各駅停車のみが停車する。","d":"東京都葛飾区亀有にある東日本旅客鉄道の駅","t":"亀有駅"},"九品仏":{"x":"九品仏駅は、東京都世田谷区奥沢七丁目にある、東急電鉄大井町線の駅である。駅番号はOM11。","d":"東京都世田谷区奥沢にある東急電鉄の駅","t":"九品仏駅"},"中野坂上":{"x":"中野坂上駅は、東京都中野区にある、東京地下鉄・東京都交通局の駅。 東京メトロの駅は本町二丁目に、東京都交通局の駅は中央二丁目にそれぞれ所在する。","d":"東京都中野区にある東京地下鉄・東京都交通局の駅","t":"中野坂上駅"},"中野島":{"x":"中野島駅は、神奈川県川崎市多摩区中野島三丁目にある、東日本旅客鉄道南武線の駅である。駅番号はJN 15。","d":"神奈川県川崎市多摩区中野島にある東日本旅客鉄道の駅","t":"中野島駅"},"二子新地":{"x":"二子新地駅は、神奈川県川崎市高津区二子二丁目にある、東急田園都市線の駅である。駅番号はDT-08。","d":"神奈川県川崎市高津区二子にある東急電鉄の駅","t":"二子新地駅"},"久我山":{"x":"久我山駅は、東京都杉並区久我山四丁目にある、京王電鉄井の頭線の駅である。井の頭北管区所属。駅番号はIN14。","d":"東京都杉並区久我山にある京王電鉄の駅","t":"久我山駅"},"九段下":{"x":"九段下駅は、東京都千代田区にある、東京地下鉄・東京都交通局の駅である。","d":"東京都千代田区にある東京地下鉄・東京都交通局の駅","t":"九段下駅"},"久地":{"x":"久地駅は、神奈川県川崎市高津区久地四丁目にある、東日本旅客鉄道南武線の駅である。駅番号はJN 12。","d":"神奈川県川崎市高津区久地にある東日本旅客鉄道の駅","t":"久地駅"},"中野新橋":{"x":"中野新橋駅は、東京都中野区弥生町二丁目にある、東京地下鉄丸ノ内線の駅である。駅番号はMb 05。","d":"日本の東京都中野区弥生町にある東京地下鉄の駅","t":"中野新橋駅"},"乃木坂":{"x":"乃木坂駅は、東京都港区南青山一丁目にある、東京地下鉄千代田線の駅。駅番号はC 05。 駅名は赤坂八・九丁目に存在する東京都道413号赤坂杉並線の「乃木坂」に由来する。","d":"東京都港区にある東京地下鉄の駅","t":"乃木坂駅"},"中野富士見町":{"x":"中野富士見町駅は、東京都中野区弥生町五丁目にある、東京地下鉄丸ノ内線の駅である。駅番号はMb 04。中野区最南端の駅。","d":"日本の東京都中野区弥生町にある東京地下鉄の駅","t":"中野富士見町駅"},"中板橋":{"x":"中板橋駅は、東京都板橋区弥生町にある、東武鉄道東上本線の駅である。駅番号はTJ 05。","d":"東京都板橋区弥生町にある東武鉄道の駅","t":"中板橋駅"},"亀戸水神":{"x":"亀戸水神駅は、東京都江東区亀戸八丁目にある、東武鉄道亀戸線の駅である。駅番号はTS 43。江東区最北端の駅である。","d":"東京都江東区亀戸にある東武鉄道の駅","t":"亀戸水神駅"},"久が原":{"x":"久が原駅は、東京都大田区南久が原二丁目にある、東急電鉄池上線の駅である。駅番号はIK11。","d":"東京都大田区南久が原にある東急電鉄の駅","t":"久が原駅"},"中里貝塚":{"x":"中里貝塚は、東京都北区上中里にある貝塚。国の史跡に指定されている。縄文時代の「水産加工場」と大々的に報道された。","t":"中里貝塚"},"亀甲山古墳":{"x":"亀甲山古墳は、東京都大田区田園調布にある古墳。形状は前方後円墳。荏原台古墳群を構成する古墳の1つ。","d":"東京都大田区にある古墳","t":"亀甲山古墳"},"亀戸":{"x":"亀戸駅は、東京都江東区亀戸五丁目にある、東日本旅客鉄道・東武鉄道の駅。","d":"東京都江東区亀戸にある東日本旅客鉄道・東武鉄道の駅","t":"亀戸駅"},"代々木":{"x":"代々木駅は、東京都渋谷区代々木一丁目にある、東日本旅客鉄道・東京都交通局の駅である。","d":"東京都渋谷区にある東日本旅客鉄道・東京都交通局の駅","t":"代々木駅"},"代々木上原":{"x":"代々木上原駅は、東京都渋谷区西原三丁目にある、小田急電鉄・東京地下鉄の駅である。駅番号は小田急電鉄がOH 05、東京メトロがC 01。","d":"東京都渋谷区西原にある小田急電鉄・東京地下鉄の駅","t":"代々木上原駅"},"二子玉川":{"x":"二子玉川駅は、東京都世田谷区玉川二丁目にある、東急電鉄の駅である。","d":"東京都世田谷区玉川にある東急電鉄の駅","t":"二子玉川駅"},"代官山":{"x":"代官山駅は、東京都渋谷区代官山町にある、東急電鉄東横線の駅である。駅番号はTY02。","d":"東京都渋谷区代官山町にある東急電鉄の駅","t":"代官山駅"},"仲町台":{"x":"仲町台駅は、神奈川県横浜市都筑区仲町台一丁目にある、横浜市営地下鉄ブルーラインの駅である。駅番号はB28。","d":"神奈川県横浜市都筑区仲町台にある横浜市交通局の駅","t":"仲町台駅"},"代田橋":{"x":"代田橋駅は、東京都世田谷区大原二丁目にある、京王電鉄京王線の駅である。世田谷区最北端の駅である。京王東管区所属。","d":"東京都世田谷区大原にある京王電鉄の駅","t":"代田橋駅"},"仙川":{"x":"仙川駅は、東京都調布市仙川町一丁目にある、京王電鉄京王線の駅である。京王東管区所属の最西端の駅で、同じ調布市内のつつじヶ丘駅からは京王中央管区となる。駅番号はKO13。","d":"東京都調布市仙川町にある京王電鉄の駅","t":"仙川駅"},"井の頭公園":{"x":"井の頭公園駅は、東京都三鷹市井の頭三丁目にある、京王電鉄井の頭線の駅である。井の頭北管区所属。駅番号はIN16。","d":"東京都三鷹市井の頭にある京王電鉄の駅","t":"井の頭公園駅"},"代々木公園":{"x":"代々木公園駅は、東京都渋谷区富ヶ谷一丁目にある、東京地下鉄千代田線の駅である。駅番号はC 02。","d":"東京都渋谷区にある東京地下鉄の駅","t":"代々木公園駅"},"代々木八幡":{"x":"代々木八幡駅は、東京都渋谷区代々木五丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 04。","d":"東京都渋谷区代々木にある小田急電鉄の駅","t":"代々木八幡駅"},"人形町":{"x":"人形町駅は、東京都中央区日本橋人形町にある、東京地下鉄・東京都交通局の駅。 東京メトロの日比谷線と、都営地下鉄の浅草線が乗り入れる。駅番号は日比谷線がH 14、浅草線がA 14。","d":"東京都中央区にある東京地下鉄・東京都交通局の駅","t":"人形町駅"},"仲御徒町":{"x":"仲御徒町駅は、東京都台東区上野五丁目にある、東京地下鉄日比谷線の駅である。駅番号はH 17。","d":"東京都台東区にある東京地下鉄の駅","t":"仲御徒町駅"},"二重橋前":{"x":"二重橋前駅は、東京都千代田区丸の内二丁目にある、東京地下鉄千代田線の駅である。駅番号はC 10。 基本的に「二重橋前〈丸の内〉駅」と案内される。","d":"東京都千代田区にある東京地下鉄の駅","t":"二重橋前駅"},"五反野":{"x":"五反野駅は、東京都足立区足立三丁目にある東武鉄道伊勢崎線の駅である。「東武スカイツリーライン」の愛称区間に含まれている。駅番号はTS 11。","d":"東京都足立区足立三丁目にある東武鉄道の駅","t":"五反野駅"},"井荻":{"x":"井荻駅は、東京都杉並区下井草五丁目にある、西武鉄道新宿線の駅である。駅番号はSS11。","d":"東京都杉並区にある西武鉄道の駅","t":"井荻駅"},"伴大納言絵詞":{"x":"伴大納言絵詞とは、応天門の変を題材にした平安時代末期の絵巻物。『伴大納言絵巻』ともいう。日本の国宝。","d":"千代田区にある国宝（美術品）","t":"伴大納言絵詞"},"五反田":{"x":"五反田駅は、東京都品川区東五反田一丁目および同二丁目にある、東日本旅客鉄道・東急電鉄・東京都交通局の駅である。","d":"東京都品川区東五反田にある東日本旅客鉄道・東急電鉄・東京都交通局の駅","t":"五反田駅"},"光が丘":{"x":"光が丘駅は、東京都練馬区光が丘二丁目にある、東京都交通局大江戸線の駅である。同線の終着駅。駅番号はE 38。","d":"東京都練馬区光が丘にある東京都交通局の駅","t":"光が丘駅"},"信濃町":{"x":"信濃町駅は、東京都新宿区信濃町にある、東日本旅客鉄道中央本線の駅。駅番号はJB 13。中央本線において起点の神田駅から起算して乗換の無い最初の単独駅でもある。","d":"東京都新宿区信濃町にある東日本旅客鉄道の駅","t":"信濃町駅"},"元住吉":{"x":"元住吉駅は、神奈川県川崎市中原区木月一丁目にある、東急電鉄の駅である。 線路名称上、当駅を通る路線は東横線のみであるが、当駅前後の複々線を利用して東横線の列車と目黒線の列車の2系統が乗り入れており、それぞれ別路線として案内されている。駅番号も個別に与えられており、東横線がTY12、目黒線がMG12である。","d":"神奈川県川崎市中原区木月にある東急電鉄の駅","t":"元住吉駅"},"八丁畷":{"x":"八丁畷駅は、神奈川県川崎市川崎区池田一丁目にある、京浜急行電鉄・東日本旅客鉄道の駅。両社の共同使用駅で、京急の管轄駅である。","d":"神奈川県川崎市川崎区にある京浜急行電鉄・東日本旅客鉄道の駅","t":"八丁畷駅"},"八丁堀":{"x":"八丁堀駅は、東京都中央区八丁堀にある、東京地下鉄・東日本旅客鉄道の駅である。","d":"東京都中央区八丁堀にある東京地下鉄・東日本旅客鉄道の駅","t":"八丁堀駅"},"内幸町":{"x":"内幸町駅は、東京都千代田区内幸町二丁目にある、東京都交通局三田線の駅である。駅番号はI 07。千代田区最南端の駅。","d":"東京都千代田区にある東京都交通局の駅","t":"内幸町駅"},"八幡山":{"x":"八幡山駅は、東京都杉並区上高井戸一丁目にある、京王電鉄京王線の駅である。京王東管区所属、駅番号はKO10。杉並区最南端の駅である。","d":"東京都杉並区上高井戸にある京王電鉄の駅","t":"八幡山駅"},"六本木":{"x":"六本木駅は、東京都港区に所在する、東京地下鉄・東京都交通局の駅。東京メトロの駅は六本木六丁目、都営地下鉄の駅は赤坂九丁目に位置する。 東京メトロの日比谷線と、都営地下鉄の大江戸線が乗り入れる。","d":"東京都港区にある東京地下鉄・東京都交通局の駅","t":"六本木駅"},"六本木一丁目":{"x":"六本木一丁目駅は、東京都港区六本木一丁目にある、東京地下鉄南北線の駅である。駅番号はN 05。","d":"東京都港区にある東京地下鉄の駅","t":"六本木一丁目駅"},"八柱":{"x":"八柱駅は、千葉県松戸市日暮一丁目にある、京成電鉄松戸線の駅である。駅番号はKS84。 東日本旅客鉄道武蔵野線の新八柱駅と同一地点別構内の乗換駅となっている。","d":"千葉県松戸市日暮にある京成電鉄の駅","t":"八柱駅"},"八広":{"x":"八広駅は、東京都墨田区八広六丁目にある、京成電鉄押上線の駅である。駅番号はKS47。","d":"日本の東京都墨田区八広にある京成電鉄の駅","t":"八広駅"},"六町":{"x":"六町駅は、東京都足立区六町四丁目にある、首都圏新都市鉄道つくばエクスプレスの駅。駅番号はTX07。 開業時は普通列車のみの停車駅であったが、駅周辺の開発により利用客が増加し、2012年のダイヤ改正で新設された通勤快速が停車し、さらに2020年のダイヤ改正で上りの通勤快速が当駅に特別停車する区間快速に置き換えられ、朝ラッシュ時の上りに限り全列車の停車駅となった。","d":"東京都足立区六町にある首都圏新都市鉄道の駅","t":"六町駅"},"八潮":{"x":"八潮駅は、埼玉県八潮市大瀬六丁目にある首都圏新都市鉄道つくばエクスプレスの駅。駅番号はTX08。八潮市における唯一の鉄道駅である。","d":"埼玉県八潮市大瀬にある首都圏新都市鉄道の駅","t":"八潮駅"},"保谷":{"x":"保谷駅は、東京都西東京市東町三丁目にある、西武鉄道池袋線の駅である。駅番号はSI12。 駅長室の所在地は西東京市だが、プラットホーム東側の3分の1ほどは練馬区にもまたがっている。","d":"東京都西東京市にある西武鉄道の駅","t":"保谷駅"},"六郷土手":{"x":"六郷土手駅は、東京都大田区仲六郷四丁目にある、京浜急行電鉄本線の駅である。駅番号はKK19。大田区ならびに東京23区内の最南端の駅である。","d":"東京都大田区仲六郷にある京浜急行電鉄の駅","t":"六郷土手駅"},"六義園":{"x":"六義園は、東京都文京区本駒込六丁目にある都立庭園で、「回遊式築山泉水庭園」の日本庭園である。国の特別名勝に指定されている。","d":"東京都文京区本駒込にある都立庭園","t":"六義園"},"初台":{"x":"初台駅は、東京都渋谷区初台一丁目にある、京王電鉄の駅である。京王東管区所属。駅番号はKO02。","d":"東京都渋谷区初台にある京王電鉄の駅","t":"初台駅"},"北小金":{"x":"北小金駅は、千葉県松戸市小金にある、東日本旅客鉄道の駅である。 東日本旅客鉄道の常磐線を走行する常磐緩行線、武蔵野線の1社2路線が乗り入れている。","d":"千葉県松戸市小金にある東日本旅客鉄道の駅","t":"北小金駅"},"北千住":{"x":"北千住駅は、東京都足立区にある、東日本旅客鉄道・東京地下鉄・東武鉄道・首都圏新都市鉄道の駅。 4社5路線が乗り入れるターミナル駅であり、JR常磐線の特急と日比谷線・伊勢崎線のTHライナー以外の全ての旅客列車が停車する。各線相互間の乗換客も多く、1日あたりの乗降人員数は約144万人と国内6位で、横浜駅に次ぐ 。","d":"東京都足立区にある駅","t":"北千住駅"},"北綾瀬":{"x":"北綾瀬駅は、東京都足立区谷中二丁目にある、東京地下鉄千代田線の駅である。駅番号はC 20。同路線の起点である。","d":"東京都足立区谷中二丁目にある東京地下鉄の駅","t":"北綾瀬駅"},"北新横浜":{"x":"北新横浜駅は、神奈川県横浜市港北区北新横浜一丁目にある、横浜市営地下鉄ブルーラインの駅である。駅番号はB26。 当駅周辺地区は、横浜市における都心の一つである「新横浜都心」に指定されている。","d":"神奈川県横浜市港北区北新横浜にある横浜市交通局の駅","t":"北新横浜駅"},"北池袋":{"x":"北池袋駅は、東京都豊島区池袋本町一丁目にある東武鉄道東上本線の駅である。駅番号はTJ 02。 併走する東日本旅客鉄道赤羽線の池袋 - 板橋間にあり、板橋駅や次の下板橋駅が近くにある。","d":"東京都豊島区池袋本町にある東武鉄道の駅","t":"北池袋駅"},"北松戸":{"x":"北松戸駅は、千葉県松戸市上本郷にある、東日本旅客鉄道常磐線の駅である。常磐緩行線の列車が停車する。駅番号はJL 23。","d":"千葉県松戸市上本郷にある東日本旅客鉄道の駅","t":"北松戸駅"},"北朝霞":{"x":"北朝霞駅は、埼玉県朝霞市浜崎一丁目にある、東日本旅客鉄道武蔵野線の駅。駅番号はJM 28。","d":"埼玉県朝霞市にある東日本旅客鉄道の駅","t":"北朝霞駅"},"北戸田":{"x":"北戸田駅は、埼玉県戸田市大字新曽字芦原にある、東日本旅客鉄道の駅である。駅番号はJA 20。 当駅に乗り入れている路線は、線路名称上は東北本線であるが、運転系統上は埼京線として案内される。","d":"埼玉県戸田市にある東日本旅客鉄道の駅","t":"北戸田駅"},"勝どき":{"x":"勝どき駅は、東京都中央区勝どき二丁目にある、東京都交通局大江戸線の駅。駅番号はE 17。中央区最南端の駅。","d":"東京都中央区にある東京都交通局の駅","t":"勝どき駅"},"北国分":{"x":"北国分駅は、千葉県市川市堀之内三丁目にある、北総鉄道北総線の駅である。駅番号はHS03。","d":"千葉県市川市堀之内にある北総鉄道の駅","t":"北国分駅"},"北千束":{"x":"北千束駅は、東京都大田区北千束二丁目にある、東急電鉄大井町線の駅である。駅番号はOM07。","d":"東京都大田区北千束にある東急電鉄の駅","t":"北千束駅"},"勝鬨橋":{"x":"勝鬨橋は、東京都中央区にある隅田川に架かる橋。晴海通りが通る。日本で現存する数少ない可動橋であるが、1980年に機械部への送電を取り止めており、可動部もロックされ、跳開することはない。","d":"東京都の橋","t":"勝鬨橋"},"北参道":{"x":"北参道駅は、東京都渋谷区千駄ヶ谷四丁目にある、東京地下鉄副都心線の駅である。駅番号はF 14。","d":"東京都渋谷区にある東京地下鉄の駅","t":"北参道駅"},"北品川":{"x":"北品川駅は、東京都品川区北品川一丁目にある、京浜急行電鉄本線の駅である。駅番号はKK02。","d":"東京都品川区北品川にある京浜急行電鉄の駅","t":"北品川駅"},"千駄ケ谷":{"x":"千駄ケ谷駅 は、東京都渋谷区千駄ヶ谷一丁目にある、東日本旅客鉄道中央本線の駅。駅番号はJB 12。渋谷区内の鉄道駅では最も東に位置する。","d":"東京都渋谷区千駄ヶ谷にある東日本旅客鉄道の駅","t":"千駄ケ谷駅"},"南新宿":{"x":"南新宿駅は、東京都渋谷区代々木二丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 02。 駅名に新宿と付くが、渋谷区に存在する。","d":"東京都渋谷区代々木にある小田急電鉄の駅","t":"南新宿駅"},"南千住":{"x":"南千住駅は、東京都荒川区南千住四丁目にある、東日本旅客鉄道・東京地下鉄・首都圏新都市鉄道の駅である。荒川区最東端の駅。","d":"東京都荒川区にある東日本旅客鉄道・東京地下鉄・首都圏新都市鉄道の駅","t":"南千住駅"},"北赤羽":{"x":"北赤羽駅は、東京都北区赤羽北二丁目にある、東日本旅客鉄道の駅である。駅番号はJA 16。一部は浮間三丁目にまたがる。","d":"東京都北区赤羽北にある東日本旅客鉄道の駅","t":"北赤羽駅"},"南浦和":{"x":"南浦和駅は、埼玉県さいたま市南区南浦和二丁目にある、東日本旅客鉄道の駅である。","d":"埼玉県さいたま市南区南浦和にある東日本旅客鉄道の駅","t":"南浦和駅"},"南流山":{"x":"南流山駅は、千葉県流山市南流山にある、東日本旅客鉄道・首都圏新都市鉄道の駅である。","d":"千葉県流山市にある東日本旅客鉄道・首都圏新都市鉄道の駅","t":"南流山駅"},"半蔵門":{"x":"半蔵門駅は、東京都千代田区麹町一丁目にある、東京地下鉄半蔵門線の駅である。駅番号はZ 05。 半蔵門線唯一の単独駅である。","d":"東京都千代田区にある東京地下鉄の駅","t":"半蔵門駅"},"千歳烏山":{"x":"千歳烏山駅は、東京都世田谷区南烏山六丁目にある、京王電鉄京王線の駅。「京王ライナー」「Mt.TAKAO号」を除く全列車が停車する。京王東管区所属。","d":"東京都世田谷区南烏山にある京王電鉄の駅","t":"千歳烏山駅"},"千川":{"x":"千川駅は、東京都豊島区要町三丁目にある、東京地下鉄の駅である。 有楽町線・副都心線が乗り入れる。当駅を含む小竹向原駅 - 池袋駅間は、有楽町線が上層を、副都心線が下層を走る形で並走する。","d":"東京都豊島区要町三丁目にある東京地下鉄の駅","t":"千川駅"},"千歳船橋":{"x":"千歳船橋駅は、東京都世田谷区船橋一丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 12。","d":"東京都世田谷区船橋にある小田急電鉄の駅","t":"千歳船橋駅"},"千住大橋":{"x":"千住大橋駅は、東京都足立区千住橋戸町にある、京成電鉄本線の駅である。駅番号はKS05。足立区最南端の駅である。","d":"東京都足立区千住橋戸町にある京成電鉄の駅","t":"千住大橋駅"},"千駄木":{"x":"千駄木駅は、東京都文京区千駄木二丁目にある、東京地下鉄千代田線の駅である。駅番号はC 15。 東京都区部のほぼ中心に存する文京区の北東端、JR東日本山手線の内側に位置している。","d":"東京都文京区にある東京地下鉄の駅","t":"千駄木駅"},"南砂町":{"x":"南砂町駅は、東京都江東区南砂三丁目にある、東京地下鉄東西線の駅である。駅番号はT 15。","d":"東京都江東区にある東京地下鉄の駅","t":"南砂町駅"},"南行徳":{"x":"南行徳駅は、千葉県市川市相之川四丁目にある、東京地下鉄東西線の駅である。駅番号はT 19。","d":"千葉県市川市にある東京地下鉄の駅","t":"南行徳駅"},"千石":{"x":"千石駅は、東京都文京区千石一丁目にある、東京都交通局三田線の駅である。駅番号はI 14。文京区最北端の駅である。","d":"東京都文京区にある東京都交通局の駅","t":"千石駅"},"十間橋通":{"x":"十間橋通駅は、かつて東京都墨田区に存在した東武鉄道亀戸線の駅。","d":"かつて日本の東京都墨田区押上にあった東武鉄道の駅","t":"十間橋通駅"},"原宿":{"x":"原宿駅は、東京都渋谷区神宮前一丁目にある、東日本旅客鉄道山手線の駅である。駅番号はJY 19。","d":"日本の鉄道駅","t":"原宿駅"},"吉祥寺":{"x":"吉祥寺駅は、東京都武蔵野市吉祥寺南町にある、東日本旅客鉄道・京王電鉄の駅。","d":"東京都武蔵野市吉祥寺南町にある東日本旅客鉄道・京王電鉄の駅","t":"吉祥寺駅"},"和光市":{"x":"和光市駅は、埼玉県和光市本町にある、東武鉄道・東京地下鉄の駅である。","d":"埼玉県和光市本町にある東武鉄道・東京地下鉄の駅","t":"和光市駅"},"品川シーサイド":{"x":"品川シーサイド駅は、東京都品川区東品川四丁目にある、東京臨海高速鉄道りんかい線の駅である。副駅名はビッグローブ本社前。駅番号はR 06。","d":"東京都品川区東品川にある東京臨海高速鉄道の駅","t":"品川シーサイド駅"},"向河原":{"x":"向河原駅は、神奈川県川崎市中原区下沼部字玉川向にある、東日本旅客鉄道南武線の駅である。駅番号はJN 06。","d":"神奈川県川崎市中原区にある東日本旅客鉄道の駅","t":"向河原駅"},"和泉多摩川":{"x":"和泉多摩川駅は、東京都狛江市東和泉四丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 17。","d":"東京都狛江市東和泉にある小田急電鉄の駅","t":"和泉多摩川駅"},"喜多見":{"x":"喜多見駅は、東京都世田谷区喜多見九丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 15。世田谷区最西端の駅である。","d":"東京都世田谷区喜多見にある小田急電鉄の駅","t":"喜多見駅"},"向ヶ丘遊園":{"x":"向ヶ丘遊園駅は、神奈川県川崎市多摩区登戸にある、小田急電鉄小田原線の駅である。駅番号はOH 19。 周辺地域は「ゆうえん」の略称で呼ばれる場合もある。","d":"神奈川県川崎市多摩区登戸にある小田急電鉄の駅","t":"向ヶ丘遊園駅"},"参宮橋":{"x":"参宮橋駅は、東京都渋谷区代々木四丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 03。","d":"東京都渋谷区代々木にある小田急電鉄の駅","t":"参宮橋駅"},"四ツ木":{"x":"四ツ木駅は、東京都葛飾区四つ木一丁目にある、京成電鉄押上線の駅。駅番号はKS48。","d":"東京都葛飾区四つ木にある京成電鉄の駅","t":"四ツ木駅"},"南阿佐ケ谷":{"x":"南阿佐ケ谷駅は、東京都杉並区阿佐谷南一丁目にある、東京地下鉄丸ノ内線の駅である。駅番号はM 02。","d":"東京都杉並区にある東京地下鉄の駅","t":"南阿佐ケ谷駅"},"南鳩ヶ谷":{"x":"南鳩ヶ谷駅は、埼玉県川口市南鳩ヶ谷五丁目にある、埼玉高速鉄道埼玉高速鉄道線の駅である。駅番号はSR 21。","d":"埼玉県川口市にある埼玉高速鉄道の駅","t":"南鳩ヶ谷駅"},"台場":{"x":"台場駅は、東京都港区台場二丁目にある、ゆりかもめ東京臨海新交通臨海線の駅。駅番号はU 07。港区最南端の駅である。","d":"東京都港区台場にあるゆりかもめの駅","t":"台場駅"},"哲学堂公園":{"x":"哲学堂公園は、東京都中野区にある中野区立の公園である。公園の南東部(面積の7%程度）は新宿区にある。2020年に国の名勝に指定された。","d":"中野区立の公園","t":"哲学堂公園"},"品川":{"x":"品川駅は、東京都港区高輪三丁目および港南二丁目にある、東日本旅客鉄道・東海旅客鉄道・日本貨物鉄道・京浜急行電鉄の駅である。 山手線南部のターミナル駅で乗降人員は港区最多の78万人、これは国内8位で北千住駅に次ぐもので、世界有数の利用者数を誇る。","d":"東京都港区にある駅","t":"品川駅"},"向島百花園":{"x":"向島百花園は、東京都墨田区東向島三丁目にある都立庭園。江戸時代に佐原鞠塢によって開かれた花園を発祥として1939年7月に開園した施設である。国指定名勝・史跡。","d":"東京都墨田区東向島にある都立庭園","t":"向島百花園"},"南馬場":{"x":"新馬場駅は、東京都品川区北品川二丁目にある京浜急行電鉄本線の駅である。駅番号はKK03。","d":"東京都品川区北品川にある京浜急行電鉄の駅","t":"新馬場駅"},"参議院":{"x":"参議院は、日本の立法府たる国会の議院のひとつである。前身は貴族院。 両院制を採用する諸国の上院に相当し、下院である衆議院とともに国会を構成している。","d":"日本の国会の上院","t":"参議院"},"国際展示場":{"x":"国際展示場駅は、東京都江東区有明二丁目にある、東京臨海高速鉄道りんかい線の駅である。りんかい線公式ウェブサイトに掲載されている路線図では「」と括弧書きが付されている。駅番号はR 03。","d":"日本の鉄道駅","t":"国際展示場駅"},"四ツ谷":{"x":"四ツ谷駅は、東京都新宿区四谷一丁目にある、東日本旅客鉄道、東京地下鉄の駅。駅敷地内に区境があり、JR東日本の大部分および東京メトロ丸ノ内線の一部は千代田区麹町六丁目に所在する。 丸ノ内線の隣駅は「四谷三丁目」、町名は「四谷」、駅前のバス停留所は「四谷駅」「四谷駅前」で、「ツ」が入らない。","d":"東京都新宿区にある東日本旅客鉄道・東京地下鉄の駅","t":"四ツ谷駅"},"国立西洋美術館":{"x":"国立西洋美術館は、東京都台東区の上野公園内にある、西洋の美術作品を専門とする美術館である。独立行政法人国立美術館が運営している。本館は「ル・コルビュジエの建築作品-近代建築運動への顕著な貢献-」の構成資産として世界文化遺産に登録されている。","d":"東京にある美術館","t":"国立西洋美術館"},"国道":{"x":"国道駅は、神奈川県横浜市鶴見区生麦五丁目にある、東日本旅客鉄道鶴見線の駅である。駅番号はJI 02。","d":"神奈川県横浜市鶴見区生麦にある東日本旅客鉄道の駅","t":"国道駅"},"地下鉄成増":{"x":"地下鉄成増駅は、東京都板橋区成増二丁目にある、東京地下鉄の駅である。","d":"東京都板橋区成増二丁目にある東京地下鉄の駅","t":"地下鉄成増駅"},"国領":{"x":"国領駅は、東京都調布市国領町三丁目にある、京王電鉄京王線の駅である。京王中央管区所属。駅番号はKO16。","d":"東京都調布市国領町にある京王電鉄の駅","t":"国領駅"},"国会議事堂前":{"x":"国会議事堂前駅は、東京都千代田区永田町一丁目にある、東京地下鉄の駅である。","d":"東京都千代田区にある東京地下鉄の駅","t":"国会議事堂前駅"},"地下鉄赤塚":{"x":"地下鉄赤塚駅は、東京都練馬区北町八丁目にある、東京地下鉄の駅である。","d":"東京都練馬区北町八丁目にある東京地下鉄の駅","t":"地下鉄赤塚駅"},"堀切菖蒲園":{"x":"堀切菖蒲園駅は、東京都葛飾区堀切五丁目にある、京成電鉄本線の駅である。駅番号はKS07。葛飾区の鉄道駅では最西端に所在する。","d":"東京都葛飾区堀切五丁目にある京成電鉄の駅","t":"堀切菖蒲園駅"},"国府台":{"x":"国府台駅は、千葉県市川市市川三丁目にある、京成電鉄本線の駅である。駅番号はKS13。","d":"千葉県市川市市川にある京成電鉄の駅","t":"国府台駅"},"堀切":{"x":"堀切駅は、東京都足立区千住曙町にある、東武鉄道伊勢崎線の駅である。「東武スカイツリーライン」の愛称区間に含まれている。駅番号はTS 07。","d":"東京都足立区千住曙町にある東武鉄道の駅","t":"堀切駅"},"四谷三丁目":{"x":"四谷三丁目駅は、東京都新宿区四谷三丁目にある、東京地下鉄丸ノ内線の駅である。駅番号はM 11。","d":"東京都新宿区にある東京地下鉄の駅","t":"四谷三丁目駅"},"国立競技場":{"x":"国立競技場駅は、東京都新宿区霞ヶ丘町にある東京都交通局大江戸線の駅。駅番号はE 25。「東京体育館前」の副名称が設定されている。","d":"東京都新宿区にある東京都交通局の駅","t":"国立競技場駅"},"国立科学博物館":{"x":"国立科学博物館（こくりつかがくはくぶつかん、英: National Museum of Nature and Science、略称:かはく、科博）は、独立行政法人国立科学博物館が運営する日本の博物館。","d":"東京都台東区にある国立博物館","t":"国立科学博物館"},"増上寺":{"x":"増上寺は、東京都港区芝公園四丁目にある浄土宗の仏教寺院。山号は三縁山。三縁山広度院増上寺と称する。","d":"東京都港区にある仏教寺院","t":"増上寺"},"国立新美術館":{"x":"国立新美術館は、東京・六本木にある美術館。日本で5館目の国立美術館として、2007年1月に開館した。黒川紀章設計。","d":"東京・六本木にある美術館","t":"国立新美術館"},"堀之内貝塚":{"x":"堀之内貝塚は、千葉県市川市堀之内にある縄文時代後期から晩期の貝塚および環状集落の遺跡。国の史跡に指定されている。 縄文時代後期前葉の標式土器型式である「堀之内式」の標式遺跡として知られている。","d":"千葉県市川市にある縄文時代の貝塚","t":"堀之内貝塚"},"埴輪 挂甲武人":{"x":"埴輪 挂甲武人は、東京国立博物館が所蔵する、衝角付冑と小札甲と呼ばれる甲冑をまとい武装した6世紀代の人物形象埴輪である。 古墳時代の埴輪として初めて国宝に指定されたものであり、2020年9月30日に綿貫観音山古墳出土埴輪群が国宝となるまでは、唯一の国宝埴輪であった。","d":"東京国立博物館所蔵の武装した人物の形象埴輪。国宝に指定されている。映画『大魔神』のモデル。","t":"埴輪 挂甲武人"},"大崎":{"x":"大崎駅は、東京都品川区大崎一丁目にある、東日本旅客鉄道・東京臨海高速鉄道の駅である。 JR東日本と東京臨海高速鉄道の共同使用駅で、JR東日本が駅管理を行う。","d":"東京都品川区大崎にある東日本旅客鉄道・東京臨海高速鉄道の駅","t":"大崎駅"},"大井町":{"x":"大井町駅は、東京都品川区大井一丁目にある、東日本旅客鉄道・東急電鉄・東京臨海高速鉄道の駅である。","d":"東京都品川区にある東日本旅客鉄道・東急電鉄・東京臨海高速鉄道の駅","t":"大井町駅"},"大師前":{"x":"大師前駅は、東京都足立区西新井一丁目にある、東武鉄道大師線の駅。駅番号はTS 51。","d":"東京都足立区西新井一丁目にある東武鉄道の駅","t":"大師前駅"},"多摩川":{"x":"多摩川駅は、東京都大田区田園調布一丁目にある、東急電鉄の駅である。","d":"東京都大田区田園調布にある東急電鉄の駅","t":"多摩川駅"},"大井競馬場前":{"x":"大井競馬場前駅は、東京都品川区勝島二丁目にある東京モノレール羽田空港線の駅である。駅番号はMO 03。","d":"東京都品川区勝島にある東京モノレールの駅","t":"大井競馬場前駅"},"大口":{"x":"大口駅は、神奈川県横浜市神奈川区大口通にある、東日本旅客鉄道横浜線の駅である。駅番号はJH 14。 東神奈川駅発着系統と、横浜駅経由で根岸線に直通する列車が停車する。","d":"神奈川県横浜市神奈川区にある東日本旅客鉄道の駅","t":"大口駅"},"大森海岸":{"x":"大森海岸駅は、東京都品川区南大井三丁目にある京浜急行電鉄本線の駅である。駅番号はKK07。 品川区最南端の駅であり、ホームの一部は大田区大森北に跨る。","d":"東京都品川区南大井にある京浜急行電鉄の駅","t":"大森海岸駅"},"外苑前":{"x":"外苑前駅は、東京都港区北青山二丁目にある、東京地下鉄銀座線の駅。駅番号はG 03。","d":"東京都港区にある東京地下鉄の駅","t":"外苑前駅"},"大岡山":{"x":"大岡山駅は、東京都大田区北千束三丁目にある、東急電鉄の駅である。目黒線と大井町線が乗り入れ、両路線の接続駅となっている。駅番号は目黒線がMG06、大井町線がOM08。","d":"東京都大田区北千束にある東急電鉄の駅","t":"大岡山駅"},"大川":{"x":"大川駅は、神奈川県川崎市川崎区大川町にある、東日本旅客鉄道・日本貨物鉄道鶴見線の駅である。川崎市最南端の鉄道駅。 大川支線の終点である。","d":"神奈川県川崎市川崎区大川町にある東日本旅客鉄道・日本貨物鉄道の駅","t":"大川駅"},"大崎広小路":{"x":"大崎広小路駅は、東京都品川区大崎四丁目にある、東急電鉄池上線の駅である。駅番号はIK02。","d":"東京都品川区大崎にある東急電鉄の駅","t":"大崎広小路駅"},"大師橋":{"x":"大師橋駅は、神奈川県川崎市川崎区大師河原二丁目にある、京浜急行電鉄大師線の駅である。駅番号はKK25。 駅名は近隣で多摩川を渡る橋の名に由来している。","d":"神奈川県川崎市川崎区大師河原にある京浜急行電鉄の駅","t":"大師橋駅"},"大塚・歳勝土遺跡":{"x":"大塚・歳勝土遺跡は、神奈川県横浜市都筑区大棚西にある弥生時代中期の遺跡。港北ニュータウン遺跡群の1つに含まれる。環濠集落の大塚遺跡と、その墓域の歳勝土遺跡から構成されている。","d":"神奈川県横浜市都筑区にある弥生時代の環濠集落。","t":"大塚・歳勝土遺跡"},"大塚先儒墓所":{"x":"大塚先儒墓所は、東京都文京区にある墓地。江戸時代の儒学者が儒葬された。俗に、「儒者捨場」とも呼ばれる。","t":"大塚先儒墓所"},"天王洲アイル":{"x":"天王洲アイル駅は、東京都品川区東品川二丁目にある、東京モノレール・東京臨海高速鉄道の駅。 品川区最東端の駅で、駅周辺の街区は天王洲アイルと通称される。","d":"日本の鉄道駅","t":"天王洲アイル駅"},"大鳥居":{"x":"大鳥居駅は、東京都大田区にある、京浜急行電鉄空港線の駅である。駅所在地および西口は西糀谷三丁目、東口は羽田一丁目にある。駅名は、開業当時の駅前に立っていた穴守稲荷神社の大鳥居に由来する。","d":"東京都大田区西糀谷にある京浜急行電鉄の駅","t":"大鳥居駅"},"宮の坂":{"x":"宮の坂駅は、東京都世田谷区宮坂一丁目にある、東急電鉄世田谷線の停留場である。駅番号はSG07。","d":"東京都世田谷区宮坂にある東急電鉄の駅","t":"宮の坂駅"},"妙蓮寺":{"x":"妙蓮寺駅は、神奈川県横浜市港北区菊名一丁目にある、東急電鉄東横線の駅である。駅番号はTY17。","d":"神奈川県横浜市港北区菊名にある東急電鉄の駅","t":"妙蓮寺駅"},"宝町":{"x":"宝町駅は、東京都中央区京橋二丁目にある、東京都交通局浅草線の駅である。駅番号はA 12。","d":"東京都中央区京橋にある東京都交通局の駅","t":"宝町駅"},"学芸大学":{"x":"学芸大学駅は、東京都目黒区鷹番三丁目にある、東急電鉄東横線の駅である。駅番号はTY05。 駅名の由来となった東京学芸大学は1964年に小金井市へ移転しているが、東京学芸大学附属高等学校は当駅を最寄り駅として現存している。","d":"東京都目黒区鷹番にある東急電鉄の駅","t":"学芸大学駅"},"妙典":{"x":"妙典駅は、千葉県市川市富浜一丁目にある、東京地下鉄東西線の駅である。駅番号はT 21。東西線の駅では最も新しい。","d":"千葉県市川市にある東京地下鉄の駅","t":"妙典駅"},"大森町":{"x":"大森町駅は、東京都大田区大森西三丁目にある、京浜急行電鉄本線の駅である。駅番号はKK09。","d":"東京都大田区大森西にある京浜急行電鉄の駅","t":"大森町駅"},"安善":{"x":"安善駅は、神奈川県横浜市鶴見区安善町一丁目にある、東日本旅客鉄道・日本貨物鉄道鶴見線の駅。横浜市で最も東に位置する駅である。駅番号はJI 06。","d":"神奈川県横浜市鶴見区安善町にある東日本旅客鉄道・日本貨物鉄道の駅","t":"安善駅"},"大泉学園":{"x":"大泉学園駅は、東京都練馬区東大泉にある、西武鉄道池袋線の駅である。駅番号はSI11。","d":"東京都練馬区にある西武鉄道の駅","t":"大泉学園駅"},"奥沢":{"x":"奥沢駅は、東京都世田谷区奥沢三丁目にある、東急電鉄目黒線の駅である。駅番号はMG07。東急目黒線では唯一世田谷区に所在する駅で、同区最南端の駅である。","d":"東京都世田谷区奥沢にある東急電鉄の駅","t":"奥沢駅"},"大森貝塚":{"x":"大森貝塚は、東京都品川区・大田区にある縄文時代後期から末期の貝塚である。発見者のエドワード・S・モースの名を冠してモース貝塚とも言われている。","d":"東京都品川区・大田区にある貝塚","t":"大森貝塚"},"学習院下":{"x":"学習院下停留場は、東京都豊島区高田二丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 28。 豊島区最南端の停車場である。","d":"東京都豊島区高田にある東京都交通局の停留場","t":"学習院下停留場"},"大隈講堂":{"x":"早稲田大学大隈記念講堂は、東京都新宿区戸塚の早稲田大学早稲田キャンパスに所在するチューダー・ゴシック様式の講堂。略称は大隈講堂、学内での別称は21号館。 大隈重信像と並び早稲田大学を象徴する建造物である。","d":"早稲田キャンパス内にある講堂","t":"大隈講堂"},"天空橋":{"x":"天空橋駅は、東京都大田区羽田空港一丁目にある、京浜急行電鉄・東京モノレールの駅である。駅名は近くの海老取川に架かる同名の人道橋に由来している。","d":"東京都大田区羽田空港にある京浜急行電鉄・東京モノレールの駅","t":"天空橋駅"},"奥戸":{"x":"大井ダム駅は、かつて岐阜県恵那郡大井町奥戸にあった北恵那鉄道大井線の駅である。","t":"大井ダム駅"},"小金城趾":{"x":"小金城趾駅は、千葉県松戸市大金平にある、流鉄流山線の駅である。駅番号はRN3。","d":"千葉県松戸市大金平にある流鉄流山線の駅","t":"小金城趾駅"},"小竹向原":{"x":"小竹向原駅は、東京都練馬区小竹町二丁目にある、東京地下鉄・西武鉄道の駅。 正式所在地は駅事務所のある練馬区となっているが、構内は板橋区向原にも跨る。練馬区の駅では最も東に位置する。","d":"東京都練馬区小竹町二丁目にある東京地下鉄・西武鉄道の駅","t":"小竹向原駅"},"富士見ヶ丘":{"x":"富士見ヶ丘駅は、東京都杉並区久我山五丁目にある、京王電鉄井の頭線の駅である。井の頭北管区所属。駅番号はIN13。","d":"東京都杉並区久我山にある京王電鉄の駅","t":"富士見ヶ丘駅"},"小岩":{"x":"小岩駅は、東京都江戸川区南小岩七丁目にある、東日本旅客鉄道の駅である。","d":"東京都江戸川区南小岩にある東日本旅客鉄道の駅","t":"小岩駅"},"宮崎台":{"x":"宮崎台駅は、神奈川県川崎市宮前区宮崎二丁目にある、東急電鉄田園都市線の駅である。駅番号はDT12。 駅前高架下に電車とバスの博物館が所在しているため、「電車とバスの博物館」という副駅名が付けられている。","d":"神奈川県川崎市宮前区にある東急電鉄の駅","t":"宮崎台駅"},"宮前平":{"x":"宮前平駅は、神奈川県川崎市宮前区宮前平一丁目にある、東急電鉄田園都市線の駅である。駅番号はDT13。","d":"神奈川県川崎市宮前区宮前平にある東急電鉄の駅","t":"宮前平駅"},"小机":{"x":"小机駅は、神奈川県横浜市港北区小机町にある、東日本旅客鉄道横浜線の駅。駅番号はJH 17。横浜国際総合競技場の最寄駅であることから「日産スタジアム最寄駅」の副駅名がある。","d":"神奈川県横浜市港北区にある東日本旅客鉄道の駅","t":"小机駅"},"小村井":{"x":"小村井駅は、東京都墨田区文花二丁目にある、東武鉄道亀戸線の駅である。駅番号はTS 41。","d":"東京都墨田区文花にある東武鉄道の駅","t":"小村井駅"},"宿河原":{"x":"宿河原駅は、神奈川県川崎市多摩区宿河原三丁目にある、東日本旅客鉄道南武線の駅である。駅番号はJN 13。","d":"神奈川県川崎市多摩区宿河原にある東日本旅客鉄道の駅","t":"宿河原駅"},"尻手":{"x":"尻手駅は、神奈川県川崎市幸区南幸町三丁目にある、東日本旅客鉄道南武線の駅である。駅番号はJN 02。 南武線の本線のほか、浜川崎駅方面の支線、および新鶴見信号場への支線が当駅から分岐している。","d":"神奈川県川崎市幸区南幸町にある東日本旅客鉄道の駅","t":"尻手駅"},"小伝馬町":{"x":"小伝馬町駅は、東京都中央区日本橋小伝馬町にある、東京地下鉄日比谷線の駅である。駅番号はH 15。 当駅の下で東日本旅客鉄道総武快速線が交差しているが、同線に駅は設けられていない。","d":"東京都中央区にある東京地下鉄の駅","t":"小伝馬町駅"},"小菅":{"x":"小菅駅は、東京都足立区足立二丁目にある、東武鉄道伊勢崎線の駅である。「東武スカイツリーライン」の愛称区間に含まれている。駅番号はTS 10。","d":"東京都足立区足立二丁目にある東武鉄道の駅","t":"小菅駅"},"富士見台":{"x":"富士見台駅は、東京都練馬区貫井三丁目にある、西武鉄道池袋線の駅である。駅番号はSI08。","d":"東京都練馬区にある西武鉄道の駅","t":"富士見台駅"},"小石川後楽園":{"x":"小石川後楽園は、東京都文京区後楽一丁目にある都立庭園。江戸時代初期に水戸徳川家の江戸上屋敷内につくられた築山泉水回遊式の日本庭園である。国の特別史跡及び特別名勝に指定されている。","d":"日本の東京都文京区にある庭園","t":"小石川後楽園"},"小島新田":{"x":"小島新田駅は、神奈川県川崎市川崎区田町二丁目にある、京浜急行電鉄大師線の駅。同線の終点。駅番号はKK26。","d":"神奈川県川崎市川崎区田町にある京浜急行電鉄の駅","t":"小島新田駅"},"小台":{"x":"小台停留場は、東京都荒川区西尾久五丁目の上にある、東京都交通局都電荒川線の停留場である。駅番号はSA 11。","d":"東京都荒川区西尾久にある都電荒川線の停留場","t":"小台停留場"},"寛永寺":{"x":"寛永寺は、東京都台東区上野桜木一丁目にある天台宗関東総本山の寺院。山号は東叡山。東叡山寛永寺円頓院と号する。","d":"東京都台東区にある仏教寺院","t":"寛永寺"},"小田栄":{"x":"小田栄駅は、神奈川県川崎市川崎区小田栄一丁目にある、東日本旅客鉄道南武線の駅である。駅番号はJN 53。","d":"神奈川県川崎市川崎区小田栄にある東日本旅客鉄道の駅","t":"小田栄駅"},"巣鴨":{"x":"巣鴨駅は、東京都豊島区巣鴨にある、東日本旅客鉄道・東京都交通局の駅である。","d":"東京都豊島区にある東日本旅客鉄道・東京都交通局の駅","t":"巣鴨駅"},"川崎":{"x":"川崎駅は、神奈川県川崎市川崎区駅前本町にある、東日本旅客鉄道の駅である。","d":"神奈川県川崎市川崎区駅前本町にある東日本旅客鉄道の駅","t":"川崎駅"},"市ヶ谷":{"x":"市ケ谷駅および市ヶ谷駅は、東京都千代田区・新宿区にある、東日本旅客鉄道・東京地下鉄・東京都交通局の駅である。 JR東日本と東京メトロの駅は「市ケ谷」、都営地下鉄の駅は「市ヶ谷」と表記する。 所在地は、JR東日本が千代田区五番町、東京メトロが新宿区市谷田町一丁目、都営地下鉄が千代田区九段南四丁目である。","d":"東京都千代田区・新宿区にある東日本旅客鉄道・東京地下鉄・都営地下鉄の駅","t":"市ケ谷駅"},"川口元郷":{"x":"川口元郷駅は、埼玉県川口市元郷一丁目にある、埼玉高速鉄道埼玉高速鉄道線の駅である。駅番号はSR 20。","d":"埼玉県川口市にある埼玉高速鉄道の駅","t":"川口元郷駅"},"岩本町":{"x":"岩本町駅は、東京都千代田区神田岩本町にある、東京都交通局新宿線の駅。駅番号はS 08。 「秋葉原」の副名称が設定されている。","d":"日本の鉄道駅","t":"岩本町駅"},"岸根公園":{"x":"岸根公園駅は、神奈川県横浜市港北区篠原町にある、横浜市営地下鉄ブルーラインの駅である。駅番号はB24。","d":"神奈川県横浜市港北区篠原町にある横浜市交通局の駅","t":"岸根公園駅"},"川口":{"x":"川口駅は、埼玉県川口市栄町三丁目にある、東日本旅客鉄道の駅である。駅番号はJK 39。","d":"埼玉県川口市栄町にある東日本旅客鉄道の駅","t":"川口駅"},"市が尾":{"x":"市が尾駅は、神奈川県横浜市青葉区市ケ尾町にある、東急電鉄田園都市線の駅である。駅番号はDT18。青葉区役所の最寄駅である。","d":"神奈川県横浜市青葉区市ヶ尾町にある東急電鉄の駅","t":"市が尾駅"},"尾久":{"x":"尾久駅は、東京都北区昭和町一丁目にある、東日本旅客鉄道の駅である。駅番号はJU 03。 乗り入れている路線は、線路名称上は東北本線の日暮里駅 - 当駅 - 赤羽駅間の支線である。","d":"日本の東京都北区昭和町にある東日本旅客鉄道の駅","t":"尾久駅"},"川崎大師":{"x":"川崎大師駅は、神奈川県川崎市川崎区大師駅前一丁目にある、京浜急行電鉄大師線の駅である。駅番号はKK23。","d":"神奈川県川崎市川崎区大師駅前にある京浜急行電鉄の駅","t":"川崎大師駅"},"川崎新町":{"x":"川崎新町駅は、神奈川県川崎市川崎区渡田山王町にある、東日本旅客鉄道南武線の駅である。駅番号はJN 52。","d":"神奈川県川崎市川崎区渡田山王町にある東日本旅客鉄道の駅","t":"川崎新町駅"},"尾山台":{"x":"尾山台駅は、東京都世田谷区等々力五丁目にある、東急電鉄大井町線の駅である。駅番号はOM12。","d":"東京都世田谷区等々力にある東急電鉄の駅","t":"尾山台駅"},"川和町":{"x":"川和町駅は、神奈川県横浜市都筑区川和町にある、横浜市営地下鉄グリーンラインの駅である。駅番号はG02。 地上駅で、グリーンラインの車両基地である川和車両基地への入・出庫線が設置されている。","d":"神奈川県横浜市都筑区川和町にある横浜市交通局の駅","t":"川和町駅"},"市場前":{"x":"市場前駅は、東京都江東区豊洲六丁目にある、ゆりかもめ東京臨海新交通臨海線の駅である。駅番号はU 14。","d":"東京都江東区豊洲にあるゆりかもめの駅","t":"市場前駅"},"市川塩浜":{"x":"市川塩浜駅は、千葉県市川市塩浜二丁目にある、東日本旅客鉄道京葉線の駅である。西船橋駅から武蔵野線に乗り入れる列車も停車する。駅番号はJE 09。","d":"千葉県市川市塩浜にある東日本旅客鉄道の駅","t":"市川塩浜駅"},"島津家文書":{"x":"島津家文書は、惟宗忠久を初代とする島津氏が、平安時代末期から明治時代初期までの約700年間、代々伝えてきた文書であり、政治、外交、社会経済、家督相続など多岐にわたる総数15,133通の大規模な武家文書群である。 西南戦争下では鹿児島城から桜島に船で難を逃れ、また、第二次世界大戦下では軍の空襲激化を避けて長野県に疎開し戦火を免れて、1955年から1957年にかけて東京大学に譲渡された。長い歳月の…","d":"文京区にある国宝（美術品）","t":"島津家文書"},"御徒町":{"x":"御徒町駅は、東京都台東区上野五丁目にある、東日本旅客鉄道の駅である。","d":"東京都台東区上野にある東日本旅客鉄道の鉄道駅","t":"御徒町駅"},"御茶ノ水":{"x":"御茶ノ水駅は、東京都千代田区・文京区にある、東日本旅客鉄道・東京地下鉄の駅である。 千代田区と文京区の境界付近に位置しており、JR東日本の駅は神田川南側の千代田区側に、東京メトロの駅は堀の北側の文京区側にある。所在地は、JR東日本が千代田区神田駿河台二丁目、東京メトロが文京区湯島一丁目である。","d":"日本の鉄道駅","t":"御茶ノ水駅"},"幸谷":{"x":"幸谷駅は、千葉県松戸市新松戸にある流鉄流山線の駅である。駅番号はRN2。付近にJR東日本の新松戸駅がある。","d":"千葉県松戸市新松戸にある流鉄流山線の駅","t":"幸谷駅"},"志木":{"x":"志木駅は、埼玉県新座市東北二丁目にある、東武鉄道東上本線の駅である。駅番号はTJ 14。","d":"埼玉県新座市東北二丁目にある東武鉄道の駅","t":"志木駅"},"御成門":{"x":"御成門駅は、東京都港区西新橋三丁目にある、東京都交通局三田線の駅である。駅番号はI 06。 当駅は新旧の駅名標が混在しており、旧式の駅名標には「東京タワー前」の副駅名が表示されている。","d":"東京都港区にある東京都交通局の駅","t":"御成門駅"},"後楽園":{"x":"後楽園駅は、東京都文京区春日一丁目にある、東京地下鉄の駅。駅ビル「メトロ・エム後楽園」を併設する。","d":"東京都文京区にある東京地下鉄の駅","t":"後楽園駅"},"幡ヶ谷":{"x":"幡ヶ谷駅は、東京都渋谷区幡ヶ谷一丁目にある、京王電鉄の駅である。京王東管区所属。駅番号はKO03。","d":"東京都渋谷区幡ヶ谷にある京王電鉄の駅","t":"幡ヶ谷駅"},"平和島":{"x":"平和島駅は、東京都大田区大森北六丁目にある京浜急行電鉄本線の駅である。駅番号はKK08。","d":"東京都大田区大森北にある京浜急行電鉄の駅","t":"平和島駅"},"平間":{"x":"平間駅は、神奈川県川崎市中原区田尻町にある、東日本旅客鉄道南武線の駅である。駅番号はJN 05。","d":"神奈川県川崎市中原区田尻町にある東日本旅客鉄道の駅","t":"平間駅"},"布田":{"x":"布田駅は、東京都調布市国領町5丁目にある、京王電鉄京王線の駅である。京王中央管区所属。駅番号はKO17。","d":"東京都調布市国領町にある京王電鉄の駅","t":"布田駅"},"広尾":{"x":"広尾駅は、東京都港区南麻布五丁目にある、東京地下鉄日比谷線の駅である。駅番号はH 03。 駅名の「広尾」は現行行政地名では渋谷区の地名で、駅の所在が港区であるが、広域地名の広尾は渋谷区と港区とにまたがる地名である。","d":"東京都港区にある東京地下鉄の駅","t":"広尾駅"},"市川真間":{"x":"市川真間駅は、千葉県市川市真間一丁目にある、京成電鉄本線の駅である。駅番号はKS14。","d":"千葉県市川市真間にある京成電鉄の駅","t":"市川真間駅"},"市川":{"x":"市川駅は、千葉県市川市市川一丁目にある、東日本旅客鉄道総武本線の駅である。 運行系統としては快速線を走行する総武快速線、緩行線を走行する総武緩行線の2系統が停車する。駅番号は快速線がJO 24、緩行線がJB 27。","d":"千葉県市川市市川にある東日本旅客鉄道の駅","t":"市川駅"},"弁天橋":{"x":"弁天橋駅は、神奈川県横浜市鶴見区弁天町にある、東日本旅客鉄道鶴見線の駅である。駅番号はJI 04。","d":"神奈川県横浜市鶴見区弁天町にある東日本旅客鉄道の駅","t":"弁天橋駅"},"御嶽山":{"x":"御嶽山駅は、東京都大田区北嶺町にある、東急電鉄池上線の駅である。駅番号はIK10。","d":"東京都大田区北嶺町にある東急電鉄の駅","t":"御嶽山駅"},"庚申塚":{"x":"庚申塚停留場は、東京都豊島区西巣鴨二丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 21。","d":"東京都豊島区西巣鴨にある東京都交通局の停留場","t":"庚申塚停留場"},"帝国劇場":{"x":"帝国劇場は、東京都千代田区丸の内三丁目にあるプロセニアム形式の劇場である。1911年3月1日開場、3月4日に杮落し公演の初日を迎えた。1940年以降は阪急阪神東宝グループの東宝が運営している。","d":"日本の劇場","t":"帝国劇場"},"影向のマツ":{"x":"影向のマツは、東京都江戸川区東小岩の善養寺境内に生育しているクロマツの巨木である。樹齢は600年以上で繁茂面積は日本一といわれ、2011年9月21日に国の天然記念物の指定を受けた。正式指定名称は善養寺影向のマツ。","d":"東京都江戸川区の善養寺に生育するクロマツ","t":"影向のマツ"},"恵比寿":{"x":"恵比寿駅は、東京都渋谷区恵比寿南一丁目にある、東日本旅客鉄道と東京地下鉄の駅である。渋谷区内の鉄道駅では最も南にある。","d":"東京都渋谷区にある東日本旅客鉄道・東京地下鉄の駅","t":"恵比寿駅"},"成城学園前":{"x":"成城学園前駅は、東京都世田谷区成城六丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 14。","d":"東京都世田谷区成城にある小田急電鉄の駅","t":"成城学園前駅"},"押上":{"x":"押上駅は、東京都墨田区押上一丁目にある、京成電鉄・東京都交通局・東京地下鉄・東武鉄道の駅である。 全社局共通の副駅名として「スカイツリー前」が導入され、すべての鉄道会社の車内放送で「押上〈スカイツリー前〉駅」と案内される。","d":"東京都墨田区押上一丁目にある鉄道駅","t":"押上駅"},"戸越公園":{"x":"戸越公園駅は、東京都品川区戸越五丁目にある、東急電鉄大井町線の駅である。駅番号はOM03。","d":"東京都品川区戸越にある東急電鉄の駅","t":"戸越公園駅"},"志茂":{"x":"志茂駅は、東京都北区志茂二丁目にある、東京地下鉄南北線の駅である。駅番号はN 18。","d":"東京都北区にある東京地下鉄の駅","t":"志茂駅"},"戸越":{"x":"戸越駅は、東京都品川区戸越三丁目にある、東京都交通局浅草線の駅である。駅番号はA 04。","d":"東京都品川区戸越にある東京都交通局の駅","t":"戸越駅"},"戸田公園":{"x":"戸田公園駅は、埼玉県戸田市本町四丁目にある、東日本旅客鉄道の駅である。駅番号はJA 18。 当駅に乗り入れている路線は、線路名称上は東北本線であるが、運転系統上は埼京線として案内される。","d":"埼玉県戸田市本町にある東日本旅客鉄道の駅","t":"戸田公園駅"},"成増":{"x":"成増駅は、東京都板橋区成増二丁目にある、東武鉄道東上本線の駅である。駅番号はTJ 10。 東京地下鉄有楽町線・副都心線の地下鉄成増駅が近接しているが、乗り換えの案内は行われていない。","d":"東京都板橋区成増にある東武鉄道の駅","t":"成増駅"},"新三河島":{"x":"新三河島駅は、東京都荒川区西日暮里六丁目にある、京成電鉄本線の駅である。駅番号はKS03。","d":"東京都荒川区西日暮里にある京成電鉄の駅","t":"新三河島駅"},"志村坂上":{"x":"志村坂上駅は、東京都板橋区志村一丁目にある、東京都交通局三田線の駅である。駅番号はI 21。","d":"東京都板橋区志村にある東京都交通局の駅","t":"志村坂上駅"},"志村三丁目":{"x":"志村三丁目駅は、東京都板橋区志村三丁目にある、東京都交通局三田線の駅である。駅番号はI 22。","d":"東京都板橋区志村にある東京都交通局の駅","t":"志村三丁目駅"},"戸越銀座":{"x":"戸越銀座駅は、東京都品川区平塚二丁目にある、東急電鉄池上線の駅である。駅番号はIK03。駅舎はグッドデザイン賞、土木学会デザイン賞2018奨励賞を受賞。","d":"東京都品川区平塚にある東急電鉄の駅","t":"戸越銀座駅"},"整備場":{"x":"整備場駅は、東京都大田区羽田空港一丁目にある東京モノレール羽田空港線の駅である。駅番号はMO 06。","d":"東京都大田区羽田空港にある東京モノレールの駅","t":"整備場駅"},"戸定邸":{"x":"戸定邸は、千葉県東葛飾郡松戸町松戸に水戸藩最後の藩主であった徳川昭武が造った別邸。 国の重要文化財の一つであり、指定名称は旧徳川家住宅松戸戸定邸。庭園は旧徳川昭武庭園として国の名勝に指定されている。","d":"旧水戸藩主徳川昭武の別邸","t":"戸定邸"},"扇大橋":{"x":"扇大橋駅は、東京都足立区扇二丁目にある、東京都交通局日暮里・舎人ライナーの駅である。駅番号はNT 06。","d":"東京都足立区扇にある東京都交通局の駅","t":"扇大橋駅"},"新大久保":{"x":"新大久保駅は、東京都新宿区百人町一丁目にある、東日本旅客鉄道山手線の駅である。駅番号はJY 16。","d":"東京都新宿区にある東日本旅客鉄道の駅","t":"新大久保駅"},"新川崎":{"x":"新川崎駅は、神奈川県川崎市幸区鹿島田一丁目にある、東日本旅客鉄道の駅である。 1980年10月1日にいわゆる「SM分離」に際して、東戸塚駅とともに開業した。","d":"神奈川県川崎市幸区にある東日本旅客鉄道の駅","t":"新川崎駅"},"新宿西口":{"x":"新宿西口駅は、東京都新宿区西新宿一丁目にある、東京都交通局大江戸線の駅である。駅番号はE 01。 JR東日本・京王・小田急各線の新宿駅及び西武新宿駅と相互に乗り換えができる他、東京メトロ丸ノ内線新宿駅とも連絡している。","d":"東京都新宿区西新宿にある東京都交通局の駅","t":"新宿西口駅"},"新大塚":{"x":"新大塚駅は、東京都文京区大塚四丁目にある、東京地下鉄丸ノ内線の駅である。 豊島区との境界に位置し、一部は南大塚二丁目および東池袋五丁目にある。駅番号はM 24。","d":"東京都文京区にある東京地下鉄の駅","t":"新大塚駅"},"新井宿":{"x":"新井宿駅は、埼玉県川口市大字新井宿にある、埼玉高速鉄道埼玉高速鉄道線の駅である。駅番号はSR 23。","d":"埼玉県川口市にある埼玉高速鉄道の駅","t":"新井宿駅"},"新御徒町":{"x":"新御徒町駅は、東京都台東区にある、東京都交通局・首都圏新都市鉄道の駅。 都営地下鉄の駅は元浅草一丁目に、首都圏新都市鉄道の駅は小島二丁目に、それぞれ所在する。","d":"東京都台東区にある東京都交通局・首都圏新都市鉄道の駅","t":"新御徒町駅"},"新富町":{"x":"新富町駅は、東京都中央区築地一丁目にある、東京地下鉄有楽町線の駅である。駅番号はY 20。","d":"東京都中央区にある東京地下鉄の駅","t":"新富町駅"},"新代田":{"x":"新代田駅は、東京都世田谷区代田五丁目にある、京王電鉄井の頭線の駅である。井の頭南管区所属。駅番号はIN06。","d":"東京都世田谷区代田にある京王電鉄の駅","t":"新代田駅"},"新丸子":{"x":"新丸子駅は、神奈川県川崎市中原区新丸子町にある、東急電鉄の駅である。 当駅前後の複々線を利用して東横線の列車と目黒線の列車の2系統が乗り入れており、それぞれ別路線として案内されている。駅番号も個別に与えられており、東横線がTY10、目黒線がMG10である 。","d":"神奈川県川崎市中原区新丸子町にある東急電鉄の駅","t":"新丸子駅"},"新小岩":{"x":"新小岩駅は、東京都葛飾区新小岩一丁目にある、東日本旅客鉄道総武本線の駅である。葛飾区最南端の駅。 運転系統としては、快速線を走る総武快速線および緩行線を走る中央・総武線各駅停車の2系統が停車する。","d":"東京都葛飾区新小岩にある東日本旅客鉄道の駅","t":"新小岩駅"},"新八柱":{"x":"新八柱駅は、千葉県松戸市日暮一丁目にある、東日本旅客鉄道武蔵野線の駅である。駅番号はJM 14。京成電鉄の八柱駅と同一地点別構内の乗換駅となっている。","d":"千葉県松戸市にある東日本旅客鉄道の駅","t":"新八柱駅"},"新御茶ノ水":{"x":"新御茶ノ水駅は、東京都千代田区神田駿河台三丁目にある、東京地下鉄千代田線の駅である。駅番号はC 12。","d":"東京都千代田区にある東京地下鉄の駅","t":"新御茶ノ水駅"},"新宿御苑前":{"x":"新宿御苑前駅は、東京都新宿区新宿一丁目にある、東京地下鉄丸ノ内線の駅である。駅番号はM 10。","d":"東京都新宿区にある東京地下鉄の駅","t":"新宿御苑前駅"},"新中野":{"x":"新中野駅は、東京都中野区中央四丁目にある、東京地下鉄丸ノ内線の駅である。駅番号はM 05。","d":"東京都中野区にある東京地下鉄の駅","t":"新中野駅"},"新座":{"x":"新座駅は、埼玉県新座市野火止5丁目にある、東日本旅客鉄道武蔵野線の駅である。駅番号はJM 29。","d":"埼玉県新座市にある東日本旅客鉄道の駅","t":"新座駅"},"新井薬師前":{"x":"新井薬師前駅は、東京都中野区上高田五丁目にある、西武鉄道新宿線の駅である。駅番号はSS05。","d":"東京都中野区にある西武鉄道の駅","t":"新井薬師前駅"},"新整備場":{"x":"新整備場駅は、東京都大田区羽田空港三丁目にある東京モノレール羽田空港線の駅である。駅番号はMO 09。","d":"東京都大田区羽田空港にある東京モノレールの駅","t":"新整備場駅"},"新庚申塚":{"x":"新庚申塚停留場は、東京都豊島区西巣鴨三丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 20。","d":"東京都豊島区西巣鴨にある東京都交通局の停留場","t":"新庚申塚停留場"},"新宿三丁目":{"x":"新宿三丁目駅は、東京都新宿区新宿にある、東京地下鉄・東京都交通局の駅。 2004年5月時点では東京メトロの駅には「伊勢丹・三越前」という副名称があった。2026年現在も丸ノ内線では車内放送で「新宿三丁目、伊勢丹前」と案内される。","d":"東京都新宿区にある東京地下鉄・東京都交通局の駅","t":"新宿三丁目駅"},"新宿":{"x":"新宿駅は、東京都新宿区・渋谷区にある、東日本旅客鉄道・京王電鉄・小田急電鉄・東京地下鉄・東京都交通局の駅。 各社間の路線の乗り換えや直通運転も含めた1日あたりの平均乗降者数は約305万人で、世界最多の駅利用者数としてギネス世界記録に認定されている。 新宿地区の中心に位置しており、東京都西部の多摩地域を中心に郊外のベッドタウンを結ぶ中央線や私鉄などの路線と、新宿駅から千代田区や港区といった都心方…","d":"東京の鉄道駅","t":"新宿駅"},"新橋":{"x":"新橋駅は、東京都港区にある、東日本旅客鉄道・東京地下鉄・東京都交通局・ゆりかもめの駅である。 所在地は、ゆりかもめの駅が東新橋一丁目、その他の駅が新橋二丁目となっている。","d":"東京都港区にある駅","t":"新橋駅"},"新横浜":{"x":"新横浜駅は、神奈川県横浜市港北区にある、東海旅客鉄道・東日本旅客鉄道・横浜市交通局・相模鉄道・東急電鉄の駅。 JR東海とJR東日本の駅は篠原町に、横浜市交通局と相模鉄道および東急電鉄の駅は新横浜に、それぞれ所在する。","d":"神奈川県横浜市港北区にある駅","t":"新横浜駅"},"新松戸":{"x":"新松戸駅は、千葉県松戸市幸谷にある、東日本旅客鉄道の駅である。 JR東日本の常磐線を走行する常磐緩行線、武蔵野線、接続路線である流鉄の流鉄流山線を含めると2社3路線が乗り入れている。このうち常磐線を当駅の所属線としている。","d":"千葉県松戸市にある東日本旅客鉄道の駅","t":"新松戸駅"},"新木場":{"x":"新木場駅は、東京都江東区新木場一丁目にある、東京地下鉄・東日本旅客鉄道・東京臨海高速鉄道の駅。","d":"日本の鉄道駅","t":"新木場駅"},"新板橋":{"x":"新板橋駅は、東京都板橋区板橋一丁目にある、東京都交通局三田線の駅である。駅番号はI 17。板橋区の駅では最も東にある。","d":"東京都板橋区板橋にある東京都交通局の駅","t":"新板橋駅"},"新桜台":{"x":"新桜台駅は、東京都練馬区桜台一丁目にある、西武鉄道西武有楽町線の駅である。駅番号はSI38。","d":"東京都練馬区桜台一丁目にある西武鉄道の駅","t":"新桜台駅"},"新日本橋":{"x":"新日本橋駅は、東京都中央区日本橋室町四丁目にある、東日本旅客鉄道総武本線の駅である。駅番号はJO 20。","d":"東京都中央区日本橋室町にある東日本旅客鉄道の駅","t":"新日本橋駅"},"新浦安":{"x":"新浦安駅は、千葉県浦安市入船一丁目にある、東日本旅客鉄道京葉線や武蔵野線の駅である。駅番号はJE 08。京葉線の列車のほか、西船橋駅から武蔵野線に乗り入れる列車も停車する。","d":"千葉県浦安市入船にある東日本旅客鉄道の駅","t":"新浦安駅"},"新高円寺":{"x":"新高円寺駅は、東京都杉並区高円寺南二丁目にある、東京地下鉄丸ノ内線の駅である。駅番号はM 03。","d":"東京都杉並区にある東京地下鉄の駅","t":"新高円寺駅"},"新羽":{"x":"新羽駅は、神奈川県横浜市港北区新羽町字仲町にある、横浜市営地下鉄ブルーラインの駅である。駅番号はB27。新羽車両基地への出入庫線が分岐しており、乗務員交替駅でもある。","d":"神奈川県横浜市港北区新羽町にある横浜市交通局の駅","t":"新羽駅"},"新柴又":{"x":"新柴又駅は、東京都葛飾区柴又五丁目にある、北総鉄道北総線の駅。駅番号はHS01。葛飾区最東端の駅である。","d":"東京都葛飾区柴又にある北総鉄道の駅","t":"新柴又駅"},"新横浜ラーメン博物館":{"x":"新横浜ラーメン博物館は、神奈川県横浜市港北区新横浜にあるラーメンに関するフードテーマパークであるとともに、同館を運営・管理する日本の会社である。通称「ラー博」、全国各地の有名ラーメン店舗を中心に、ミュージアムショップや駄菓子屋、喫茶店・スナックなどを併設している。","d":"神奈川県横浜市港北区にあるフードテーマパーク","t":"新横浜ラーメン博物館"},"新江古田":{"x":"新江古田駅は、東京都中野区江原町二丁目にある、東京都交通局大江戸線の駅。駅番号はE 34。 中野区最北端の駅で、駅構内は中野区と練馬区の境界線上に位置している。","d":"東京都中野区江原町にある東京都交通局の駅","t":"新江古田駅"},"新芝浦":{"x":"新芝浦駅は、神奈川県横浜市鶴見区末広町二丁目にある、東日本旅客鉄道・日本貨物鉄道鶴見線の駅である。駅番号はJI 51。","d":"神奈川県横浜市鶴見区末広町にある東日本旅客鉄道・日本貨物鉄道の駅","t":"新芝浦駅"},"新豊洲":{"x":"新豊洲駅は、東京都江東区豊洲六丁目にある、ゆりかもめ東京臨海新交通臨海線の駅である。駅番号はU 15。","d":"東京都江東区豊洲にあるゆりかもめの駅","t":"新豊洲駅"},"新馬場":{"x":"新馬場駅は、東京都品川区北品川二丁目にある京浜急行電鉄本線の駅である。駅番号はKK03。","d":"東京都品川区北品川にある京浜急行電鉄の駅","t":"新馬場駅"},"新線新宿":{"x":"新宿駅は、東京都新宿区・渋谷区にある、東日本旅客鉄道・京王電鉄・小田急電鉄・東京地下鉄・東京都交通局の駅。 各社間の路線の乗り換えや直通運転も含めた1日あたりの平均乗降者数は約305万人で、世界最多の駅利用者数としてギネス世界記録に認定されている。 新宿地区の中心に位置しており、東京都西部の多摩地域を中心に郊外のベッドタウンを結ぶ中央線や私鉄などの路線と、新宿駅から千代田区や港区といった都心方…","d":"東京の鉄道駅","t":"新宿駅"},"新綱島":{"x":"新綱島駅は、神奈川県横浜市港北区綱島東一丁目にある、東急電鉄東急新横浜線の駅である。駅番号はSH02。","d":"神奈川県横浜市港北区にある東急電鉄の駅","t":"新綱島駅"},"日暮里":{"x":"日暮里駅は、東京都荒川区西日暮里二丁目にある、東日本旅客鉄道・京成電鉄・東京都交通局の駅である。 荒川区最南端の駅で、一部は台東区にまたがる。","d":"東京都荒川区西日暮里にある東日本旅客鉄道・京成電鉄・東京都交通局の駅","t":"日暮里駅"},"方南町":{"x":"方南町駅は、東京都杉並区堀ノ内一丁目にある、東京地下鉄丸ノ内線の駅で、分岐線の終着駅である。駅番号はMb 03。","d":"日本の東京都杉並区堀ノ内にある東京地下鉄の駅","t":"方南町駅"},"日の出":{"x":"日の出駅は、東京都港区海岸二丁目にある、ゆりかもめ東京臨海新交通臨海線の駅である。駅番号はU 04。 東京港2号埋立地にあり、防潮堤より海側のため、高潮警戒時にゲートが閉鎖されると孤立する。","d":"東京都港区海岸にあるゆりかもめの駅","t":"日の出駅"},"旗の台":{"x":"旗の台駅は、東京都品川区旗の台二丁目にある、東急電鉄の駅である。","d":"東京都品川区旗の台にある東急電鉄の駅","t":"旗の台駅"},"日比谷":{"x":"日比谷駅は、東京都千代田区有楽町一丁目にある、東京地下鉄・東京都交通局の駅。","d":"東京都千代田区にある東京地下鉄・東京都交通局の駅","t":"日比谷駅"},"新高島平":{"x":"新高島平駅は、東京都板橋区高島平七丁目にある、東京都交通局三田線の駅である。駅番号はI 26。","d":"東京都板橋区高島平にある東京都交通局の駅","t":"新高島平駅"},"日吉本町":{"x":"日吉本町駅は、神奈川県横浜市港北区日吉本町五丁目に位置する、横浜市営地下鉄グリーンラインの駅である。駅番号はG09。 ステーションカラーは背後に迫る小高い林など、身近な地域の緑をイメージしてきみどり 。","d":"神奈川県横浜市港北区日吉本町にある横浜市交通局の駅","t":"日吉本町駅"},"日本水準原点":{"x":"日本水準原点は、日本の水準測量の基準点である。東京都千代田区永田町1丁目にある日本水準原点標庫という建物の中にある。","t":"日本水準原点"},"旧古河庭園":{"x":"旧古河庭園は、東京都北区西ケ原にある都立庭園である。1919年に古河財閥の古河虎之助男爵の邸宅として現在の形に整えられた。現在は国有財産であり、東京都が借り受けて一般公開している。","d":"東京都北区の公園","t":"旧古河庭園"},"旧岩崎邸庭園":{"x":"旧岩崎邸庭園は、東京都台東区池之端一丁目にある都立庭園である。三菱財閥岩崎家の茅町本邸だった建物とその庭園を公園として整備したもので、園内の歴史的建造物は、国の重要文化財に指定されている。","d":"東京都台東区の公園","t":"旧岩崎邸庭園"},"日本武道館":{"x":"日本武道館は、東京都千代田区北の丸公園2-3にある武道館。日本伝統の武道を普及奨励し、心身錬磨の大道場としての役割を担うことを設立趣旨とする。日本武道協議会加盟。","d":"東京都千代田区にある武道館","t":"日本武道館"},"日本銀行本店":{"x":"日本銀行本店は、日本の銀行建築。東京都中央区日本橋本石町2丁目1番1号に所在する。東京の建築遺産50選に指定されている。","d":"東京都中央区日本橋本石町2丁目1番1号にある日本の銀行建築","t":"日本銀行本店"},"旧朝倉家住宅":{"x":"旧朝倉家住宅は、東京都渋谷区猿楽町に所在する歴史的建造物、国の重要文化財に指定されている。","d":"東京都渋谷区にある民家","t":"旧朝倉家住宅"},"東京ビッグサイト":{"x":"東京ビッグサイト駅は、東京都江東区有明三丁目にある、ゆりかもめ東京臨海新交通臨海線の駅である。駅番号はU 11。","d":"東京都江東区有明にあるゆりかもめの駅","t":"東京ビッグサイト駅"},"東京テレポート":{"x":"東京テレポート駅は、東京都江東区青海一丁目にある、東京臨海高速鉄道りんかい線の駅である。 りんかい線公式ウェブサイトに掲載されている路線図では「」と括弧書きが付されている。駅番号はR 04。","d":"東京都江東区青海にある東京臨海高速鉄道の駅","t":"東京テレポート駅"},"東京都写真美術館":{"x":"東京都写真美術館は、東京都目黒区三田にある、写真表現の総合的専門美術館である。指定管理者制度により、東京都歴史文化財団グループが管理・運営している。","d":"東京都目黒区にある美術館","t":"東京都写真美術館"},"東京国立近代美術館":{"x":"東京国立近代美術館（とうきょうこくりつきんだいびじゅつかん、英語: The National Museum of Modern Art, Tokyo、英略称: MOMAT）は、独立行政法人国立美術館が運営する美術館である。東京都千代田区北の丸公園内にある本館と、石川県金沢市にある国立工芸館から構成される。 明治時代後半から現代までの近現代美術作品を随時コレクションし、常時展示した初めての美術館…","d":"北の丸公園にある美術館","t":"東京国立近代美術館"},"東京国立博物館":{"x":"東京国立博物館は、日本と東洋の文化財の収集保管、展示公開、調査研究、普及などを目的として独立行政法人国立文化財機構が運営する、日本の国立博物館である。東京都台東区の上野恩賜公園内にある。1872年に創設された日本最古かつ最大の博物館であり、本館、表慶館、東洋館、平成館、法隆寺宝物館の5つの展示館と資料館その他の施設からなる。","d":"東京都台東区にある国立博物館","t":"東京国立博物館"},"東京ディズニーシー・ステーション":{"x":"東京ディズニーシー・ステーション駅は、千葉県浦安市舞浜にある、ディズニーリゾートラインの駅である。東京ディズニーシーの最寄り駅。旅客案内上は、東京ディズニーシー・ステーションと呼称される。","d":"千葉県浦安市にある舞浜リゾートラインの駅","t":"東京ディズニーシー・ステーション駅"},"東京国際クルーズターミナル":{"x":"東京国際クルーズターミナル駅は、東京都江東区青海一丁目にある、ゆりかもめ東京臨海新交通臨海線の駅である。駅番号はU 08。江東区最西端の駅である。","d":"東京都江東区青海にあるゆりかもめの駅","t":"東京国際クルーズターミナル駅"},"東京都庭園美術館":{"x":"東京都庭園美術館は、東京都港区白金台にある都立美術館である。旧朝香宮邸とも呼ばれる。","d":"東京都港区にある美術館","t":"東京都庭園美術館"},"東京都現代美術館":{"x":"東京都現代美術館は、東京都江東区三好四丁目にある、現代美術専門の公立美術館。指定管理者制度により、東京都歴史文化財団グループ(公益財団法人東京都歴史文化財団、鹿島建物総合管理株式会社、アサヒビール株式会社の共同事業体)が管理・運営している。施設の大規模改修工事のため、2016年5月30日から2019年3月28日まで休館していたが、翌29日からリニューアルオープンした。","d":"東京都江東区にある美術館","t":"東京都現代美術館"},"東京国際フォーラム":{"x":"東京国際フォーラムは、東京都千代田区丸の内に所在する公的総合文化施設。東京の代表的国際コンベンションセンターの一つ。1997年1月10日に開館し、株式会社東京国際フォーラムが運営する。","d":"東京都千代田区にある総合文化施設","t":"東京国際フォーラム"},"東京ディズニーランド・ステーション":{"x":"東京ディズニーランド・ステーション駅は、千葉県浦安市舞浜にある、ディズニーリゾートラインの駅である。東京ディズニーランドの最寄り駅。旅客案内上は、東京ディズニーランド・ステーションと呼称される。","d":"千葉県浦安市にある舞浜リゾートラインの駅","t":"東京ディズニーランド・ステーション駅"},"東京大学大学院理学系研究科附属植物園":{"x":"東京大学大学院理学系研究科附属植物園（とうきょうだいがくだいがくいんりがくけいけんきゅうかふぞくしょくぶつえん、英: Botanical Gardens, Graduate School of Science, the University of Tokyo）は、東京都文京区白山三丁目にある植物園。小石川植物園の通称を持つ。 植物に関する様々な研究を行っている東京大学の附属施設の一つだが、広く…","d":"東京大学の附属施設の一つ","t":"東京大学大学院理学系研究科附属植物園"},"東京大学総合研究博物館小石川分館":{"x":"本稿では東京大学の建造物について解説する。","d":"東京大学の学内に存在する建造物","t":"東京大学の建造物"},"東京ディズニーシー":{"x":"東京ディズニーシーは、千葉県浦安市舞浜にある東京ディズニーリゾートを構成するテーマパーク。 世界で唯一「海」をテーマにしたディズニーパークで、2001年9月4日に開園した。京成電鉄と三井不動産などが出資して設立したオリエンタルランドが所有し、アメリカのウォルト・ディズニー・カンパニーからテーマのライセンスを受けている。","d":"千葉県浦安市にあるテーマパーク","t":"東京ディズニーシー"},"東京ディズニーリゾート":{"x":"東京ディズニーリゾートは、千葉県浦安市にあるテーマパークを含む複合リゾート。 1983年4月15日に単一のテーマパークとして開業した東京ディズニーランド、2001年9月4日に開業した世界のディズニーパークで初めて「海」をテーマとした第2のパークである東京ディズニーシー、さらに6つのディズニーホテル、6つのオフィシャルホテル、商業施設のイクスピアリ、ボン・ヴォヤージュ、多目的ホールの舞浜アンフィ…","d":"千葉県浦安市にあるテーマパーク","t":"東京ディズニーリゾート"},"東京タワー":{"x":"東京タワーは、東京都港区芝公園にある総合電波塔。 1958年12月23日に竣工。東京のシンボルで、観光名所となっている。","d":"東京都港区にある電波塔","t":"東京タワー"},"東京カテドラル聖マリア大聖堂":{"x":"カトリック関口教会は、東京都文京区関口にあるキリスト教の教会。カトリック東京大司教区の司教座聖堂であり、教会堂名が「無原罪の聖母」であることから、東京カテドラル聖マリア大聖堂として知られている。 本項では、教会としてのカトリック関口教会だけでなく、建築物としての東京カテドラル聖マリア大聖堂についても記述する。","d":"東京都文京区の教会","t":"カトリック関口教会"},"東京ディズニーランド":{"x":"東京ディズニーランドは、千葉県浦安市にある東京ディズニーリゾートを構成するテーマパーク。 アメリカのカリフォルニア州にあるディズニーランド・パーク、フロリダ州のマジック・キングダムに次ぎ3番目、アメリカ国外で最初に建設されたディズニーパークで、1983年4月15日にオープンした。京成電鉄と三井不動産などが出資して設立されたオリエンタルランドが所有し、アメリカのウォルト・ディズニー・カンパニーか…","d":"千葉県浦安市にあるテーマパーク","t":"東京ディズニーランド"},"東京ワンピースタワー":{"x":"東京ワンピースタワーは、東京都港区の東京タワー「フットタウン」内にあった、漫画『ONE PIECE』をテーマとしたテーマパーク。2015年3月13日に開園。2016年6月18日、2020年3月18日にリニューアルオープン。","d":"日本のテーマパーク","t":"東京ワンピースタワー"},"東十条":{"x":"東十条駅は、東京都北区東十条三丁目にある、東日本旅客鉄道の駅である。駅番号はJK 37。 乗り入れている路線は線路名称上は東北本線であるが、当駅には電車線を走る京浜東北線電車のみが停車し、旅客案内では「東北線」とは案内されていない。","d":"東京都北区東十条にある東日本旅客鉄道の駅","t":"東十条駅"},"東池袋":{"x":"東池袋駅は、東京都豊島区東池袋四丁目にある、東京地下鉄有楽町線の駅である。駅番号はY 10。","d":"東京都豊島区にある東京地下鉄の駅","t":"東池袋駅"},"東池袋四丁目":{"x":"東池袋四丁目停留場は、東京都豊島区東池袋四丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 25。 サンシャインシティへの最寄停留場であり、「サンシャイン前」の停留場副名称を持つ。","d":"東京都豊島区東池袋にある東京都交通局の停留場","t":"東池袋四丁目停留場"},"東日本橋":{"x":"東日本橋駅は、東京都中央区東日本橋三丁目にある、東京都交通局浅草線の駅。駅番号はA 15。 東京都中央区の北東部に立地する地下鉄駅である。","d":"東京都中央区東日本橋にある東京都交通局の駅","t":"東日本橋駅"},"東松原":{"x":"東松原駅は、東京都世田谷区松原五丁目にある、京王電鉄井の頭線の駅である。井の頭南管区所属。駅番号はIN07。","d":"東京都世田谷区松原にある京王電鉄の駅","t":"東松原駅"},"東北沢":{"x":"東北沢駅は、東京都世田谷区北沢三丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 06。","d":"東京都世田谷区北沢にある小田急電鉄の駅","t":"東北沢駅"},"東銀座":{"x":"東銀座駅は、東京都中央区銀座四丁目にある、東京都交通局・東京地下鉄の駅。 都営地下鉄の浅草線と、東京メトロの日比谷線が乗り入れる。駅番号は浅草線がA 11、日比谷線がH 10。","d":"東京都中央区にある東京都交通局・東京地下鉄の駅","t":"東銀座駅"},"東向島":{"x":"東向島駅は、東京都墨田区東向島四丁目にある東武鉄道伊勢崎線の駅である。「東武スカイツリーライン」の愛称区間に含まれている。駅番号はTS 05。","d":"東京都墨田区東向島にある東武鉄道の駅","t":"東向島駅"},"東大前":{"x":"東大前駅は、東京都文京区向丘一丁目にある、東京地下鉄南北線の駅である。駅番号はN 12。駅名の通り、東京大学への最寄り駅の一つである。","d":"東京都文京区にある東京地下鉄の駅","t":"東大前駅"},"東大島":{"x":"東大島駅は、東京都江東区大島九丁目にある、東京都交通局新宿線の駅。駅番号はS 16。 旧中川上を横断して駅ホームが設けられており、東側は江戸川区小松川一丁目にまたがる。","d":"東京都江東区大島にある東京都交通局の駅","t":"東大島駅"},"東京都美術館":{"x":"東京都美術館は、東京都台東区上野公園8番36号にある都立美術館である。略称都美。旧称東京府美術館。","d":"東京都台東区にある美術館","t":"東京都美術館"},"東長崎":{"x":"東長崎駅は、東京都豊島区長崎五丁目にある、西武鉄道池袋線の駅である。駅番号はSI03。豊島区最西端の駅。","d":"東京都豊島区にある西武鉄道の駅","t":"東長崎駅"},"東伏見":{"x":"東伏見駅は、東京都西東京市東伏見二丁目にある、西武鉄道新宿線の駅。駅番号はSS15。","d":"東京都西東京市にある西武鉄道の駅","t":"東伏見駅"},"東山田":{"x":"東山田駅は、神奈川県横浜市都筑区東山田町にある、横浜市営地下鉄グリーンラインの駅である。駅番号はG07。 ステーションカラーは駅周辺の畑や果樹園等の豊かな自然・大地をイメージしてちゃいろ） 。","d":"神奈川県横浜市都筑区東山田町にある横浜市交通局の駅","t":"東山田駅"},"東新宿":{"x":"東新宿駅は、東京都新宿区新宿七丁目にある、東京都交通局・東京地下鉄の駅。","d":"東京都新宿区新宿七丁目にある東京都交通局・東京地下鉄の駅","t":"東新宿駅"},"東京":{"x":"東京駅は、東京都千代田区丸の内一丁目にある、東日本旅客鉄道・東海旅客鉄道・東京地下鉄の駅。JR東日本の在来線と新幹線各路線、JR東海の東海道新幹線、東京メトロの丸ノ内線が発着するターミナル駅。 1日の乗降人員数は約126万人で、日本で6番目に利用者数の多い駅である。","d":"東京都千代田区にある駅","t":"東京駅"},"板橋":{"x":"板橋駅は、東京都北区滝野川七丁目にある、東日本旅客鉄道の駅。駅番号はJA 13。 当駅を通る鉄道路線は、線路名称上は赤羽線であるが、運行系統上は埼京線として案内される。","d":"東京都北区滝野川にある東日本旅客鉄道の駅","t":"板橋駅"},"柴崎":{"x":"柴崎駅は、東京都調布市菊野台二丁目にある、京王電鉄京王線の駅である。京王中央管区所属。駅番号はKO15。","d":"東京都調布市菊野台にある京王電鉄の駅","t":"柴崎駅"},"松戸":{"x":"松戸駅は、千葉県松戸市松戸にある、東日本旅客鉄道・京成電鉄の駅である。","d":"千葉県松戸市松戸にある東日本旅客鉄道・京成電鉄の駅","t":"松戸駅"},"柴又":{"x":"柴又駅は、東京都葛飾区柴又四丁目にある京成電鉄金町線の駅。駅番号はKS50。","d":"日本の鉄道駅","t":"柴又駅"},"板橋区役所前":{"x":"板橋区役所前駅は、東京都板橋区板橋二丁目にある、東京都交通局三田線の駅。駅番号はI 18。","d":"東京都板橋区にある東京都交通局の駅","t":"板橋区役所前駅"},"松戸新田":{"x":"松戸新田駅は、千葉県松戸市松戸新田にある、京成電鉄松戸線の駅である。駅番号はKS86。","d":"千葉県松戸市松戸新田にある京成電鉄の駅","t":"松戸新田駅"},"東陽町":{"x":"東陽町駅は、東京都江東区東陽四丁目にある、東京地下鉄東西線の駅である。駅番号はT 14。","d":"東京都江東区にある東京地下鉄の駅","t":"東陽町駅"},"東高円寺":{"x":"東高円寺駅は、東京都杉並区和田三丁目にある、東京地下鉄丸ノ内線の駅である。駅番号はM 04。杉並区最東端の駅であり、杉並区内で最も新しい駅である。","d":"東京都杉並区にある東京地下鉄の駅","t":"東高円寺駅"},"板橋本町":{"x":"板橋本町駅は、東京都板橋区大和町にある、東京都交通局三田線の駅。駅番号はI 19。","d":"東京都板橋区にある東京都交通局の駅","t":"板橋本町駅"},"柳瀬川":{"x":"柳瀬川駅は、埼玉県志木市館二丁目にある、東武鉄道東上本線の駅である。駅番号はTJ 15。","d":"埼玉県志木市館にある東武鉄道の駅","t":"柳瀬川駅"},"東門前":{"x":"東門前駅は、神奈川県川崎市川崎区中瀬三丁目にある、京浜急行電鉄大師線の駅である。駅番号はKK24。","d":"神奈川県川崎市川崎区中瀬にある京浜急行電鉄の駅","t":"東門前駅"},"松陰神社前":{"x":"松陰神社前駅は、東京都世田谷区若林四丁目にある、東急電鉄世田谷線の停留場である。駅番号はSG04。","d":"東京都世田谷区若林にある東急電鉄の駅","t":"松陰神社前駅"},"根津神社":{"x":"根津神社は、東京都文京区根津にある神社。旧社格は府社で、元准勅祭社。つつじの名所として有名。","d":"東京都文京区の神社","t":"根津神社"},"松林図屏風":{"x":"松林図屏風は、安土桃山時代の絵師・長谷川等伯の代表作。紙本墨画、六曲一双、各縦156.8cm横356.0cmの屏風画である。「美術史上日本の水墨画を自立させた」と称される、近世日本水墨画の代表作のひとつ。","d":"長谷川等伯の屏風画","t":"松林図屏風"},"歌舞伎座":{"x":"歌舞伎座は東銀座にある、日本で唯一の歌舞伎専用の劇場である。","d":"日本の劇場","t":"歌舞伎座"},"横浜国際総合競技場":{"x":"横浜国際総合競技場は、神奈川県横浜市港北区の新横浜公園内にある陸上競技場兼球技場。施設は横浜市が所有し、横浜市スポーツ協会・横浜マリノス・管理JV共同事業体が指定管理者として運営管理を行っている。 横浜市西区に本社を置き、横浜F・マリノスのトップパートナーでもある日産自動車が命名権を取得しており、2005年3月1日より「日産スタジアム」の呼称を使用している。","d":"横浜市にある陸上競技場","t":"横浜国際総合競技場"},"梅島":{"x":"梅島駅は、東京都足立区梅田七丁目にある、東武鉄道伊勢崎線の駅である。「東武スカイツリーライン」の愛称区間に含まれている。駅番号はTS 12。","d":"東京都足立区梅田にある東武鉄道の駅","t":"梅島駅"},"梶が谷":{"x":"梶が谷駅は、神奈川県川崎市高津区末長一丁目にある、東急電鉄田園都市線の駅である。駅番号はDT11。","d":"神奈川県川崎市高津区にある東急電鉄の駅","t":"梶が谷駅"},"桜新町":{"x":"桜新町駅は、東京都世田谷区桜新町二丁目にある、東急電鉄田園都市線の駅である。駅番号はDT05。","d":"東京都世田谷区桜新町にある東急電鉄の駅","t":"桜新町駅"},"桜田門":{"x":"桜田門は、東京都千代田区皇居外苑にある門の一つ。かつて江戸城の内郭門のひとつだった。城の南西にあたる。","d":"皇居（かつての江戸城）の門のひとつ","t":"桜田門"},"武蔵中原":{"x":"武蔵中原駅は、神奈川県川崎市中原区上小田中六丁目にある、東日本旅客鉄道南武線の駅である。駅番号はJN 08。","d":"神奈川県川崎市中原区にある東日本旅客鉄道の駅","t":"武蔵中原駅"},"桜上水":{"x":"桜上水駅は、東京都世田谷区桜上水五丁目にある、京王電鉄京王線の駅。京王東管区所属で、管区長所在駅。駅番号はKO08。","d":"東京都世田谷区桜上水にある京王電鉄の駅","t":"桜上水駅"},"梅ヶ丘":{"x":"梅ヶ丘駅は、東京都世田谷区梅丘一丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 09。","d":"東京都世田谷区梅丘にある小田急電鉄の駅","t":"梅ヶ丘駅"},"根津":{"x":"根津駅は、東京都文京区根津一丁目にある、東京地下鉄千代田線の駅である。駅番号はC 14。","d":"東京都文京区にある東京地下鉄の駅","t":"根津駅"},"森美術館":{"x":"森美術館という名称をもつ美術館は、以下の2館がある。 東京都港区の六本木ヒルズ森タワー内にある美術館施設。本項ではこれについて詳述する。","d":"東京都港区の六本木ヒルズにある美術館","t":"森美術館"},"根津美術館":{"x":"根津美術館は、東京都港区南青山に所在する、公益財団法人根津美術館により運営される美術館である。現在の英称は Nezu Museum、以前は Nezu Institute of Fine Arts であった。 1941年11月に、前年に没した根津財閥創設者の初代根津嘉一郎の古美術コレクションを引き継く形で、邸宅を改装し財団法人根津美術館として開館した。","d":"東京都港区にある美術館","t":"根津美術館"},"椎名町":{"x":"椎名町駅は、東京都豊島区長崎一丁目にある、西武鉄道池袋線の駅である。駅番号はSI02。同線の駅の中では一番海抜の低い場所に位置する。","d":"東京都豊島区長崎一丁目にある西武鉄道の駅","t":"椎名町駅"},"梶原":{"x":"梶原停留場は、東京都北区上中里三丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 14。","d":"東京都北区上中里にある東京都交通局の停留場","t":"梶原停留場"},"横浜アリーナ":{"x":"横浜アリーナは、神奈川県横浜市港北区にある多目的ホール。1989年4月1日に開館した。株式会社横浜アリーナが管理・運営を行う。","d":"横浜市港北区新横浜の多目的施設","t":"横浜アリーナ"},"横山大観記念館":{"x":"横山大観記念館は、東京都台東区池之端にある記念館。近代日本画の巨匠として知られる横山大観を記念して、1976年に開設された。子孫が理事を務める公益財団法人横山大観記念館が運営している。","d":"東京都台東区池之端にある記念館","t":"横山大観記念館"},"武蔵境":{"x":"武蔵境駅は、東京都武蔵野市にある、東日本旅客鉄道・日本貨物鉄道・西武鉄道の駅。","d":"東京都武蔵野市にある東日本旅客鉄道・日本貨物鉄道・西武鉄道の駅","t":"武蔵境駅"},"水道橋":{"x":"水道橋駅は、東京都千代田区・文京区にある、東日本旅客鉄道・東京都交通局の駅である。","d":"東京都千代田区・文京区にある東日本旅客鉄道・東京都交通局の駅","t":"水道橋駅"},"武蔵浦和":{"x":"武蔵浦和駅は、埼玉県さいたま市南区別所七丁目にある、東日本旅客鉄道の駅である。","d":"埼玉県さいたま市南区別所にある東日本旅客鉄道の駅","t":"武蔵浦和駅"},"武蔵小杉":{"x":"武蔵小杉駅は、神奈川県川崎市中原区にある、東日本旅客鉄道・東急電鉄の駅。 南武線と東急電鉄の駅は小杉町三丁目に、横須賀線の駅は新丸子東三丁目に、それぞれ所在する。","d":"神奈川県川崎市中原区にある東日本旅客鉄道・東急電鉄の駅","t":"武蔵小杉駅"},"水天宮前":{"x":"水天宮前駅は、東京都中央区日本橋蛎殻町二丁目にある、東京地下鉄半蔵門線の駅である。駅番号はZ 10。 副駅名は東京シティエアターミナル前。","d":"東京都中央区にある東京地下鉄の駅","t":"水天宮前駅"},"汐留":{"x":"汐留駅は、東京都港区東新橋一丁目にある、東京都交通局・ゆりかもめの駅である。 東京都交通局の都営地下鉄大江戸線と、ゆりかもめの東京臨海新交通臨海線が乗り入れ、接続駅となっている。両社局とも駅番号が制定されており、都営地下鉄がE 19、ゆりかもめはU 02である。","d":"東京都港区東新橋にある東京都交通局・ゆりかもめの駅","t":"汐留駅"},"武蔵溝ノ口":{"x":"武蔵溝ノ口駅は、神奈川県川崎市高津区溝口一丁目にある、東日本旅客鉄道南武線の駅。駅番号はJN 10。 川崎市民および利用者の大半は、当駅との乗換駅である東急田園都市線・大井町線の溝の口駅を含む駅周辺を「ノクチ」と呼ぶことが多く、駅ビル「ノクティプラザ」の名称の由来にもなっている。","d":"神奈川県川崎市高津区溝口にある東日本旅客鉄道の駅","t":"武蔵溝ノ口駅"},"氷川台":{"x":"氷川台駅は、東京都練馬区氷川台三丁目にある、東京地下鉄の駅。 有楽町線・副都心線が乗り入れる。当駅を含む和光市駅 - 小竹向原駅の区間は、有楽町線と副都心線が線路を共有している。","d":"東京都練馬区にある東京地下鉄の駅","t":"氷川台駅"},"江古田":{"x":"江古田駅は、東京都練馬区旭丘一丁目にある、西武鉄道池袋線の駅である。駅番号はSI04。 練馬駅から分岐する豊島線の列車も利用可能である。","d":"東京都練馬区にある西武鉄道の駅","t":"江古田駅"},"永田町":{"x":"永田町駅は、東京都千代田区永田町一丁目にある、東京地下鉄の駅。","d":"東京都千代田区にある東京地下鉄の駅","t":"永田町駅"},"武蔵新城":{"x":"武蔵新城駅は、神奈川県川崎市中原区上新城二丁目にある、東日本旅客鉄道南武線の駅である。駅番号はJN 09。","d":"神奈川県川崎市中原区上新城にある東日本旅客鉄道の駅","t":"武蔵新城駅"},"永福町":{"x":"永福町駅は、東京都杉並区永福二丁目にある、京王電鉄井の頭線の駅である。井の頭北管区所属。駅番号はIN09。","d":"東京都杉並区永福にある京王電鉄の駅","t":"永福町駅"},"武蔵小山":{"x":"武蔵小山駅は、東京都品川区小山三丁目にある、東急電鉄目黒線の駅である。駅番号はMG03。","d":"東京都品川区小山にある東急電鉄の駅","t":"武蔵小山駅"},"武蔵白石":{"x":"武蔵白石駅は、神奈川県川崎市川崎区白石町にある、東日本旅客鉄道鶴見線の駅である。駅番号はJI 07。","d":"神奈川県川崎市川崎区白石町にある東日本旅客鉄道の駅","t":"武蔵白石駅"},"武蔵関":{"x":"武蔵関駅は、東京都練馬区関町北二丁目にある、西武鉄道新宿線の駅である。駅番号はSS14。練馬区かつ東京都区部の最西端の駅である。","d":"東京都練馬区にある西武鉄道の駅","t":"武蔵関駅"},"江戸城":{"x":"江戸城は、室町期から江戸期にかけて武蔵国荏原郡桜田郷の麹町台地の東端に築かれた平山城。関東平野の南端、東京湾の北隅に位置し、関東の陸上交通・水上交通の要だった。この桜田郷は平川を挟んで東岸側の豊嶋郡江戸郷に接し鎌倉時代より一体とみなされ「江戸」の名を持つ。","d":"東京都千代田区にあった城（現・皇居）","t":"江戸城"},"永代橋":{"x":"永代橋は、隅田川にかかる橋。東京都道・千葉県道10号東京浦安線を通す。西岸は中央区新川一丁目、東岸は江東区佐賀一丁目及び同区永代一丁目。","d":"東京都の橋","t":"永代橋"},"武蔵新田":{"x":"武蔵新田駅は、東京都大田区矢口一丁目にある、東急電鉄東急多摩川線の駅である。駅番号はTM05。","d":"東京都大田区矢口にある東急電鉄の駅","t":"武蔵新田駅"},"江戸幕府":{"x":"江戸幕府は、江戸時代における日本の武家政権。1603年に徳川家康が征夷大将軍に補任され、江戸を本拠として創立した。諸説あるが、大政奉還が行われた1867年までの約264年間続いたとされる。","d":"徳川氏による日本の武家政権","t":"江戸幕府"},"泉岳寺":{"x":"泉岳寺は、東京都港区高輪二丁目にある曹洞宗の寺院。青松寺・総泉寺とともに曹洞宗江戸三箇寺の1つに数えられる。","d":"東京都港区にある仏教寺院","t":"泉岳寺"},"池尻大橋":{"x":"池尻大橋駅は、東京都世田谷区池尻三丁目にある、東急電鉄田園都市線の駅である。駅番号はDT 02。 世田谷区最東端の駅である。","d":"東京都世田谷区池尻にある東急電鉄の駅","t":"池尻大橋駅"},"江戸川橋":{"x":"江戸川橋駅は、東京都文京区関口一丁目にある、東京地下鉄有楽町線の駅である。駅番号はY 12。","d":"東京都文京区にある東京地下鉄の駅","t":"江戸川橋駅"},"津田山":{"x":"津田山駅は、神奈川県川崎市高津区下作延六丁目にある、東日本旅客鉄道南武線の駅である。駅番号はJN 11。","d":"神奈川県川崎市高津区下作延にある東日本旅客鉄道の駅","t":"津田山駅"},"池ノ上":{"x":"池ノ上駅は、東京都世田谷区代沢二丁目にある、京王電鉄井の頭線の駅である。井の頭南管区所属。駅番号はIN04。","d":"東京都世田谷区代沢にある京王電鉄の駅","t":"池ノ上駅"},"沼袋":{"x":"沼袋駅は、東京都中野区沼袋一丁目にある西武鉄道新宿線の駅である。駅番号はSS06。","d":"東京都中野区にある西武鉄道の駅","t":"沼袋駅"},"江戸川":{"x":"江戸川駅は、東京都江戸川区北小岩三丁目にある、京成電鉄本線の駅である。駅番号はKS12。","d":"東京都江戸川区北小岩にある京成電鉄の駅","t":"江戸川駅"},"池上本門寺":{"x":"池上本門寺は、東京都大田区池上にある日蓮宗の大本山。 寺格は大本山、山号を長栄山、院号を大国院、寺号を本門寺とし、古くより池上本門寺と呼ばれてきた。また日蓮入滅の霊場として日蓮宗の十四霊蹟寺院のひとつとされ、七大本山のひとつにも挙げられている。","d":"東京都大田区にある仏教寺院","t":"池上本門寺"},"洗足":{"x":"洗足駅は、東京都目黒区洗足二丁目にある、東急電鉄目黒線の駅である。駅番号はMG05。東急目黒線では唯一、目黒区に所在する駅である。","d":"東京都目黒区洗足にある東急電鉄の駅","t":"洗足駅"},"池上":{"x":"池上駅は、東京都大田区池上六丁目にある、東急電鉄池上線の駅である。駅番号はIK13。","d":"東京都大田区池上にある東急電鉄の駅","t":"池上駅"},"洗足池":{"x":"洗足池駅は、東京都大田区東雪谷一丁目にある、東急電鉄池上線の駅である。駅番号はIK07。","d":"京都大田区東雪谷にある東急電鉄の駅","t":"洗足池駅"},"沼部":{"x":"沼部駅は、東京都大田区田園調布本町にある、東急電鉄東急多摩川線の駅である。駅番号はTM02。","d":"東京都大田区田園調布本町にある東急電鉄の駅","t":"沼部駅"},"法務省旧本館":{"x":"法務省旧本館は、東京都千代田区霞が関にある歴史的建造物である。中央合同庁舎第6号館赤れんが棟ともいう。","d":"東京都千代田区霞が関にある歴史的建造物","t":"法務省旧本館"},"池袋":{"x":"池袋駅は、東京都豊島区にある、東日本旅客鉄道・東武鉄道・西武鉄道・東京地下鉄の駅である。 東京3大副都心の一つである池袋に位置するターミナル駅。全体の1日平均の乗降人員数は約236万人で、新宿駅、渋谷駅に次いで世界第3位の利用者数となっている。","d":"東京の鉄道駅","t":"池袋駅"},"江戸城跡のヒカリゴケ生育地":{"x":"江戸城跡のヒカリゴケ生育地は、東京都千代田区北の丸公園にある、国の天然記念物に指定されたヒカリゴケの自生地である。 ヒカリゴケは、ヒカリゴケ科ヒカリゴケ属の原始的なコケ植物で、直射日光の乏しい洞窟や石垣の隙間などに生育して黄緑色に光るコケである。日本国内における生育は1910年に長野県の岩村田町で確認されたのが最初で、この場所は岩村田ヒカリゴケ産地として1921年に国の天然記念物に指定され、そ…","d":"日本の天然記念物","t":"江戸城跡のヒカリゴケ生育地"},"浜松町":{"x":"浜松町駅は、東京都港区にある、東日本旅客鉄道の駅である。 本項では、ほぼ同位置に所在する東京モノレール羽田空港線のモノレール浜松町駅についても扱う。 所在地は、JR東日本が海岸一丁目、東京モノレールが浜松町二丁目となっている。","d":"東京都港区にある東日本旅客鉄道・東京モノレールの駅","t":"浜松町駅"},"浅草橋":{"x":"浅草橋駅は、東京都台東区浅草橋一丁目にある、東日本旅客鉄道・東京都交通局の駅である。台東区の駅で最も南に位置する。 JR東日本の総武本線の支線と、都営地下鉄の浅草線が乗り入れ、接続駅となっている。","d":"東京都台東区にある東日本旅客鉄道・東京都交通局の駅","t":"浅草橋駅"},"浅草":{"x":"浅草駅は、東京都台東区にある、東武鉄道・東京地下鉄・東京都交通局の駅である。 台東区最東端の駅である。所在地は東京メトロが浅草一丁目、東武鉄道が花川戸一丁目、都営地下鉄が駒形一丁目である。","d":"東京の鉄道駅","t":"浅草駅"},"浅草寺":{"x":"浅草寺は、東京都台東区浅草二丁目にある都内最古の寺で、正式には金龍山浅草寺と号する。聖観世音菩薩を本尊とすることから、浅草観音とも呼ばれている。山号は金龍山。","d":"東京都台東区にある仏教寺院","t":"浅草寺"},"浜田山":{"x":"浜田山駅は、東京都杉並区浜田山三丁目にある、京王電鉄井の頭線の駅である。井の頭北管区所属。駅番号はIN11。","d":"東京都杉並区浜田山にある京王電鉄の駅","t":"浜田山駅"},"淡路町":{"x":"淡路町駅は、東京都千代田区神田淡路町一丁目にある、東京地下鉄丸ノ内線の駅。駅番号はM 19。","d":"東京都千代田区にある東京地下鉄の駅","t":"淡路町駅"},"浜町":{"x":"浜町駅は、東京都中央区日本橋浜町二丁目にある、東京都交通局新宿線の駅である。中央区最東端の駅。駅番号はS 10。","d":"東京都中央区にある東京都交通局の駅","t":"浜町駅"},"浮間舟渡":{"x":"浮間舟渡駅は、東京都北区浮間四丁目にある、東日本旅客鉄道の駅である。駅番号はJA 17。北区最北端かつ最西端の駅でもある。","d":"東京都北区浮間にある東日本旅客鉄道の駅","t":"浮間舟渡駅"},"浅野":{"x":"浅野駅は、神奈川県横浜市鶴見区末広町二丁目にある、東日本旅客鉄道鶴見線の駅である。JRの特定都区市内制度における「横浜市内」の駅。駅番号はJI 05。","d":"神奈川県横浜市鶴見区末広町にある東日本旅客鉄道の駅","t":"浅野駅"},"浜川崎":{"x":"浜川崎駅は、神奈川県川崎市川崎区にある、東日本旅客鉄道・日本貨物鉄道の駅である。","d":"神奈川県川崎市にある東日本旅客鉄道・日本貨物鉄道の駅","t":"浜川崎駅"},"流通センター":{"x":"流通センター駅は、東京都大田区平和島六丁目にある東京モノレール羽田空港線の駅である。駅番号はMO 04。","d":"東京都大田区平和島にある東京モノレールの駅","t":"流通センター駅"},"浮島町":{"x":"浮島町駅は、神奈川県川崎市川崎区浮島町の南部にある神奈川臨海鉄道浮島線の貨物駅。同線の終点。 神奈川県の鉄道駅では最東端に位置する。","d":"日本の神奈川県川崎市川崎区にある神奈川臨海鉄道の貨物駅","t":"浮島町駅"},"浜離宮恩賜庭園":{"x":"浜離宮恩賜庭園は、東京都中央区浜離宮庭園にある潮入の池と二つの鴨場をもつ都立庭園である。旧浜離宮庭園として特別史跡・特別名勝に指定されている。","d":"東京都中央区の公園","t":"浜離宮恩賜庭園"},"浅草神社":{"x":"浅草神社は、東京都台東区浅草に所在する浅草寺本堂の東隣りにある神社である。通称に三社権現、三社様。5月例大祭は三社祭という。","d":"東京都台東区の神社","t":"浅草神社"},"清洲橋":{"x":"清洲橋は、隅田川にかかる橋で、東京都道474号浜町北砂町線を通す。西岸は中央区日本橋中洲、東岸は江東区清澄一丁目。「清洲」という名称は公募により、建設当時の両岸である深川区清住町と日本橋区中洲町から採られた。","d":"東京都の橋","t":"清洲橋"},"浜安善":{"x":"浜安善駅は、かつて神奈川県横浜市鶴見区安善町2丁目に存在した日本国有鉄道鶴見線の貨物駅。かつては旅客営業も行っていた。 駅は廃止されているものの、安善駅と当駅の間の路線は安善駅構内側線扱いとして現存する。","d":"かつて神奈川県横浜市鶴見区安善町にあった日本国有鉄道の駅","t":"浜安善駅"},"深大寺城":{"x":"深大寺城は、東京都調布市深大寺元町にあった日本の城。国の史跡。所在地は深大寺元町5丁目31-10。","d":"日本の城","t":"深大寺城"},"浮世絵 太田記念美術館":{"x":"太田記念美術館は、東京都渋谷区にある浮世絵専門の私設美術館である。 東邦生命保険相互会社会長などの重職を歴任し、実業界の大立者であった5代目太田清蔵のコレクションを基礎に、1980年1月に開館した。内訳は肉筆浮世絵約500点、浮世絵版画約1万点、浮世絵関係の版本及び骨董品約200点、旧鴻池コレクションの扇面画約900点、さらに浮世絵研究家の長瀬武郎から寄贈された肉筆画と版画約650点で、総計1…","d":"東京都渋谷区にある美術館","t":"太田記念美術館"},"清水門":{"x":"清水門は、東京都千代田区北の丸公園内にある、旧江戸城の門。東面する高麗門と南側に矩折りに建つ櫓門からなる桝形門である。1961年に「旧江戸城清水門」として国の重要文化財に指定されている。","d":"東京都千代田区北の丸公園内にある江戸城の門","t":"清水門"},"溝の口":{"x":"溝の口駅は、神奈川県川崎市高津区溝口二丁目にある、東急電鉄の駅である。","d":"神奈川県川崎市高津区にある東急電鉄の駅","t":"溝の口駅"},"溜池山王":{"x":"溜池山王駅は、東京都千代田区永田町二丁目にある、東京地下鉄の駅。","d":"日本の鉄道駅","t":"溜池山王駅"},"清澄白河":{"x":"清澄白河駅は、東京都江東区白河一丁目にある、東京都交通局・東京地下鉄の駅。 都営地下鉄の大江戸線と、東京メトロの半蔵門線が乗り入れ、接続駅となっている。それぞれ駅番号が与えられており、大江戸線がE 14、半蔵門線がZ 11。","d":"東京都江東区にある東京地下鉄・東京都交通局の駅","t":"清澄白河駅"},"潮見":{"x":"潮見駅は、東京都江東区潮見二丁目にある、東日本旅客鉄道京葉線の駅である。駅番号はJE 04。 京葉線の列車のほか、西船橋駅から武蔵野線に乗り入れる列車も停車する。","d":"東京都江東区潮見二丁目にある東日本旅客鉄道の駅","t":"潮見駅"},"片倉町":{"x":"片倉町駅は、神奈川県横浜市神奈川区片倉一丁目にある、横浜市営地下鉄ブルーラインの駅である。駅番号はB23。","d":"神奈川県横浜市神奈川区片倉にある横浜市交通局の駅","t":"片倉町駅"},"狛江":{"x":"狛江駅は、東京都狛江市東和泉一丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 16。","d":"東京都狛江市東和泉にある小田急電鉄の駅","t":"狛江駅"},"湯島":{"x":"湯島駅は、東京都文京区湯島三丁目にある、東京地下鉄千代田線の駅である。駅番号はC 13。文京区最東端の駅。","d":"東京都文京区にある東京地下鉄の駅","t":"湯島駅"},"牛込柳町":{"x":"牛込柳町駅は、東京都新宿区原町二丁目にある、東京都交通局大江戸線の駅である。駅番号はE 04。","d":"東京都新宿区原町二丁目にある東京都交通局の駅","t":"牛込柳町駅"},"牛込神楽坂":{"x":"牛込神楽坂駅は、東京都新宿区箪笥町にある、東京都交通局大江戸線の駅である。駅番号はE 05。 駅業務は東京都営交通協力会に委託されている。","d":"東京都新宿区箪笥町にある東京都交通局の駅","t":"牛込神楽坂駅"},"獨協大学前":{"x":"獨協大学前駅は、埼玉県草加市松原一丁目にある、東武鉄道伊勢崎線の駅である。「東武スカイツリーライン」の愛称区間に含まれている。駅番号はTS 17。","d":"埼玉県草加市松原一丁目にある東武鉄道の駅","t":"獨協大学前駅"},"湯島聖堂":{"x":"湯島聖堂は、東京都文京区湯島一丁目にある史跡。江戸時代の元禄3年、江戸幕府5代将軍徳川綱吉によって建てられた孔子廟であり、後に幕府直轄の学問所となった。JR中央線の御茶ノ水駅聖橋口からでて、聖橋を渡り右手の森の中にあり、「日本の学校教育発祥の地」の掲示がある。","d":"東京都文京区にある史跡","t":"湯島聖堂"},"熊野前":{"x":"熊野前駅は、東京都荒川区東尾久にある、東京都交通局日暮里・舎人ライナーの駅。 本項目では、近接する都電荒川線の停留場である熊野前停留場についても説明する。","d":"東京都荒川区東尾久にある東京都交通局の駅、停留場","t":"熊野前駅"},"港町":{"x":"港町駅は、神奈川県川崎市川崎区港町にある、京浜急行電鉄大師線の駅である。駅番号はKK21。","d":"神奈川県川崎市川崎区港町にある京浜急行電鉄の駅","t":"港町駅"},"滝野川一丁目":{"x":"滝野川一丁目停留場は、東京都北区滝野川一丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 18。","d":"東京都北区滝野川にある東京都交通局の停留場","t":"滝野川一丁目停留場"},"湯島天満宮":{"x":"湯島天満宮は、東京都文京区湯島三丁目にある天満宮で、菅原道真を含む二柱の祭神を祀る神社。通称は湯島天神、旧称は湯島神社。 旧社格は府社で、現在は神社本庁の別表神社。","d":"東京都文京区にある神社","t":"湯島天満宮"},"清澄庭園":{"x":"清澄庭園は、東京都江東区清澄にある都立庭園。池の周囲に築山や名石を配置した回遊式林泉庭園で、東京都指定名勝に指定されている。","d":"東京都江東区清澄にある都立庭園","t":"清澄庭園"},"渋沢史料館":{"x":"渋沢史料館は、東京都北区西ケ原にある渋沢栄一の生涯と事績に関する博物館。管理運営は公益財団法人渋沢栄一記念財団。飛鳥山公園内にある「飛鳥山3つの博物館」の一つ。","d":"東京都北区にある渋沢栄一に関する博物館","t":"渋沢史料館"},"渋谷":{"x":"渋谷駅は、東京都渋谷区にある、東日本旅客鉄道・京王電鉄・東急電鉄・東京地下鉄の駅である。 東京3大副都心の一つである渋谷に位置するターミナル駅である。JRや私鉄、地下鉄など複数の路線が集積しており、多くの郊外の通勤通学利用者が都心方面への乗り換えで当駅を利用する。","d":"東京の鉄道駅","t":"渋谷駅"},"町屋":{"x":"町屋駅は、東京都荒川区荒川七丁目および町屋一丁目にある、京成電鉄・東京地下鉄の駅である。 本項では、両駅に近接する東京都交通局都電荒川線の町屋駅前停留場についても記す。","d":"東京都荒川区にある京成電鉄・東京地下鉄の駅、東京都交通局の停留場","t":"町屋駅"},"田端":{"x":"田端駅は、東京都北区東田端一丁目にある、東日本旅客鉄道の駅である。特定都区市内制度における「東京都区内」および「東京山手線内」に属する。北区最南端および最東端の駅である。","d":"東京都北区東田端にある東日本旅客鉄道の駅","t":"田端駅"},"田町":{"x":"田町駅は、東京都港区芝五丁目にある、東日本旅客鉄道の駅である。","d":"東京都港区芝にある東日本旅客鉄道の駅","t":"田町駅"},"白金高輪":{"x":"白金高輪駅は、東京都港区高輪一丁目にある、東京地下鉄・東京都交通局の駅である。駅番号は東京メトロがN 03、都営地下鉄がI 03。","d":"東京都港区にある東京地下鉄・東京都交通局の駅","t":"白金高輪駅"},"王子駅前":{"x":"王子駅は、東京都北区王子一丁目にある、東日本旅客鉄道・東京地下鉄の駅である。 本項では、付近にある東京都交通局都電荒川線の王子駅前停留場についても記述する。","d":"東京都北区王子にある東日本旅客鉄道・東京地下鉄の駅、東京都交通局の停留場","t":"王子駅"},"田園調布":{"x":"田園調布駅は、東京都大田区田園調布三丁目にある、東急電鉄の駅である。大田区最西端の駅。","d":"東京都大田区田園調布にある東急電鉄の駅","t":"田園調布駅"},"王子神谷":{"x":"王子神谷駅は、東京都北区王子五丁目にある、東京地下鉄南北線の駅である。駅番号はN 17。","d":"東京都北区にある東京地下鉄の駅","t":"王子神谷駅"},"用賀":{"x":"用賀駅は、東京都世田谷区用賀二丁目にある、東急電鉄田園都市線の駅である。駅番号はDT 06。副駅名は「GMOインターネットTOWER前」。","d":"東京都世田谷区用賀にある東急電鉄の駅","t":"用賀駅"},"登戸":{"x":"登戸駅は、神奈川県川崎市多摩区登戸にある、東日本旅客鉄道・小田急電鉄の駅である。 JR東日本の南武線と小田急小田原線が乗り入れており、相互間の接続駅となっている。駅番号はJR東日本がJN 14、小田急がOH 18。","d":"神奈川県川崎市多摩区にある東日本旅客鉄道・小田急電鉄の駅","t":"登戸駅"},"白金台":{"x":"白金台駅は、東京都港区白金台四丁目にある、東京地下鉄・東京都交通局の駅である。駅番号は東京メトロがN 02、都営地下鉄がI 02。 東京メトロの南北線と、都営地下鉄の三田線の共用区間に位置する駅で、両路線の列車が乗り入れている。","d":"東京都港区にある東京地下鉄・東京都交通局の駅","t":"白金台駅"},"玉川上水":{"x":"玉川上水は、江戸市中への飲料水が流れていた上水道。江戸の六上水の一つ。 江戸時代前期の1653年に多摩川の羽村から四谷までの高低差92.3メートルの間に全長42.74キロメートルが築かれた。","d":"江戸市中への飲料水が流れていた上水道","t":"玉川上水"},"瑞江":{"x":"瑞江駅は、東京都江戸川区瑞江二丁目にある、東京都交通局新宿線の駅である。駅番号はS 19。","d":"東京都江戸川区瑞江にある東京都交通局の駅","t":"瑞江駅"},"生麦":{"x":"生麦駅は、神奈川県横浜市鶴見区生麦三丁目にある、京浜急行電鉄本線の駅である。駅番号はKK31。下りのみ待避可能駅で、普通が優等種別の通過待ちを行う。","d":"神奈川県横浜市鶴見区生麦にある京浜急行電鉄の駅","t":"生麦駅"},"田島ヶ原":{"x":"田島ヶ原および田島ヶ原サクラソウ自生地は、埼玉県さいたま市桜区にある、国の特別天然記念物に指定されたサクラソウの自生地である。さくら草公園が整備されている。","d":"埼玉県さいたま市桜区にあるサクラソウの自生地","t":"田島ヶ原"},"瑞聖寺":{"x":"瑞聖寺は、東京都港区白金台三丁目にある禅宗寺院。宗派は黄檗宗系の単立。山号は紫雲山。","d":"東京都港区にある寺院","t":"瑞聖寺"},"田安門":{"x":"田安門は、東京都千代田区北の丸公園内にある、旧江戸城の門。北面する高麗門と西側に矩折りに位置する櫓門からなる桝形門である。1961年に「旧江戸城田安門」として国の重要文化財に指定されている。","d":"東京都千代田区北の丸公園内の門","t":"田安門"},"練馬":{"x":"練馬駅は、東京都練馬区にある、西武鉄道・東京都交通局の駅。 西武鉄道の駅は練馬一丁目に、都営地下鉄の駅は豊玉北五丁目に、それぞれ所在する。","d":"東京都練馬区にある西武鉄道および東京都交通局の駅","t":"練馬駅"},"綾瀬":{"x":"綾瀬駅は、東京都足立区綾瀬三丁目にある、東京地下鉄・東日本旅客鉄道・日本貨物鉄道の駅である。駅番号は東京メトロがC 19、JR東日本がJL 19。足立区と葛飾区の境近くに位置し、駅の南側は葛飾区小菅四丁目である。","d":"東京都足立区綾瀬三丁目にある東京地下鉄・東日本旅客鉄道・日本貨物鉄道の駅","t":"綾瀬駅"},"練馬高野台":{"x":"練馬高野台駅は、東京都練馬区高野台一丁目にある、西武鉄道池袋線の駅である。駅番号はSI09。","d":"東京都練馬区にある西武鉄道の駅","t":"練馬高野台駅"},"羽田空港第1・第2ターミナル":{"x":"羽田空港第1・第2ターミナル駅は、東京都大田区羽田空港三丁目にある京浜急行電鉄空港線の駅である。駅番号はKK17。京急最東端の駅である。","d":"東京都大田区羽田空港にある京浜急行電鉄の駅","t":"羽田空港第1・第2ターミナル駅"},"経堂":{"x":"経堂駅は、東京都世田谷区経堂二丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 11。副駅名は「東京農業大学 最寄駅」。","d":"東京都世田谷区経堂にある小田急電鉄の駅","t":"経堂駅"},"綱島":{"x":"綱島駅は、神奈川県横浜市港北区綱島西一丁目に所在する、東急電鉄東横線の駅である。駅番号はTY14。","d":"神奈川県横浜市港北区綱島西にある東急電鉄の駅","t":"綱島駅"},"総持寺":{"x":"総持寺駅は、大阪府茨木市総持寺駅前町にある、阪急電鉄京都本線の駅。駅番号はHK-70。","d":"大阪府茨木市にある阪急電鉄の駅","t":"総持寺駅"},"築地":{"x":"築地駅は、東京都中央区築地三丁目にある、東京地下鉄日比谷線の駅である。駅番号はH 11。副駅名は本願寺前。","d":"東京都中央区にある東京地下鉄の駅","t":"築地駅"},"練馬春日町":{"x":"練馬春日町駅は、東京都練馬区春日町三丁目にある、東京都交通局大江戸線の駅である。駅番号はE 37。 同駅地上の環八交差点は地上道路から富士山が望めるスポットとして知られ、練馬区の「とっておきの風景」にもリストアップされている。","d":"東京都練馬区春日町にある東京都交通局の駅","t":"練馬春日町駅"},"篠崎":{"x":"篠崎駅は、東京都江戸川区篠崎町七丁目にある、東京都交通局新宿線の駅。駅番号はS 20。 江戸川区、東京都区部並びに東京都内で最東端に位置する駅である。","d":"東京都江戸川区篠崎町にある東京都交通局の駅","t":"篠崎駅"},"糀谷":{"x":"糀谷駅は、東京都大田区西糀谷四丁目にある、京浜急行電鉄空港線の駅である。駅番号はKK12。","d":"東京都大田区西糀谷にある京浜急行電鉄の駅","t":"糀谷駅"},"羽田空港第2ターミナル":{"x":"羽田空港第2ターミナル駅は、東京都大田区羽田空港三丁目にある、東京モノレール羽田空港線の駅で、同線の終点。駅番号はMO 11。大田区の鉄道駅では最も東に位置する。","d":"東京都大田区羽田空港にある東京モノレールの駅","t":"羽田空港第2ターミナル駅"},"羽田空港第1ターミナル":{"x":"羽田空港第1ターミナル駅は、東京都大田区羽田空港三丁目にある、東京モノレール羽田空港線の駅である。駅番号はMO 10。","d":"東京都大田区羽田空港にある東京モノレールの駅","t":"羽田空港第1ターミナル駅"},"築地本願寺":{"x":"築地本願寺は、東京都中央区築地三丁目にある浄土真宗本願寺派の寺院。東京都内における代表的な寺院の一つで、京都市にある西本願寺の直轄寺院である。本尊は聖徳太子手彫と伝承される阿弥陀如来立像。","d":"東京都中央区にある仏教寺院","t":"築地本願寺"},"聖徳記念絵画館":{"x":"聖徳記念絵画館は、東京都新宿区の明治神宮外苑にある美術館。 神宮外苑の中心的な建物で、明治天皇の生涯に昭憲皇太后の在世中の事績を交えつつ各時代を描いた歴史的・文化的にも貴重な壁画を展示している。維持管理は宗教法人明治神宮の予算で賄われており、他からの援助は一切受けていない。","d":"東京都新宿区にある美術館","t":"聖徳記念絵画館"},"羽田空港第3ターミナル":{"x":"羽田空港第3ターミナル駅は、東京都大田区羽田空港二丁目にある、京浜急行電鉄・東京モノレールの駅である。","d":"東京都大田区羽田空港にある京浜急行電鉄・東京モノレールの駅","t":"羽田空港第3ターミナル駅"},"練馬白山神社の大ケヤキ":{"x":"練馬白山神社の大ケヤキは、東京都練馬区練馬の白山神社境内にあるケヤキの大木。2本が国の天然記念物に指定されていたが、現在は1本しか残っていない。","d":"日本の天然記念物","t":"練馬白山神社の大ケヤキ"},"茅場町":{"x":"茅場町駅は、東京都中央区日本橋茅場町一丁目にある、東京地下鉄の駅。 日比谷線と東西線が乗り入れている。駅番号は日比谷線がH 13、東西線がT 11。","d":"東京都中央区にある東京地下鉄の駅","t":"茅場町駅"},"自由が丘":{"x":"自由が丘駅は、東京都目黒区自由が丘一丁目にある、東急電鉄の駅である。東横線と大井町線が乗り入れ、両線の乗換駅となっている。駅番号は東横線がTY 07、大井町線がOM 10。","d":"東京都目黒区自由が丘にある東急電鉄の駅","t":"自由が丘駅"},"舞浜":{"x":"舞浜駅は、千葉県浦安市舞浜にある、東日本旅客鉄道京葉線の駅。京葉線の列車のほか、西船橋駅から武蔵野線に乗り入れる列車も停車する。駅番号はJE 07。","d":"千葉県浦安市舞浜にある東日本旅客鉄道の駅","t":"舞浜駅"},"茗荷谷":{"x":"茗荷谷駅は、東京都文京区小日向四丁目にある、東京地下鉄丸ノ内線の駅である。駅番号はM 23。","d":"東京都文京区にある東京地下鉄の駅","t":"茗荷谷駅"},"草加":{"x":"草加駅は、埼玉県草加市高砂二丁目にある、東武鉄道伊勢崎線の駅である。「東武スカイツリーライン」の愛称区間に含まれている。駅番号はTS 16。","d":"埼玉県草加市高砂二丁目にある東武鉄道の駅","t":"草加駅"},"芦花公園":{"x":"芦花公園駅は、東京都世田谷区南烏山三丁目にある、京王電鉄京王線の駅である。京王東管区所属。駅番号はKO11。","d":"東京都世田谷区南烏山にある京王電鉄の駅","t":"芦花公園駅"},"芝公園":{"x":"芝公園駅は、東京都港区芝公園四丁目にある、東京都交通局三田線の駅である。駅番号はI 05。","d":"東京都港区にある東京都交通局の駅","t":"芝公園駅"},"若松河田":{"x":"若松河田駅は、東京都新宿区河田町にある、東京都交通局大江戸線の駅である。駅番号はE 03。","d":"東京都新宿区河田町にある東京都交通局の駅","t":"若松河田駅"},"船堀":{"x":"船堀駅は、東京都江戸川区船堀三丁目にある、東京都交通局新宿線の駅である。駅番号はS 17。","d":"東京都江戸川区船堀にある東京都交通局の駅","t":"船堀駅"},"芝浦ふ頭":{"x":"芝浦ふ頭駅は、東京都港区海岸三丁目にある、ゆりかもめ東京臨海新交通臨海線の駅である。駅番号はU 05。 駅周辺は東京湾の埋立地で、倉庫が多く、多少の中層住宅も入り混じっている。","d":"東京都港区海岸にあるゆりかもめの駅","t":"芝浦ふ頭駅"},"花月総持寺":{"x":"花月総持寺駅は、神奈川県横浜市鶴見区生麦五丁目にある、京浜急行電鉄本線の駅である。駅番号はKK30。","d":"神奈川県横浜市鶴見区生麦にある京浜急行電鉄の駅","t":"花月総持寺駅"},"舎人公園":{"x":"舎人公園駅は、東京都足立区舎人公園にある、東京都交通局日暮里・舎人ライナーの駅である。駅番号はNT 11。","d":"東京都足立区舎人公園にある東京都交通局の駅","t":"舎人公園駅"},"舎人":{"x":"舎人駅は、東京都足立区舎人一丁目にある、東京都交通局日暮里・舎人ライナーの駅である。難読駅として知られている。駅番号はNT 12。","d":"東京都足立区舎人にある東京都交通局の駅","t":"舎人駅"},"草加松原":{"x":"草加松原は、埼玉県草加市にある国指定の名勝。旧日光街道の草加六丁目橋付近から旭町一丁目南端にかけて綾瀬川沿いに約1.5kmに渡って続くクロマツの並木である。千本松原とも呼ばれる。","d":"埼玉県草加市にある松並木","t":"草加松原"},"自由学園明日館":{"x":"自由学園明日館は、東京都豊島区西池袋に所在する、学校法人自由学園が所有する施設。1921年、東京府北豊島郡高田町雑司ヶ谷村に羽仁吉一・羽仁もと子夫妻により設立された。当初は本科と専攻科からなる女学校として開校。","d":"東京都豊島区西池袋に所在する、学校法人自由学園が所有する施設","t":"自由学園明日館"},"船氏王後墓誌":{"x":"船 王後は、飛鳥時代の官人。姓は首、冠位は大仁。 船氏王後墓誌で知られる人物である。","d":"飛鳥時代の官人","t":"船王後"},"葛西":{"x":"葛西駅は、東京都江戸川区中葛西五丁目にある、東京地下鉄東西線の駅である。駅番号はT 17。 副駅名は地下鉄博物館前。","d":"東京都江戸川区にある東京地下鉄の駅","t":"葛西駅"},"荻窪":{"x":"荻窪駅は、東京都杉並区にある、東日本旅客鉄道・東京地下鉄の駅である。 JR東日本の駅は上荻一丁目に、東京メトロの駅は荻窪五丁目にそれぞれ所在する。","d":"東京都杉並区にある東日本旅客鉄道・東京メトロの駅","t":"荻窪駅"},"菊名":{"x":"菊名駅は、神奈川県横浜市港北区菊名七丁目にある、東日本旅客鉄道・東急電鉄の駅である。","d":"神奈川県横浜市港北区にある東急電鉄・東日本旅客鉄道の駅","t":"菊名駅"},"荏原中延":{"x":"荏原中延駅は、東京都品川区中延二丁目にある、東急電鉄池上線の駅である。駅番号はIK04。","d":"東京都品川区中延にある東急電鉄の駅","t":"荏原中延駅"},"荒川一中前":{"x":"荒川一中前停留場は、東京都荒川区南千住一丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 02。 荒川線の停留場では最も新しい。","d":"東京都荒川区南千住にある都電荒川線の停留場","t":"荒川一中前停留場"},"蒲田":{"x":"蒲田駅は、東京都大田区にある、東日本旅客鉄道・東急電鉄の駅である。 JR東日本の駅は蒲田五丁目、東急電鉄の駅は西蒲田七丁目に位置する。京浜急行電鉄の京急蒲田駅は、当駅よりおよそ800メートル離れて位置し、連絡駅とはなっていない。","d":"東京都大田区にある東日本旅客鉄道・東急電鉄の駅","t":"蒲田駅"},"葛西臨海公園":{"x":"葛西臨海公園駅は、東京都江戸川区臨海町六丁目にある、東日本旅客鉄道京葉線の駅である。駅番号はJE 06。江戸川区最南端の駅である。","d":"東京都江戸川区臨海町六丁目にある東日本旅客鉄道の駅","t":"葛西臨海公園駅"},"菅野":{"x":"菅野駅は、千葉県市川市菅野二丁目にある、京成電鉄本線の駅である。駅番号はKS15。","d":"千葉県市川市菅野にある京成電鉄の駅","t":"菅野駅"},"蓮根":{"x":"蓮根駅は、東京都板橋区蓮根二丁目にある、東京都交通局三田線の駅である。駅番号はI 23。","d":"東京都板橋区蓮根にある東京都交通局の駅","t":"蓮根駅"},"落合南長崎":{"x":"落合南長崎駅は、東京都新宿区西落合三丁目にある、東京都交通局大江戸線の駅である。駅番号はE 33。新宿区最西端かつ最北端の駅。","d":"東京都新宿区西落合にある東京都交通局の駅","t":"落合南長崎駅"},"荏原町":{"x":"荏原町駅は、東京都品川区中延五丁目にある、東急電鉄大井町線の駅である。駅番号はOM05。","d":"東京都品川区中延にある東急電鉄の駅","t":"荏原町駅"},"荒川区役所前":{"x":"荒川区役所前停留場は、東京都荒川区荒川一丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 03。","d":"東京都荒川区荒川にある都電荒川線の停留場","t":"荒川区役所前停留場"},"荒川二丁目":{"x":"荒川二丁目停留場は、東京都荒川区荒川二丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 04。 「ゆいの森あらかわ前」の副名称を持つ。","d":"東京都荒川区荒川にある都電荒川線の停留場","t":"荒川二丁目停留場"},"荒川七丁目":{"x":"荒川七丁目停留場は、東京都荒川区荒川七丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 05。 乗降客数は2019年度で473人と荒川線、そして東京都区部の駅・停留所では最も少ない。","d":"東京都荒川区荒川にある都電荒川線の停留場","t":"荒川七丁目停留場"},"荒川車庫前":{"x":"荒川車庫前停留場は、東京都荒川区西尾久にある東京都交通局都電荒川線の停留場である。駅番号はSA 13。 東京都電車の荒川車庫付近に位置する。","d":"東京都荒川区西尾久にある都電荒川線の停留場","t":"荒川車庫前停留場"},"荒川遊園地前":{"x":"荒川遊園地前停留場は、東京都荒川区西尾久にある東京都交通局都電荒川線の停留場である。駅番号はSA 12。 当停留場の名称は、付近にある遊園地「あらかわ遊園」に因む。","d":"東京都荒川区西尾久にある都電荒川線の停留場","t":"荒川遊園地前停留場"},"荻生徂徠墓":{"x":"荻生徂徠墓は、東京都港区三田四丁目の長松寺にある荻生徂徠の墓で、国の史跡。荻生徂徠は、江戸時代中期の儒学者・思想家・文献学者で、徳川吉宗に重用され、古文辞学を提唱して護園学派の祖となった人物である。 荻生徂徠は、享保13年正月19日、63歳で死去し、三田の長松寺に葬られた。","d":"東京都港区にある荻生徂徠の墓","t":"荻生徂徠墓"},"荻外荘公園":{"x":"荻外荘公園は、東京都杉並区荻窪に所在する区立公園。近衛文麿の邸宅であった荻外荘の敷地を公園として整備した施設である。","d":"東京都杉並区にある公園","t":"荻外荘公園"},"西大井":{"x":"西大井駅は、東京都品川区西大井一丁目にある、東日本旅客鉄道の駅である。","d":"東京都品川区にある東日本旅客鉄道の駅","t":"西大井駅"},"西巣鴨":{"x":"西巣鴨駅は、東京都豊島区西巣鴨三丁目にある、東京都交通局三田線の駅である。駅番号はI 16。","d":"東京都豊島区にある東京都交通局の駅","t":"西巣鴨駅"},"西川口":{"x":"西川口駅は、埼玉県川口市並木二丁目にある、東日本旅客鉄道の駅である。駅番号はJK 40。","d":"埼玉県川口市並木にある東日本旅客鉄道の駅","t":"西川口駅"},"蕨":{"x":"蕨駅は、埼玉県蕨市中央一丁目にある、東日本旅客鉄道の駅である。駅番号はJK 41。","d":"埼玉県蕨市中央にある東日本旅客鉄道の駅","t":"蕨駅"},"虎ノ門":{"x":"虎ノ門駅は、東京都港区虎ノ門一丁目にある、東京地下鉄銀座線の駅である。駅番号はG 07。 区境付近に位置しており、出入口の一部は千代田区霞が関三丁目に跨る。","d":"東京都港区にある東京地下鉄の駅","t":"虎ノ門駅"},"蔵前":{"x":"蔵前駅は、東京都台東区にある、東京都交通局の駅である。 所在地は浅草線が蔵前二丁目、大江戸線が寿三丁目となっている。","d":"東京都台東区にある東京都交通局の駅","t":"蔵前駅"},"表参道":{"x":"表参道駅は、東京都港区北青山三丁目にある、東京地下鉄の駅である。 港区最西端の駅。駅名の由来となっている明治神宮の表参道と青山通りの交差点の地下に位置する。","d":"東京都港区にある東京地下鉄の駅","t":"表参道駅"},"行徳":{"x":"行徳駅は、千葉県市川市行徳駅前二丁目にある、東京地下鉄東西線の駅である。駅番号はT 20。","d":"千葉県市川市にある東京地下鉄の駅","t":"行徳駅"},"西ケ原":{"x":"西ケ原駅は、東京都北区西ケ原二丁目にある、東京地下鉄南北線の駅である。駅番号はN 15。","d":"東京都北区にある東京地下鉄の駅","t":"西ケ原駅"},"西台":{"x":"西台駅は、東京都板橋区高島平九丁目にある、東京都交通局三田線の駅である。駅番号はI 24。","d":"東京都板橋区高島平にある東京都交通局の駅","t":"西台駅"},"西大島":{"x":"西大島駅は、東京都江東区大島二丁目にある、東京都交通局新宿線の駅である。駅番号はS 14。","d":"東京都江東区大島にある東京都交通局の駅","t":"西大島駅"},"西小山":{"x":"西小山駅は、東京都品川区小山六丁目にある、東急電鉄目黒線の駅である。品川区最西端の駅である。駅番号はMG04。","d":"東京都品川区小山にある東急電鉄の駅","t":"西小山駅"},"蓮沼":{"x":"蓮沼駅は、東京都大田区西蒲田七丁目にある、東急池上線の駅である。駅番号はIK14。","d":"東京都大田区西蒲田にある東急電鉄の駅","t":"蓮沼駅"},"西太子堂":{"x":"西太子堂駅は、東京都世田谷区太子堂四丁目にある、東急電鉄世田谷線の停留場である。駅番号はSG02。","d":"東京都世田谷区太子堂にある東急電鉄の駅","t":"西太子堂駅"},"西ヶ原四丁目":{"x":"西ヶ原四丁目停留場は、東京都北区西ケ原四丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 19。 地名は「西ケ原四丁目」だが、東京都交通局は「西ヶ原四丁目」という表記を用いている。","d":"東京都北区西ケ原にある東京都交通局の停留場","t":"西ヶ原四丁目停留場"},"虎橋通":{"x":"虎橋通駅は、かつて東京都向島区に存在した東武鉄道亀戸線の駅。","d":"東武鉄道の廃駅","t":"虎橋通駅"},"虎ノ門ヒルズ":{"x":"虎ノ門ヒルズ駅は、東京都港区虎ノ門一丁目にある、東京地下鉄日比谷線の駅である。駅番号はH 06。 森ビルが建設費用の大半を負担する請願駅として建設された。","d":"東京都港区にある東京地下鉄の駅","t":"虎ノ門ヒルズ駅"},"西日暮里":{"x":"西日暮里駅は、東京都荒川区西日暮里五丁目にある、東京地下鉄・東日本旅客鉄道・東京都交通局の駅である。","d":"東京都荒川区西日暮里にある東京地下鉄・東日本旅客鉄道・東京都交通局の駅","t":"西日暮里駅"},"西新井":{"x":"西新井駅は、東京都足立区西新井栄町二丁目にある、東武鉄道の駅である。駅番号はTS 13。 伊勢崎線と大師線が乗り入れている。","d":"東京都足立区西新井栄町二丁目にある東武鉄道の駅","t":"西新井駅"},"調布":{"x":"調布駅は、東京都調布市布田四丁目にある、京王電鉄の駅。京王中央管区所属で管区長所在駅。駅番号はKO18。","d":"日本の鉄道駅","t":"調布駅"},"西馬込":{"x":"西馬込駅は、東京都大田区西馬込二丁目にある、東京都交通局浅草線の駅である。駅番号はA 01。 都営地下鉄の駅では最南端で、東京の地下鉄全体でも最南端に位置する駅である。","d":"東京都大田区西馬込にある東京都交通局の駅","t":"西馬込駅"},"護国寺":{"x":"護国寺は、東京都文京区大塚五丁目にある真言宗豊山派の寺。神齢山悉地院大聖護国寺と称する。","d":"東京都文京区にある寺院","t":"護国寺"},"西浦和":{"x":"西浦和駅は、埼玉県さいたま市桜区田島五丁目にある、東日本旅客鉄道武蔵野線の駅である。駅番号はJM 27。 さいたま市桜区に所在する唯一の鉄道駅である。","d":"埼玉県さいたま市桜区にある東日本旅客鉄道の駅","t":"西浦和駅"},"西葛西":{"x":"西葛西駅は、東京都江戸川区西葛西六丁目にある、東京地下鉄東西線の駅である。駅番号はT 16。","d":"東京都江戸川区にある東京地下鉄の駅","t":"西葛西駅"},"西永福":{"x":"西永福駅は、東京都杉並区永福三丁目にある、京王電鉄井の頭線の駅である。井の頭北管区所属。駅番号はIN10。","d":"東京都杉並区永福にある京王電鉄の駅","t":"西永福駅"},"要町":{"x":"要町駅は、東京都豊島区要町一丁目にある、東京地下鉄の駅である。 有楽町線・副都心線が乗り入れる。当駅を含む小竹向原駅 - 池袋駅間は、有楽町線が上層を、副都心線が下層を走る形で並走する。","d":"東京都豊島区要町一丁目にある東京地下鉄の駅","t":"要町駅"},"西新宿":{"x":"西新宿駅は、東京都新宿区西新宿六丁目にある、東京地下鉄丸ノ内線の駅である。駅番号はM 07。副駅名は東京医大病院前。","d":"東京都新宿区にある東京地下鉄の駅","t":"西新宿駅"},"西高島平":{"x":"西高島平駅は、東京都板橋区高島平六丁目にある、東京都交通局三田線の駅である。駅番号はI 27。三田線の終着駅。","d":"東京都板橋区高島平にある東京都交通局の駅","t":"西高島平駅"},"西新宿五丁目":{"x":"西新宿五丁目駅は、東京都新宿区西新宿五丁目にある、東京都交通局大江戸線の駅。駅番号はE 29。「清水橋」の副名称が設定されている。","d":"東京都新宿区にある東京都交通局の駅","t":"西新宿五丁目駅"},"西荻窪":{"x":"西荻窪駅は、東京都杉並区西荻南三丁目にある、東日本旅客鉄道中央本線の駅である。 運転系統としては、急行線を走る中央線快速電車および緩行線を走る中央・総武線各駅停車の2系統が停車する。ただし、中央線快速電車は平日ダイヤ時のみ停車する。","d":"東京都杉並区西萩南にある東日本旅客鉄道の駅","t":"西荻窪駅"},"西早稲田":{"x":"西早稲田駅は、東京都新宿区戸山三丁目にある、東京地下鉄副都心線の駅である。駅番号はF 11。","d":"東京都新宿区にある東京地下鉄の駅","t":"西早稲田駅"},"西新井大師西":{"x":"西新井大師西駅は、東京都足立区江北六丁目にある、東京都交通局日暮里・舎人ライナーの駅である。駅番号はNT 09。北隣の谷在家駅と共に足立区の駅としては最も西にある。","d":"東京都足立区江北にある東京都交通局の駅","t":"西新井大師西駅"},"見沼代親水公園":{"x":"見沼代親水公園駅は、東京都足立区舎人二丁目にある東京都交通局日暮里・舎人ライナーの駅。同線の終着駅である。駅番号はNT 13。","d":"東京都足立区舎人にある東京都交通局の駅","t":"見沼代親水公園駅"},"赤羽":{"x":"赤羽駅は、東京都北区赤羽一丁目にある、東日本旅客鉄道の駅である。","d":"東京都北区赤羽にある東日本旅客鉄道の駅","t":"赤羽駅"},"豊島園":{"x":"豊島園駅は、東京都練馬区練馬四丁目にある、西武鉄道・東京都交通局の駅である。 開業時から2020年8月31日まで23区内有数の遊園地であるとしまえんの最寄駅であった。","d":"東京都練馬区にある西武豊島線の駅","t":"豊島園駅"},"赤羽岩淵":{"x":"赤羽岩淵駅は、東京都北区赤羽一丁目にある、東京地下鉄・埼玉高速鉄道の駅である。駅番号は東京メトロがN 19、埼玉高速鉄道がSR 19。","d":"東京都北区にある東京地下鉄・埼玉高速鉄道の駅","t":"赤羽岩淵駅"},"都庁前":{"x":"都庁前駅は、東京都新宿区西新宿二丁目にある、東京都交通局大江戸線の駅である。同線の起点駅。駅番号はE 28。","d":"東京都新宿区西新宿にある東京都交通局の駅","t":"都庁前駅"},"豊洲":{"x":"豊洲駅は、東京都江東区豊洲にある、東京地下鉄・ゆりかもめの駅である。","d":"東京都江東区にある東京地下鉄・ゆりかもめの駅","t":"豊洲駅"},"都立大学":{"x":"都立大学駅は、東京都目黒区中根一丁目にある、東急電鉄東横線の駅である。駅番号はTY06。 駅名はかつて近隣に存在した東京都立大学に由来するが、隣駅の学芸大学駅と同様、現在の同名の大学の最寄り駅にはなっていない。","d":"東京都目黒区中根にある東急電鉄の駅","t":"都立大学駅"},"赤坂見附":{"x":"赤坂見附駅は、東京都港区赤坂三丁目にある、東京地下鉄の駅である。港区最北端の駅であり、千代田区との区界付近に位置している。 駅名の赤坂見附とはかつて存在した同名の江戸城の城門に由来している。","d":"東京都港区にある東京地下鉄の駅","t":"赤坂見附駅"},"豪徳寺":{"x":"豪徳寺は、東京都世田谷区豪徳寺二丁目にある曹洞宗の寺院。元は臨済宗。山号は大谿山。","d":"東京都世田谷区の寺院","t":"豪徳寺"},"赤羽橋":{"x":"赤羽橋駅は、東京都港区東麻布一丁目にある、東京都交通局大江戸線の駅である。駅番号はE 21。","d":"東京都港区にある東京都交通局の駅","t":"赤羽橋駅"},"辰巳":{"x":"辰巳駅は、東京都江東区辰巳一丁目にある、東京地下鉄有楽町線の駅である。駅番号はY 23。","d":"東京都江東区にある東京地下鉄の駅","t":"辰巳駅"},"谷塚":{"x":"谷塚駅は、埼玉県草加市谷塚一丁目にある東武鉄道伊勢崎線の駅である。「東武スカイツリーライン」の愛称区間に含まれている。駅番号はTS 15。","d":"埼玉県草加市谷塚一丁目にある東武鉄道の駅","t":"谷塚駅"},"越中島":{"x":"越中島駅は、東京都江東区越中島二丁目にある、東日本旅客鉄道京葉線の駅である。駅番号はJE 03。 京葉線の列車のほか、西船橋駅から武蔵野線に乗り入れる列車も停車する。","d":"東京都江東区越中島二丁目にある東日本旅客鉄道の駅","t":"越中島駅"},"都立家政":{"x":"都立家政駅は、東京都中野区鷺宮一丁目にある西武鉄道新宿線の駅である。駅番号はSS08。","d":"東京都中野区にある西武鉄道の駅","t":"都立家政駅"},"赤門":{"x":"御守殿は、江戸時代において、徳川将軍家の娘が三位以上の大名へ正室として嫁ぎ居住した奥御殿を指す。 また、その正室の敬称であり、加えて仕えた女中とその髪結い、服装などの風俗をも指す。","d":"東京大学本郷キャンパスの校門の一つ","t":"御守殿"},"赤土小学校前":{"x":"赤土小学校前駅は、東京都荒川区東尾久四丁目にある、東京都交通局日暮里・舎人ライナーの駅。駅番号はNT 03。","d":"東京都荒川区東尾久にある東京都交通局の駅","t":"赤土小学校前駅"},"足立小台":{"x":"足立小台駅は、東京都足立区小台一丁目にある、東京都交通局日暮里・舎人ライナーの駅である。駅番号はNT 05。","d":"東京都足立区小台にある東京都交通局の駅","t":"足立小台駅"},"谷在家":{"x":"谷在家駅は、東京都足立区谷在家三丁目にある東京都交通局日暮里・舎人ライナーの駅である。駅番号はNT 10。南隣の西新井大師西駅と共に足立区の駅としては最も西にある。","d":"東京都足立区谷在家にある東京都交通局の駅","t":"谷在家駅"},"迎賓館赤坂離宮":{"x":"迎賓館赤坂離宮は、東京都港区元赤坂にある日本の迎賓館。赤坂迎賓館とも呼ばれる。国賓を迎える施設で、行政官庁としては、内閣府の施設等機関として置かれている。","d":"東京都港区にある日本の迎賓館","t":"迎賓館赤坂離宮"},"錦糸町":{"x":"錦糸町駅は、東京都墨田区江東橋三丁目にある、東日本旅客鉄道・東京地下鉄の駅である。","d":"東京都墨田区江東橋にある東日本旅客鉄道・東京地下鉄の駅","t":"錦糸町駅"},"野方":{"x":"野方駅は、東京都中野区野方六丁目にある西武鉄道新宿線の駅。駅番号はSS07。","d":"東京都中野区にある西武鉄道の駅","t":"野方駅"},"銀座一丁目":{"x":"銀座一丁目駅は、東京都中央区銀座一丁目にある、東京地下鉄有楽町線の駅である。駅番号はY 19。","d":"東京都中央区にある東京地下鉄の駅","t":"銀座一丁目駅"},"銀座":{"x":"銀座駅は、東京都中央区銀座四丁目にある、東京地下鉄の駅である。中央区最西端の駅である。","d":"東京都中央区にある東京地下鉄の駅","t":"銀座駅"},"金町":{"x":"金町駅は、東京都葛飾区金町六丁目にある、東日本旅客鉄道・日本貨物鉄道の駅である。葛飾区最北端の駅。","d":"東京都葛飾区にある東日本旅客鉄道・日本貨物鉄道の駅","t":"金町駅"},"門前仲町":{"x":"門前仲町駅は、東京都江東区門前仲町にある、東京地下鉄・東京都交通局の駅。 東京メトロの駅は門前仲町一丁目に、都営地下鉄の駅は門前仲町二丁目にある。 東京メトロの東西線と都営地下鉄の大江戸線が乗り入れ、接続駅となっている。","d":"東京都江東区にある東京地下鉄・東京都交通局の駅","t":"門前仲町駅"},"阿佐ケ谷":{"x":"阿佐ケ谷駅は、東京都杉並区阿佐谷南三丁目にある、東日本旅客鉄道中央本線の駅である。 運転系統としては、急行線を走る中央線快速電車、及び緩行線を走る中央・総武線各駅停車の2系統が停車する。ただし中央線快速電車は平日ダイヤ時のみ停車する。","d":"東京都杉並区阿佐谷南にある東日本旅客鉄道の駅","t":"阿佐ケ谷駅"},"鐘ヶ淵":{"x":"鐘ヶ淵駅は、東京都墨田区墨田五丁目にある東武鉄道伊勢崎線の駅である。墨田区最北端の駅。「東武スカイツリーライン」の愛称区間に含まれている。","d":"東京都墨田区墨田五丁目にある東武鉄道の駅","t":"鐘ヶ淵駅"},"鈴木町":{"x":"鈴木町駅は、神奈川県川崎市川崎区鈴木町にある、京浜急行電鉄大師線の駅である。駅番号はKK22。","d":"神奈川県川崎市川崎区鈴木町にある京浜急行電鉄の駅","t":"鈴木町駅"},"都筑ふれあいの丘":{"x":"都筑ふれあいの丘駅は、神奈川県横浜市都筑区葛が谷にある、横浜市営地下鉄グリーンラインの駅である。駅番号はG03。 ステーションカラーは街としての成熟度が高いことから優雅さ・高級感をイメージしてむらさき 。","d":"神奈川県横浜市都筑区葛が谷にある横浜市交通局の駅","t":"都筑ふれあいの丘駅"},"隅田川":{"x":"隅田川駅は、東京都荒川区南千住四丁目にある、日本貨物鉄道・東日本旅客鉄道の駅である。常磐線貨物支線上に設置されている。主に東北本線、上越線などのいわゆる北、東方面発着の貨物列車の終着駅であり、東京貨物ターミナル駅と並ぶ東京の二大貨物駅である。","d":"日本の東京都荒川区にある日本貨物鉄道・東日本旅客鉄道の駅","t":"隅田川駅"},"隅田八幡神社人物画像鏡":{"x":"隅田八幡神社人物画像鏡は、和歌山県橋本市の隅田八幡神社が所蔵する、5世紀から6世紀頃製作の銅鏡。鏡背の48字の金石文は、日本古代史、考古学、日本語学における貴重な資料である。国宝に指定されている。","d":"台東区にある国宝（美術品）","t":"隅田八幡神社人物画像鏡"},"金銅灌頂幡":{"x":"国宝指定名称・金銅灌頂幡は東京国立博物館所蔵の幡である。一般的な幡は布製であるところ、本品は銅製透彫鍍金という他に類を見ない絢爛な技法・材質でつくられており、日本古代の金工品を代表する品とされている。","d":"東京国立博物館所蔵の幡、国宝","t":"金銅灌頂幡"},"金銅匙":{"x":"墨台、水滴、匙は東京国立博物館所蔵の金工品である。奈良時代の文房具のあり方を知るうえで貴重な品であり、国宝に指定されている。","d":"東京国立博物館所蔵の金工品、国宝","t":"墨台、水滴、匙"},"青砥":{"x":"青砥駅は、東京都葛飾区青戸三丁目にある、京成電鉄の駅である。本線と押上線が乗り入れている。駅番号はKS09。","d":"東京都葛飾区青戸にある京成電鉄の駅","t":"青砥駅"},"馬橋":{"x":"馬橋駅は、千葉県松戸市馬橋にある、東日本旅客鉄道・流鉄の駅である。 東日本旅客鉄道の常磐線を走行する常磐緩行線、武蔵野線、流鉄の流鉄流山線の2社3路線が乗り入れ、接続駅となっている。なお武蔵野線にはホームが無いため、旅客の乗降は不可能である。","d":"千葉県松戸市にある東日本旅客鉄道・日本貨物鉄道・流鉄の駅","t":"馬橋駅"},"飯田橋":{"x":"飯田橋駅は、東京都千代田区・新宿区・文京区にある、東日本旅客鉄道・東京地下鉄・東京都交通局の駅である。","d":"東京都千代田区・新宿区・文京区にある東日本旅客鉄道・東京地下鉄・東京都交通局の駅","t":"飯田橋駅"},"馬喰横山":{"x":"馬喰横山駅は、東京都中央区日本橋横山町にある、東京都交通局新宿線の駅である。 駅番号はS 09。馬喰駅務管区の所在駅である。","d":"東京都中央区にある東京都交通局の駅","t":"馬喰横山駅"},"馬喰町":{"x":"馬喰町駅は、東京都中央区日本橋馬喰町一丁目にある、東日本旅客鉄道総武本線の駅である。駅番号はJO 21。中央区最北端の駅である。","d":"東京都中央区日本橋馬喰町にある東日本旅客鉄道の駅","t":"馬喰町駅"},"飛鳥山公園":{"x":"飛鳥山公園は、東京都北区にある区立公園。東京都内の桜の名所の一つ。江戸時代享保年間に行楽地として整備され、明治6年3月には日本最初の公園の一つに指定された。","d":"東京都北区の公園","t":"飛鳥山公園"},"靖国神社":{"x":"靖国神社は、東京都千代田区九段北にある神社。招魂社に起源を発し、1853年以降の国事に殉難した人の霊246万6千余柱を祀る。靖国神社では、祭神を「みたま」と称するときは、「神霊」の字を用いている。","d":"東京都千代田区の神社","t":"靖国神社"},"青山一丁目":{"x":"青山一丁目駅は、東京都港区にある、東京地下鉄・東京都交通局の駅。 東京メトロの銀座線と半蔵門線、都営地下鉄の大江戸線が乗り入れており、接続駅となっている。各路線とも駅番号が付与されており、銀座線がG 04、半蔵門線がZ 03、大江戸線がE 24。","d":"東京都港区にある東京地下鉄・東京都交通局の駅","t":"青山一丁目駅"},"青物横丁":{"x":"青物横丁駅は、東京都品川区南品川三丁目にある、京浜急行電鉄本線の駅である。駅番号はKK04。 隣接の鮫洲駅との駅間距離は500mと短い。","d":"東京都品川区南品川にある京浜急行電鉄の駅","t":"青物横丁駅"},"青井":{"x":"青井駅は、東京都足立区青井三丁目にある、首都圏新都市鉄道つくばエクスプレスの駅。駅番号はTX06。","d":"東京都足立区青井にある首都圏新都市鉄道の駅","t":"青井駅"},"馬込":{"x":"馬込駅は、東京都大田区北馬込二丁目にある、東京都交通局浅草線の駅である。駅番号はA 02。","d":"東京都大田区北馬込にある東京都交通局の駅","t":"馬込駅"},"雪が谷大塚":{"x":"雪が谷大塚駅は、東京都大田区南雪谷二丁目にある、東急電鉄池上線の駅である。駅番号はIK09。 早朝・夜間を中心に当駅止まり・始発列車が設定されており、朝ラッシュ時には五反田発列車のうち3本に1本が当駅で折返す。","d":"東京都大田区南雪谷にある東急電鉄の駅","t":"雪が谷大塚駅"},"面影橋":{"x":"面影橋停留場は、東京都新宿区西早稲田三丁目にある、東京都交通局都電荒川線の停留場である。駅番号はSA 29。","d":"東京都新宿区西早稲田にある都電荒川線の停留場","t":"面影橋停留場"},"雑色":{"x":"雑色駅は、東京都大田区仲六郷二丁目にある、京浜急行電鉄本線の駅である。駅番号はKK18。","d":"東京都大田区仲六郷にある京浜急行電鉄の駅","t":"雑色駅"},"雑司ヶ谷":{"x":"雑司が谷駅は、東京都豊島区雑司が谷二丁目にある、東京地下鉄副都心線の駅である。駅番号はF 10。","d":"東京都豊島区にある東京メトロ副都心線の駅","t":"雑司が谷駅"},"高田馬場":{"x":"高田馬場駅は、東京都新宿区高田馬場一丁目にある、東日本旅客鉄道・西武鉄道・東京地下鉄の駅である。","d":"日本の鉄道駅","t":"高田馬場駅"},"駒込":{"x":"駒込駅は、東京都豊島区駒込二丁目にある、東日本旅客鉄道・東京地下鉄の駅である。豊島区最東端の駅である。","d":"東京都豊島区にある東日本旅客鉄道・東京地下鉄の駅","t":"駒込駅"},"駒場東大前":{"x":"駒場東大前駅は、東京都目黒区駒場三丁目にある、京王電鉄井の頭線の駅である。井の頭南管区所属。駅番号はIN03。","d":"東京都目黒区駒場にある京王電鉄の駅","t":"駒場東大前駅"},"鰭ヶ崎":{"x":"鰭ヶ崎駅は、千葉県流山市大字鰭ケ崎字宮ノ後にある、流鉄流山線の駅である。駅番号はRN4。","d":"千葉県流山市大字鰭ケ崎字宮ノ後にある流鉄流山線の駅","t":"鰭ヶ崎駅"},"高井戸":{"x":"高井戸駅は、東京都杉並区高井戸西二丁目にある、京王電鉄井の頭線の駅。井の頭北管区所属。駅番号はIN12。","d":"東京都杉並区高井戸西にある京王電鉄の駅","t":"高井戸駅"},"鳩ヶ谷":{"x":"鳩ヶ谷駅は、埼玉県川口市大字里にある、埼玉高速鉄道埼玉高速鉄道線の駅である。駅番号はSR 22。","d":"埼玉県川口市にある埼玉高速鉄道の駅","t":"鳩ヶ谷駅"},"鴨居":{"x":"鴨居駅は、神奈川県横浜市緑区鴨居一丁目にある、東日本旅客鉄道横浜線の駅。駅番号はJH 18。 横浜市の要請により、地主50人が敷地を寄付して開業した。","d":"神奈川県横浜市緑区にある東日本旅客鉄道の駅","t":"鴨居駅"},"駒沢大学":{"x":"駒沢大学駅は、東京都世田谷区上馬四丁目にある、東急電鉄田園都市線の駅である。駅番号はDT04。","d":"東京都世田谷区上馬にある東急電鉄の駅","t":"駒沢大学駅"},"鮫洲":{"x":"鮫洲駅は、東京都品川区東大井一丁目にある京浜急行電鉄本線の駅である。駅番号はKK05。 隣の青物横丁駅との駅間距離は0.5 kmと近接している。","d":"東京都品川区東大井にある京浜急行電鉄の駅","t":"鮫洲駅"},"高円寺":{"x":"高円寺駅は、東京都杉並区高円寺南四丁目にある、東日本旅客鉄道中央本線の駅である。 運転系統としては、急行線を走る中央線快速電車、及び緩行線を走る中央・総武線各駅停車の2系統が停車する。但し中央線快速電車は平日ダイヤ時のみ停車する。","d":"東京都杉並区高円寺南にある東日本旅客鉄道の駅","t":"高円寺駅"},"鬼越":{"x":"鬼越駅は、千葉県市川市鬼越一丁目にある、京成電鉄本線の駅である。駅番号はKS17。","d":"千葉県市川市鬼越にある京成電鉄の駅","t":"鬼越駅"},"高輪台":{"x":"高輪台駅は、東京都港区白金台二丁目にある、東京都交通局浅草線の駅である。駅番号はA 06。","d":"東京都港区にある東京都交通局の駅","t":"高輪台駅"},"高島平":{"x":"高島平駅は、東京都板橋区高島平八丁目にある、東京都交通局三田線の駅である。駅番号はI 25。","d":"東京都板橋区高島平にある東京都交通局の駅","t":"高島平駅"},"鬼子母神前":{"x":"鬼子母神前停留場は、東京都豊島区雑司が谷二丁目にある東京都交通局都電荒川線の停留場である。駅番号はSA 27。","d":"東京都豊島区雑司が谷にある都電荒川線の停留場","t":"鬼子母神前停留場"},"高輪大木戸跡":{"x":"高輪大木戸跡は、高輪大木戸の史跡である。1928年、国の史跡に指定。東京都港区高輪二丁目19番先に所在し、国道15号の泉岳寺交差点の北東側に位置する。","d":"東京都港区高輪にあった門","t":"高輪大木戸跡"},"高輪ゲートウェイ":{"x":"高輪ゲートウェイ駅は、東京都港区港南二丁目にある、東日本旅客鉄道の駅。","d":"東京都港区港南にある東日本旅客鉄道の駅","t":"高輪ゲートウェイ駅"},"鶯谷":{"x":"鶯谷駅は、東京都台東区根岸一丁目にある、東日本旅客鉄道の駅である。","d":"東京都台東区根岸にある東日本旅客鉄道の駅","t":"鶯谷駅"},"鷺沼":{"x":"鷺沼駅は、神奈川県川崎市宮前区鷺沼三丁目にある、東急電鉄田園都市線の駅である。駅番号はDT14。 駅長所在駅。","d":"神奈川県川崎市宮前区鷺沼にある東急電鉄の駅","t":"鷺沼駅"},"鶴見":{"x":"鶴見駅は、神奈川県横浜市鶴見区鶴見中央一丁目にある、東日本旅客鉄道の駅である。東海道本線を当駅の所属線とし、また鶴見線と武蔵野線は当駅が起点となっている。東海道本線に関しては本線の他に4つの支線が分岐している。","d":"神奈川県横浜市鶴見区鶴見中央一丁目にある東日本旅客鉄道の駅","t":"鶴見駅"},"麹町":{"x":"麴町駅は、東京都千代田区麹町三丁目にある、東京地下鉄有楽町線の駅である。駅番号はY 15。","d":"東京都千代田区にある東京地下鉄の駅","t":"麹町駅"},"鹿島田":{"x":"鹿島田駅は、神奈川県川崎市幸区鹿島田一丁目にある、東日本旅客鉄道南武線の駅である。駅番号はJN 04。","d":"神奈川県川崎市幸区にある東日本旅客鉄道の駅","t":"鹿島田駅"},"麻布十番":{"x":"麻布十番駅は、東京都港区麻布十番にある、東京地下鉄・東京都交通局の駅。 東京メトロの南北線と、都営地下鉄の大江戸線が乗り入れ、接続駅となっている。駅番号は南北線がN 04、大江戸線がE 22。","d":"東京都港区にある東京地下鉄・東京都交通局の駅","t":"麻布十番駅"},"鶴見市場":{"x":"鶴見市場駅は、神奈川県横浜市鶴見区市場大和町にある、京浜急行電鉄本線の駅である。駅番号はKK28。","d":"神奈川県横浜市鶴見区市場大和町にある京浜急行電鉄の駅","t":"鶴見市場駅"},"鷺ノ宮":{"x":"鷺ノ宮駅は、東京都中野区鷺宮三丁目にある、西武鉄道新宿線の駅である。駅番号はSS09。中野区最西端に位置する駅。","d":"東京都中野区にある西武鉄道の駅","t":"鷺ノ宮駅"},"鶴見小野":{"x":"鶴見小野駅は、神奈川県横浜市鶴見区小野町にある、東日本旅客鉄道鶴見線の駅である。駅番号はJI 03。","d":"神奈川県横浜市鶴見区にある東日本旅客鉄道の駅","t":"鶴見小野駅"},"鶴瀬":{"x":"鶴瀬駅は、埼玉県富士見市鶴瀬東一丁目にある、東武鉄道東上本線の駅である。駅番号はTJ 17。","d":"埼玉県富士見市鶴瀬東にある東武鉄道の駅","t":"鶴瀬駅"},"鵜の木":{"x":"鵜の木駅は、東京都大田区鵜の木二丁目にある、東急電鉄東急多摩川線の駅である。駅番号はTM03。","d":"東京都大田区鵜の木にある東急電鉄の駅","t":"鵜の木駅"},"鵲尾形柄香炉":{"x":"鵲尾形柄香炉（じゃくびがたえごうろ、英語: Incense Burner with Magpie's Tail-shaped Handle）とは、柄の先端がカササギの尾を模した三叉の形状になっている柄香炉である。","d":"柄香炉の一種","t":"鵲尾形柄香炉"},"早稲田":{"x":"早稲田駅は、東京都新宿区早稲田南町にある、東京地下鉄東西線の駅である。駅番号はT 04。 都電荒川線の早稲田停留場は、当駅から直線距離で約600メートル離れた新目白通り沿いにあり、接続駅とはなっていない。","d":"東京都新宿区にある東京地下鉄の駅","t":"早稲田駅"},"市ケ谷":{"x":"市ケ谷駅および市ヶ谷駅は、東京都千代田区・新宿区にある、東日本旅客鉄道・東京地下鉄・東京都交通局の駅である。 JR東日本と東京メトロの駅は「市ケ谷」、都営地下鉄の駅は「市ヶ谷」と表記する。 所在地は、JR東日本が千代田区五番町、東京メトロが新宿区市谷田町一丁目、都営地下鉄が千代田区九段南四丁目である。","d":"東京都千代田区・新宿区にある東日本旅客鉄道・東京地下鉄・都営地下鉄の駅","t":"市ケ谷駅"},"明大前":{"x":"明大前駅は、東京都世田谷区松原二丁目にある、京王電鉄の駅。井の頭北管区所属で、管区長所在駅。","d":"東京都世田谷区松原にある京王電鉄の駅","t":"明大前駅"},"明治神宮前":{"x":"明治神宮前駅は、東京都渋谷区神宮前にある、東京地下鉄の駅。 旅客案内上は「明治神宮前〈原宿〉駅」と呼称される。","d":"東京都渋谷区にある東京地下鉄の駅","t":"明治神宮前駅"},"明治神宮":{"x":"明治神宮は、日本の東京都渋谷区にある神社。祭神は明治天皇と昭憲皇太后で、明治天皇崩御後の1920年11月1日に創建された。旧社格は官幣大社で、勅祭社。","d":"東京都渋谷区にある神社","t":"明治神宮"},"明治生命館":{"x":"明治生命館は、東京都千代田区丸の内二丁目にある建築物である。設計は岡田信一郎・捷五郎、構造設計は内藤多仲、施工は竹中工務店が手掛けた。重要文化財には「明治生命保険相互会社本社本館」として指定されている。","d":"東京都千代田区にある建築物","t":"明治生命館"},"旧東京音楽学校奏楽堂":{"x":"旧東京音楽学校 奏楽堂は、東京都台東区の上野公園にある、日本近代建築史における歴史的建造物。日本で最初に建てられた本格的な西洋式音楽ホールとされる。","d":"東京都台東区にある歴史的建造物","t":"旧東京音楽学校奏楽堂"},"旧芝離宮恩賜庭園":{"x":"旧芝離宮恩賜庭園は、東京都港区海岸にある都立庭園。大久保忠朝上屋敷の庭園楽寿園が始まりで、宮内庁管理の離宮を経て、大正13年東京市に下賜され、旧芝離宮恩賜庭園として公開された。","d":"日本の東京都港区にある公園","t":"旧芝離宮恩賜庭園"},"明治丸":{"x":"明治丸は、日本の船舶。灯台巡視船として日本政府がイギリスに発注し、天皇の乗る御召船や船員育成の練習船としても使用された。国の重要文化財に指定されている。","d":"日本の船舶","t":"明治丸"},"旧磯野家住宅":{"x":"旧磯野家住宅は、東京都文京区小石川に所在する歴史的建造物。国の重要文化財に指定されている。通称「銅御殿」。","t":"旧磯野家住宅"},"旧田中家住宅":{"x":"旧田中家住宅は、埼玉県川口市にある歴史的建造物である。2018年12月25日に国の重要文化財に指定された。川口市内では初の重要文化財指定物件である。","d":"埼玉県川口市にある歴史的建造物","t":"旧田中家住宅"},"有楽町":{"x":"有楽町駅は、東京都千代田区有楽町にある、東日本旅客鉄道・東京地下鉄の駅である。","d":"東京都千代田区にある東日本旅客鉄道・東京地下鉄の駅","t":"有楽町駅"},"朝霞台":{"x":"朝霞台駅は、埼玉県朝霞市東弁財一丁目にある、東武鉄道東上本線の駅である。駅番号はTJ 13。","d":"埼玉県朝霞市東弁財一丁目にある東武鉄道の駅","t":"朝霞台駅"},"明治神宮野球場":{"x":"明治神宮野球場は、東京都新宿区の明治神宮外苑に所在する野球場。宗教法人明治神宮が所有する。通称は「神宮球場」「神宮」。","d":"東京都新宿区にある野球場","t":"明治神宮野球場"},"朝霞":{"x":"朝霞駅は、埼玉県朝霞市本町二丁目にある、東武鉄道東上本線の駅である。駅番号はTJ 12。","d":"埼玉県朝霞市本町二丁目にある東武鉄道の駅","t":"朝霞駅"},"月島":{"x":"月島駅は、東京都中央区月島一丁目にある、東京地下鉄・東京都交通局の駅。 東京メトロの有楽町線と、都営地下鉄の大江戸線が乗り入れ、接続駅となっている。駅番号は、有楽町線がY 21、大江戸線がE 16。","d":"東京都中央区にある東京地下鉄・東京都交通局の駅","t":"月島駅"},"曳舟":{"x":"曳舟駅は、東京都墨田区東向島二丁目にある、東武鉄道の駅である。駅番号はTS 04。 駅名標に記載された副駅名は「東京曳舟病院前」。","d":"東京都墨田区東向島にある東武鉄道の駅","t":"曳舟駅"},"木場":{"x":"木場駅は、東京都江東区木場五丁目にある、東京地下鉄東西線の駅である。駅番号はT 13。","d":"東京都江東区にある東京地下鉄の駅","t":"木場駅"},"曙橋":{"x":"曙橋駅は、東京都新宿区住吉町にある、東京都交通局新宿線の駅である。駅番号はS 03。 駅名は近くに架かる「曙橋」に由来する。","d":"東京都新宿区住吉町にある東京都交通局の駅","t":"曙橋駅"},"昭和":{"x":"昭和駅は、神奈川県川崎市川崎区扇町にある、東日本旅客鉄道鶴見線の駅である。駅番号はJI 09。","d":"神奈川県川崎市川崎区扇町にある東日本旅客鉄道の駅","t":"昭和駅"},"有明コロシアム":{"x":"有明コロシアムは、東京都江東区有明二丁目にある東京都生活文化スポーツ局が所管するスタジアム。有明テニスの森公園の敷地内にあり、同施設のセンターコートである。","d":"東京都江東区にあるスタジアム","t":"有明コロシアム"},"昭和島":{"x":"昭和島駅は、東京都大田区昭和島二丁目にある東京モノレール羽田空港線の駅である。駅番号はMO 05。","d":"東京都大田区昭和島にある東京モノレールの駅","t":"昭和島駅"},"有明テニスの森":{"x":"有明テニスの森駅は、東京都江東区有明一丁目にある、ゆりかもめ東京臨海新交通臨海線の駅である。駅番号はU 13。","d":"東京都江東区有明にあるゆりかもめの駅","t":"有明テニスの森駅"},"朝倉彫塑館":{"x":"朝倉彫塑館は、東京都台東区谷中七丁目にある、彫刻・彫塑家朝倉文夫のアトリエ兼住居を改装した美術館である。朝倉の遺志に基づき遺族によって1967年(昭和42年)から公開され、1986年から台東区に移管されて区立朝倉彫塑館となった。現在は公益財団法人台東区芸術文化財団が運営・管理を行っている。","d":"東京都台東区にある朝倉文夫のアトリエを改装した美術館","t":"朝倉彫塑館"},"有明アリーナ":{"x":"有明アリーナは、日本の東京都江東区有明一丁目に所在する屋内競技施設、コンサート・イベントが行われる施設である。 2020年東京オリンピックおよびパラリンピックの競技会場として、2017年4月21日着工、2019年12月9日竣工。東京都が所有・管理する施設であるが、スポーツ競技施設としては国内初の公共施設等運営事業により、民間の営利企業が運営するスポーツ・文化拠点として、2022年8月20日に再…","d":"東京都江東区にある競技施設","t":"有明アリーナ"},"有明体操競技場":{"x":"有明体操競技場は、東京都江東区有明に在った競技施設。2020年東京オリンピックの体操競技会場として2019年10月完成。第62回BCS賞受賞。","d":"東京都江東区にある競技施設","t":"有明体操競技場"},"有明アーバンスポーツパーク":{"x":"有明アーバンスポーツパークは、東京都江東区有明一丁目にある施設。 2020年東京オリンピックの仮設競技会場として建設され、正式競技自転車競技のBMXレーシング、BMXフリースタイル、追加種目スケートボードが実施された。大会終了後はスケートボード施設を除いて撤去され、東京都と民間事業者によりアーバンスポーツを楽しめる場として整備し、2024年4月に一部先行開業、同年10月に全面開業した。","d":"東京都江東区に開設される競技場","t":"有明アーバンスポーツパーク"},"王子":{"x":"王子駅は、東京都北区王子一丁目にある、東日本旅客鉄道・東京地下鉄の駅である。 本項では、付近にある東京都交通局都電荒川線の王子駅前停留場についても記述する。","d":"東京都北区王子にある東日本旅客鉄道・東京地下鉄の駅、東京都交通局の停留場","t":"王子駅"},"本八幡":{"x":"本八幡駅は、千葉県市川市八幡二丁目にある、東日本旅客鉄道・東京都交通局の駅。市川市の行政・商業の中心に位置している。 東日本旅客鉄道の総武本線を走行する中央・総武緩行線と東京都交通局の都営地下鉄新宿線の2社2路線が乗り入れており、接続駅となっている。","d":"千葉県市川市八幡にある東日本旅客鉄道・東京都交通局の駅","t":"本八幡駅"},"東中野":{"x":"東中野駅は、東京都中野区東中野にある、東日本旅客鉄道・東京都交通局の駅である。中野区最東端の駅でもある。この駅から立川駅まで、中央本線は長い直線区間となる。","d":"東京都中野区にある東日本旅客鉄道・東京都交通局の駅","t":"東中野駅"},"本所吾妻橋":{"x":"本所吾妻橋駅は、東京都墨田区吾妻橋三丁目にある、東京都交通局浅草線の駅である。駅番号はA 19。 浅草通りと三ツ目通りの交差点の地下にあり、ターミナル駅である浅草駅と押上駅の間に位置している。","d":"東京都墨田区吾妻橋にある東京都交通局の駅","t":"本所吾妻橋駅"},"本郷三丁目":{"x":"本郷三丁目駅は、東京都文京区本郷二丁目にある、東京地下鉄・東京都交通局の駅である。","d":"東京都文京区にある東京地下鉄・東京都交通局の駅","t":"本郷三丁目駅"},"本駒込":{"x":"本駒込駅は、東京都文京区向丘二丁目にある、東京地下鉄南北線の駅である。駅番号はN 13。","d":"東京都文京区にある東京地下鉄の駅","t":"本駒込駅"},"本蓮沼":{"x":"本蓮沼駅は、東京都板橋区蓮沼町にある、東京都交通局三田線の駅である。駅番号はI 20。","d":"東京都板橋区蓮沼町にある東京都交通局の駅","t":"本蓮沼駅"},"東あずま":{"x":"東あずま駅は、東京都墨田区立花四丁目にある、東武鉄道亀戸線の駅である。駅番号はTS 42。墨田区最東端の駅。","d":"東京都墨田区立花にある東武鉄道の駅","t":"東あずま駅"},"目黒":{"x":"目黒駅は、東京都品川区上大崎にある、東日本旅客鉄道・東急電鉄・東京地下鉄・東京都交通局の駅である。 所在地は目黒区ではなく品川区であり、同区最北端の駅である。なお、目黒区にある駅で「目黒」を駅名に冠する駅は、中目黒駅である。","d":"東京都品川区にある駅","t":"目黒駅"},"目白":{"x":"目白駅は、東京都豊島区目白三丁目にある、東日本旅客鉄道山手線の駅である。 当駅には山手線電車のみが停車し、山手貨物線を走行する埼京線・湘南新宿ラインやその他の列車は通過する。また、特定都区市内制度における「東京都区内」および「東京山手線内」に属している。","d":"東京都豊島区にある東日本旅客鉄道の駅","t":"目白駅"},"神楽坂":{"x":"神楽坂駅は、東京都新宿区矢来町にある、東京地下鉄東西線の駅である。駅番号はT 05。","d":"東京都新宿区にある東京地下鉄の駅","t":"神楽坂駅"},"矢向":{"x":"矢向駅は、神奈川県横浜市鶴見区矢向六丁目にある、東日本旅客鉄道南武線の駅である。 駅番号はJN 03。南武線で唯一、横浜市内にある駅となっている。","d":"神奈川県横浜市鶴見区矢向にある東日本旅客鉄道の駅","t":"矢向駅"},"祐天寺":{"x":"祐天寺駅は、東京都目黒区祐天寺二丁目にある、東急電鉄東横線の駅である。駅番号はTY04。","d":"東京都目黒区祐天寺にある東急電鉄の駅","t":"祐天寺駅"},"神泉":{"x":"神泉駅は、東京都渋谷区神泉町にある、京王電鉄井の頭線の駅である。井の頭南管区所属。駅番号はIN02。","d":"日本の鉄道駅","t":"神泉駅"},"神保町":{"x":"神保町駅は、東京都千代田区神田神保町二丁目にある、東京都交通局・東京地下鉄の駅。 都営地下鉄の三田線と新宿線、東京メトロの半蔵門線が乗り入れ、接続駅となっている。3路線とも駅番号が与えられており、三田線がI 10、新宿線がS 06、半蔵門線がZ 07。","d":"東京都千代田区にある東京地下鉄・東京都交通局の駅","t":"神保町駅"},"祖師ヶ谷大蔵":{"x":"祖師ヶ谷大蔵駅は、東京都世田谷区祖師谷一丁目にある、小田急電鉄小田原線の駅である。駅番号はOH 13。","d":"東京都世田谷区祖師谷にある小田急電鉄の駅","t":"祖師ヶ谷大蔵駅"},"神谷町":{"x":"神谷町駅は、東京都港区虎ノ門五丁目にある、東京地下鉄日比谷線の駅である。駅番号はH 05。","d":"東京都港区にある東京地下鉄の駅","t":"神谷町駅"},"矢切":{"x":"矢切駅は、千葉県松戸市下矢切にある、北総鉄道北総線の駅である。駅番号はHS02。","d":"千葉県松戸市矢切にある北総鉄道の駅","t":"矢切駅"},"石神井公園":{"x":"石神井公園駅は、東京都練馬区石神井町三丁目にある、西武鉄道池袋線の駅である。駅番号はSI10。都立「石神井公園」に隣接。","d":"東京都練馬区石神井町にある西武鉄道の駅","t":"石神井公園駅"},"神田明神":{"x":"神田明神は、東京都千代田区外神田二丁目にある神社。正式名称は神田神社。 神田祭を行う神社として知られる。","d":"東京都千代田区の神社","t":"神田明神"},"石川台":{"x":"石川台駅は、東京都大田区東雪谷二丁目にある、東急電鉄池上線の駅である。駅番号はIK08。","d":"東京都大田区東雪谷にある東急電鉄の駅","t":"石川台駅"},"矢口渡":{"x":"矢口渡駅は、東京都大田区多摩川一丁目にある、東急電鉄東急多摩川線の駅である。駅番号はTM06。","d":"東京都大田区多摩川にある東急電鉄の駅","t":"矢口渡駅"},"皇居三の丸尚蔵館":{"x":"皇居三の丸尚蔵館は、東京都千代田区千代田の皇居東御苑内にある、独立行政法人国立文化財機構が運営する博物館施設。 昭和天皇崩御後の1989年6月に遺族の明仁と香淳皇后から寄贈され国庫に帰属した美術品を保存、研究、公開するための施設として、1992年9月に宮内庁が管理運営する博物館施設「三の丸尚蔵館」として皇居東御苑内に建設され、1993年11月3日に開館した。開館以後も皇族からの寄贈により収蔵品…","d":"東京都千代田区の皇居東御苑内にある博物館","t":"皇居三の丸尚蔵館"},"碣石調幽蘭第五":{"x":"『碣石調幽蘭第五』は、現存する最古の古琴の楽譜。通常の漢字を使った「文字譜」という方式で記している唯一の例でもある。 中国で失われ、日本にのみ残る佚存書である。","d":"古琴の楽曲","t":"碣石調幽蘭第五"},"秋冬山水図":{"x":"秋冬山水図、あるいは紙本墨画秋冬山水図は、室町時代の禅僧で著名な画家である雪舟による水墨画である。東京国立博物館が所蔵している。もともとは四季すべての絵が揃っていたと考えられているが、現在はそのうち2つ、冬景と一般的には秋景と考えられているものしか残っていない。","d":"台東区にある国宝（美術品）","t":"秋冬山水図"},"破墨山水図":{"x":"「破墨山水図」は、雪舟が室町時代の明応4年に描いた水墨画であり、山水画である。単に「山水図」とも。紙本墨画、大きさは縦147.9センチメートル、横32.7センチメートル。","d":"雪舟の水墨画","t":"破墨山水図"},"笹塚":{"x":"笹塚駅は、東京都渋谷区笹塚一丁目にある、京王電鉄京王線の駅。渋谷区内の鉄道駅では最も西に位置し「京王ライナー」「Mt.TAKAO号」を除く全列車が停車する。京王東管区所属。","d":"東京都渋谷区笹塚にある京王電鉄の駅","t":"笹塚駅"},"竹芝":{"x":"竹芝駅は、東京都港区海岸一丁目にある、ゆりかもめ東京臨海新交通臨海線の駅である。駅番号はU 03。竹芝桟橋の最寄駅。","d":"東京都港区海岸にあるゆりかもめの駅","t":"竹芝駅"},"竹ノ塚":{"x":"竹ノ塚駅は、東京都足立区竹の塚六丁目にある、東武鉄道伊勢崎線の駅である。「東武スカイツリーライン」の愛称区間に含まれている。駅番号はTS 14。","d":"東京都足立区竹の塚六丁目にある東武鉄道の駅","t":"竹ノ塚駅"},"築地市場":{"x":"築地市場駅は、東京都中央区築地五丁目にある、東京都交通局大江戸線の駅。駅番号はE 18。","d":"東京都中央区にある東京都交通局の駅","t":"築地市場駅"},"秩父宮ラグビー場":{"x":"秩父宮ラグビー場は、東京都港区の北青山二丁目にあるラグビー専用球技場。神宮外苑内の施設と間違われることもあるが、独立行政法人日本スポーツ振興センターが土地の所有権をもち、管理・運営を行っている。最大収容人員は25,194人。","d":"東京都港区にあるラグビー場","t":"秩父宮ラグビー場"},"立会川":{"x":"立会川駅は、東京都品川区東大井二丁目にある京浜急行電鉄本線の駅である。駅番号はKK06。","d":"東京都品川区東大井にある京浜急行電鉄の駅","t":"立会川駅"},"竹橋":{"x":"竹橋駅は、東京都千代田区一ツ橋一丁目にある、東京地下鉄東西線の駅である。駅番号はT 08。副駅名は毎日新聞社前。","d":"東京都千代田区にある東京地下鉄の駅","t":"竹橋駅"},"秋山":{"x":"秋山駅は、千葉県松戸市秋山一丁目にある、北総鉄道北総線の駅である。駅番号はHS04。副駅名は「聖徳小・光英VERITAS中高前」。","d":"千葉県松戸市秋山にある北総鉄道の駅","t":"秋山駅"},"穴守稲荷":{"x":"穴守稲荷駅は、東京都大田区羽田四丁目にある、京浜急行電鉄空港線の駅である。駅番号はKK14。駅名は近隣の穴守稲荷神社に由来する。","d":"東京都大田区羽田にある京浜急行電鉄の駅","t":"穴守稲荷駅"},"等々力":{"x":"等々力駅は、東京都世田谷区等々力三丁目にある、東急電鉄大井町線の駅である。1929年11月1日に開設した。駅番号はOM13。","d":"東京都世田谷区等々力にある東急電鉄の駅","t":"等々力駅"},"立石":{"x":"立石駅は、大分県杵築市山香町大字立石字乙丸にある、九州旅客鉄道日豊本線の駅である。 小倉駅から続いてきた複線は当駅で一旦合流し、隣の中山香駅まで単線となる。","d":"大分県杵築市山香町にある九州旅客鉄道の駅","t":"立石駅"},"第三台場":{"x":"台場公園は、東京都港区台場一丁目にある都立の都市公園である。 ペリーの黒船来航に備え東京湾上に作られた品川台場の跡地の一つである第三台場を利用して1928年7月7日に開園した。 お台場海浜公園から続く、東京湾に突き出た公園となっていて、周囲は石垣で囲まれ、その上に土手があり、中央が低い構造になっている。","d":"東京都の公園","t":"台場公園"},"秋萩帖":{"x":"秋萩帖は、平安時代の書の作品の一つで、草仮名の代表的遺品。巻子本、1巻。和歌48首と王羲之尺牘臨書11通が書写されている。","d":"日本の東京国立博物館に所蔵されている美術品（国宝）","t":"秋萩帖"},"秋葉原":{"x":"秋葉原駅は、東京都千代田区にある、東日本旅客鉄道・東京地下鉄・首都圏新都市鉄道の駅。 JR東日本の駅は外神田一丁目に、東京メトロと首都圏新都市鉄道の駅は神田佐久間町一丁目に、それぞれ所在する。","d":"日本の鉄道駅","t":"秋葉原駅"},"竜首水瓶":{"x":"竜首水瓶、国宝指定名称「金銀鍍龍首水瓶」は東京国立博物館所蔵の水瓶である。7-8世紀アジアにおける東西文化交流の象徴的な存在と評され、法隆寺献納宝物のひとつとして国宝に指定されている。","d":"東京国立博物館所蔵の国宝","t":"竜首水瓶"},"雑司が谷":{"x":"雑司が谷駅は、東京都豊島区雑司が谷二丁目にある、東京地下鉄副都心線の駅である。駅番号はF 10。","d":"東京都豊島区にある東京メトロ副都心線の駅","t":"雑司が谷駅"},"金銅水注":{"x":"墨台、水滴、匙は東京国立博物館所蔵の金工品である。奈良時代の文房具のあり方を知るうえで貴重な品であり、国宝に指定されている。","d":"東京国立博物館所蔵の金工品、国宝","t":"墨台、水滴、匙"}};
